INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('bg_rules_general', 'Battleground Basics', 'Battlegrounds are instanced PvP matches queued for from any Battlemaster NPC or the Battleground UI; most use standard 10-level brackets, though Alterac Valley opens at level 51 and Eye of the Storm, Strand of the Ancients, and Isle of Conquest all require at least level 61-71. Winning awards a burst of Honor plus a Mark of Honor for that battleground, spent at PvP quartermasters on battleground-specific gear, while losing still pays a smaller Honor reward. Patch 3.3.3 added the Random Battleground queue, replacing the old daily battleground quests with a bonus of Honor and Arena Points for the day''s first win; the featured ''Call to Arms'' battleground of the day pays that same bonus for queuing it directly instead of random.', 'battlegrounds,battlemaster,marks of honor,random battleground,call to arms,pvp brackets,random bg', 'pvp,battlegrounds,mechanic', '', '', 'how do i queue for bgs|where do i sign up for battlegrounds|what is random bg|random bg worth it|how does the random battleground work|what are marks of honor for|what is call to arms|do you get honor for losing a bg|what level can i start doing bgs|what are the bg level brackets|where do i spend marks of honor|what is the bonus for first win of the day|do the bg daily quests still exist|how do i get into a battleground|what level is av and eots and sota|which bg is the call to arms today');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('bg_warsong_gulch', 'Warsong Gulch', 'Warsong Gulch is a capture-the-flag battleground fought 10-a-side between Horde and Alliance camps in a fenced-off stretch of Ashenvale forest. The first team to carry the enemy''s flag back to their own flag room three times wins the match; a dropped flag resets after a short time if nobody picks it up. It is the lowest-level battleground, open to characters starting at level 10, and is often a new player''s first taste of organized PvP.', 'warsong gulch,wsg,capture the flag,flag room,ashenvale', 'pvp,battlegrounds,leveling', 'pvp', 'Put a Druid or Warrior on the flag with a healer behind them, and have most of the team kill the enemy flag carrier in the middle. The longer anyone holds a flag the more damage they take, so return it fast. Pick up the speed and restoration buffs when you see them; they decide most chases.', 'how does wsg work|what level is warsong gulch|how many caps to win wsg|wsg tips|how do i play warsong|where is wsg|how many players in wsg|what do i do with the flag in wsg|who should carry the flag in wsg|does a dropped flag reset|best class for wsg flag carrier|how do i win warsong gulch|is wsg good for new pvpers|what are the buffs in wsg');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('bg_arathi_basin', 'Arathi Basin', 'Arathi Basin is a resource-control battleground played 15-a-side over five capturable nodes -- the Blacksmith, Farm, Gold Mine, Lumber Mill, and Stables -- scattered across a stretch of the Arathi Highlands. Holding a node generates resources for your team every few seconds, so controlling more nodes at once matters more than any single capture. The first team to reach 1600 resources wins, or whichever team is ahead if the match runs its full length. It opens to characters at level 20.', 'arathi basin,ab,blacksmith,gold mine,lumber mill,stables', 'pvp,battlegrounds,leveling', 'pvp', 'Hold three nodes and you win: your base node, the Blacksmith in the middle, and the closest side node. Leave one or two players guarding each node instead of the whole team chasing kills. A node only flips after a short capture timer, so reaching it first with a group wins the fight.', 'how does ab work|what level is arathi basin|how do i win ab|ab tips|what are the nodes in ab|how many resources to win ab|how many people in arathi basin|which nodes should i hold in ab|how many nodes do you need in ab|where is arathi basin|how do you cap a node in ab|should i guard a node or chase kills in ab|farm lumber mill or blacksmith in ab|what level do you start ab');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('bg_alterac_valley', 'Alterac Valley', 'Alterac Valley is the largest battleground, fought up to 40-a-side across the long mountain valley connecting the Horde''s Frostwolf Keep to the Alliance''s Dun Baldar. Each side wins by pushing all the way to the enemy base and killing its final boss -- Alliance players kill Drek''Thar, Horde players kill Vanndar Stormpike -- while capturing towers and graveyards along the way weakens the enemy''s reinforcements. Its original Vanilla form could run for hours and required razing every enemy tower, bunker, and field commander first; a later redesign cut that down to a much faster rush on the boss, so a 3.3.5a match usually finishes in well under 20 minutes. It opens to characters at level 51, the highest minimum of any standard battleground.', 'alterac valley,av,drek''thar,vanndar stormpike,frostwolf keep,dun baldar', 'pvp,battlegrounds,endgame', 'pvp', 'Rush the enemy general with most of the team and send a few to burn towers on the way, since every standing enemy tower makes the general harder to kill. The Snowfall graveyard in the middle is the key one to hold. When both teams just race, the faster boss kill wins.', 'how does av work|what level is alterac valley|how do i win av|av tips|who is the last boss in av|how long does an av take|how many people in av|who do i kill in av as horde|who do i kill in av as alliance|do i need to burn towers in av|what is the snowfall graveyard|is av still hours long|where is dun baldar|how do you do alterac valley fast|how big is av|should i rush the general in av');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('bg_eye_of_the_storm', 'Eye of the Storm', 'Eye of the Storm is a 15-a-side battleground on a floating island in Netherstorm that blends flag-carrying with resource-node control. Teams fight over four capturable towers -- the Blood Elf Tower, Draenei Ruins, Mage Tower, and Fel Reaver Ruins -- that each generate points over time, and picking up the flag at the center of the map and holding it while your team controls nodes adds a large points bonus. The first team to 1600 points wins, or whichever team is ahead when the match''s timer expires. It was added in the Burning Crusade and opens to characters at level 61.', 'eye of the storm,eots,netherstorm,blood elf tower,draenei ruins,mage tower,fel reaver', 'pvp,battlegrounds,endgame', 'pvp', 'Take the two towers on your side, then fight for a third; with three or four towers held, carry the center flag to one of them for a big points bonus. A flag carried with only one tower is worth little, so get towers first.', 'how does eots work|what level is eye of the storm|how do i win eots|eots tips|where is eye of the storm|how many towers in eots|what does the flag do in eots|how many points to win eots|which towers should i hold in eots|when should i take the center flag in eots|how many players in eots|what are the towers in eots called|is eots a bg or arena|what level do you start eots');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('bg_strand_of_the_ancients', 'Strand of the Ancients', 'Strand of the Ancients is a 15-a-side attack-and-defend battleground off the southern coast of Northrend''s Dragonblight. The attacking team pilots siege engines and demolishers to smash through three walls of gates -- planting seaforium charges or ramming them down -- while defenders man turrets and cannons to hold them off, all racing a countdown clock that resets when a gate falls. If the attackers breach the final gate and capture the Titan Relic at the citadel''s core, the two teams swap roles for a second round, and whichever side broke through faster wins; a team that never breaches loses outright. It shipped with Wrath of the Lich King at launch and opens to characters at level 71.', 'strand of the ancients,sota,siege engine,demolisher,seaforium,relic,dragonblight', 'pvp,battlegrounds,endgame,vehicles', '', '', 'how does sota work|what level is strand of the ancients|sota tips|how do i win sota|how do you use the demolisher in sota|what is seaforium for|what do attackers do in strand|how many gates in sota|what is the titan relic|do teams swap sides in sota|where is strand of the ancients|how do i get a siege engine in sota|how many players in sota|what level do you start sota');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('bg_isle_of_conquest', 'Isle of Conquest', 'Isle of Conquest is a 40-a-side siege battleground on a Northrend island, added in patch 3.2. Both teams start by fighting over the Docks, Hangar, and Workshop, which unlock siege vehicles and an airship drop onto the enemy keep, while the Refinery and Quarry generate resources that fund reinforcements and boost siege damage. A team wins by breaching the enemy keep and killing its general -- Overlord Agmar for the Horde, High Commander Halford Wyrmbane for the Alliance -- or by grinding the other side''s reinforcement count to zero first. Alongside Strand of the Ancients, it is one of the two Wrath-era battlegrounds built around vehicle combat, and it opens to characters at level 71.', 'isle of conquest,ioc,overlord agmar,justicar mariel trueheart,siege vehicles,reinforcements,workshop,hangar', 'pvp,battlegrounds,endgame,vehicles', 'pvp', 'Take the Workshop for siege engines and the Hangar for the gunship, which drops you inside the enemy keep. Push siege onto one gate at a time with Glaive Throwers. Once the keep is open, kill the general fast before the enemy can retake their nodes.', 'how does ioc work|what level is isle of conquest|ioc tips|how do i win ioc|who is the general in ioc|what does the workshop do in ioc|what does the hangar do in ioc|how many players in ioc|when did ioc come out|what do refinery and quarry do in ioc|how do i get into the enemy keep in ioc|which node should i take first in ioc|how do reinforcements work in ioc|ioc vs sota difference');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_ingvar_the_plunderer', 'Ingvar the Plunderer', 'Ingvar the Plunderer is the final boss of Utgarde Keep, a level 69 to 72 five-player dungeon in Howling Fjord. He is resurrected once by a val''kyr after the first kill, so the fight is effectively two rounds.', 'ingvar the plunderer,utgarde keep', 'boss,dungeon', '', '', 'how do i beat ingvar|ingvar the plunderer tips|last boss of utgarde keep|who is the final boss in uk|ingvar comes back after dying?|why does ingvar res after first kill|where is ingvar|ingvar fight guide uk');
