INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_the_prophet_tharon_ja', 'The Prophet Tharon''ja', 'The Prophet Tharon''ja is the final boss of Drak''Tharon Keep, a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. Partway through he turns the whole group into skeletons with their own short action bar, then turns them back.', 'the prophet tharon''ja,drak''tharon keep', 'boss,dungeon', '', '', 'how to beat tharon ja|tharonja tips|last boss of drak tharon keep|tharonja skeleton phase what do|where is prophet tharon''ja|final boss in dtk|what does tharon''ja do|tharon ja fight guide');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_king_dred', 'King Dred', 'King Dred is the third boss of Drak''Tharon Keep, a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. He is a devilsaur kept by the Drakkari, and the raptors around him can be pulled in with the fight.', 'king dred,drak''tharon keep', 'boss,dungeon', '', '', 'how to beat king dred|king dred tips dtk|third boss of drak''tharon keep|what does king dred do|king dred raptors pulled in?|where is dred|dred devilsaur fight guide');
