INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_sjonnir_the_ironshaper', 'Sjonnir The Ironshaper', 'Sjonnir The Ironshaper is the final boss of Halls of Stone, a level 77 to 79 five-player dungeon in The Storm Peaks. He is reached after the Tribunal of Ages escort, and floods the room with iron and earthen adds.', 'sjonnir the ironshaper,halls of stone', 'boss,dungeon', '', '', 'how to beat sjonnir|sjonnir tips halls of stone|last boss of halls of stone|sjonnir adds iron earthen|where is sjonnir|final boss hos who|sjonnir fight after tribunal');
