INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_loken', 'Loken', 'Loken is the final boss of Halls of Lightning, a level 79 to 80 five-player dungeon in The Storm Peaks. The fight is a damage race against Lightning Nova and a pulse that hits harder the further away you stand.', 'loken,halls of lightning', 'boss,dungeon', '', '', 'how to beat loken|loken tips halls of lightning|last boss of halls of lightning|loken lightning nova what do|loken pulse stand close|where is loken|final boss hol who|loken fight guide hol');
