INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_king_ymiron', 'King Ymiron', 'King Ymiron is the final boss of Utgarde Pinnacle, a level 79 to 80 five-player dungeon in Howling Fjord. He is the vrykul king, and he draws power from the spirits of the old kings in the burial boats around the room.', 'king ymiron,utgarde pinnacle', 'boss,dungeon', '', '', 'how to beat ymiron|king ymiron tips pinnacle|last boss of utgarde pinnacle|ymiron spirits boats what do|where is king ymiron|final boss of up|ymiron vrykul king fight guide');
