INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_svala_sorrowgrave', 'Svala Sorrowgrave', 'Svala Sorrowgrave is the first boss of Utgarde Pinnacle, a level 79 to 80 five-player dungeon in Howling Fjord. She sacrifices a player on an altar partway through and must be interrupted or healed past it.', 'svala sorrowgrave,utgarde pinnacle', 'boss,dungeon', '', '', 'how to beat svala|svala sorrowgrave tips|first boss of utgarde pinnacle|svala sacrifice altar what do|where is svala|svala fight guide pinnacle|who is svala sorrowgrave');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_ley_guardian_eregos', 'Ley-Guardian Eregos', 'Ley-Guardian Eregos is the final boss of The Oculus, a level 79 to 80 five-player dungeon in Coldarra, in the Borean Tundra. He is fought entirely from drake mounts, which is why the dungeon has the reputation it does.', 'ley-guardian eregos,the oculus', 'boss,dungeon', '', '', 'how to beat eregos|eregos tips oculus|last boss of the oculus|why is oculus hated|eregos drake fight guide|where is ley guardian eregos|final boss of oculus who|oculus last boss drakes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_mal_ganis', 'Mal''Ganis', 'Mal''Ganis is the final boss of The Culling of Stratholme, a level 79 to 80 five-player dungeon in the Caverns of Time in Tanaris. He is the dreadlord who baits Arthas into the purge, and he escapes rather than dying.', 'mal''ganis,the culling of stratholme', 'boss,dungeon', '', '', 'how to beat malganis|mal''ganis tips culling|last boss of culling of stratholme|why does malganis escape|where is mal ganis|final boss cos who|malganis dreadlord arthas fight|culling last boss guide');
