INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('boss_high_inquisitor_whitemane', 'High Inquisitor Whitemane', 'High Inquisitor Whitemane is the final boss of the Cathedral wing of Scarlet Monastery, a level 29 to 40 five-player dungeon in Tirisfal Glades. She resurrects Scarlet Commander Mograine once, so both have to be brought down together.', 'high inquisitor whitemane,scarlet monastery', 'boss,dungeon', '', '', 'how to beat whitemane|whitemane tips sm cath|last boss of scarlet cathedral|where is high inquisitor whitemane|who is whitemane|whitemane resurrects mograine|kill mograine and whitemane together|sm cathedral last boss guide');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_rules_general', 'Capital Cities', 'Capital cities are safe hubs, not leveling ground. They contain no hostile mobs to kill and no quest grinding areas. Dueling is disabled inside city limits, so players who want to duel step outside the gates first. Every capital has a bank, auction house, mailbox, inn with an innkeeper for setting your hearthstone, flight master, stable master, guild master, barber shop, and the full set of class and profession trainers. Resting in a city accumulates rested experience faster than resting in the wild.', 'capital,capital city,city,cities,cannot duel,dueling disabled,duel,rested experience,barber shop', 'city,mechanics,safe_zone', '', '', 'do cities have a bank|can i duel in a city|why cant i duel in stormwind|where can i set my hearthstone|do capitals have an auction house|can i level in a capital city|are there mobs in cities|where do i learn my class skills|do all capitals have trainers|where is the barber shop|does resting in a city give rested xp|where do i find the flight master in a city|can i find a stable master in a capital|where do i duel if not in the city');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_stormwind', 'Stormwind City', 'Stormwind City is the human capital and the main Alliance hub in the Eastern Kingdoms, sitting in the north of Elwynn Forest. It is divided into the Trade District, Old Town, the Mage Quarter, Cathedral Square, the Dwarven District, and the Park, with the Valley of Heroes at the front gates. King Varian Wrynn rules from Stormwind Keep. The Deeprun Tram runs underground from the Dwarven District to Ironforge, and the harbor carries boats to Northrend and Kalimdor.', 'stormwind,stormwind city,human capital,alliance capital,trade district,old town,mage quarter,cathedral square,dwarven district,valley of heroes,stormwind keep,varian wrynn,deeprun tram,stormwind harbor,sw', 'city,alliance,eastern_kingdoms', '', '', 'how do i get to stormwind|where is stormwind|what is the human capital|where is the deeprun tram|how do i get to ironforge from stormwind|how do i get to northrend from stormwind|where is the stormwind harbor|where is the boat to kalimdor in stormwind|what districts are in stormwind|who rules stormwind|where is the dwarven district|where is the trade district|where is the mage quarter|where is the valley of heroes|what is old town in sw');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_ironforge', 'Ironforge', 'Ironforge is the dwarven capital, carved into the mountain of Dun Morogh and centered on the Great Forge. Its districts include the Commons, Tinker Town, the Mystic Ward, the Military Ward, and the Hall of Explorers, which houses the Explorers'' League and the museum. King Magni Bronzebeard rules here. The Deeprun Tram connects Ironforge to Stormwind, and the gryphon roost handles Alliance flight paths across the Eastern Kingdoms.', 'ironforge,dwarven capital,dwarf capital,great forge,tinker town,mystic ward,military ward,hall of explorers,explorers league,magni bronzebeard,deeprun tram,gryphon roost', 'city,alliance,eastern_kingdoms', '', '', 'how do i get to ironforge|where is ironforge|what is the dwarf capital|where is the deeprun tram|how do i get to stormwind from ironforge|where is tinker town|where is the great forge|where is the hall of explorers|who rules ironforge|where is the gryphon master in if|what districts are in ironforge|where is the mystic ward|where is the military ward|where is the explorers league');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_darnassus', 'Darnassus', 'Darnassus is the night elf capital, built among the branches of Teldrassil across the sea in northern Kalimdor. Its districts include the Temple of the Moon, the Cenarion Enclave, the Craftsmen''s Terrace, the Warrior''s Terrace, and the Tradesmen''s Terrace. High Priestess Tyrande Whisperwind leads from the temple. Players reach it through the portal at Rut''theran Village at the base of the tree, which also connects by boat to Darkshore and Azuremyst Isle.', 'darnassus,night elf capital,temple of the moon,cenarion enclave,craftsmens terrace,warriors terrace,tyrande whisperwind,rutheran village,teldrassil capital', 'city,alliance,kalimdor', '', '', 'how do i get to darnassus|where is darnassus|what is the night elf capital|how do i get to darnassus from teldrassil|where is the portal to darnassus|where is rut''theran village|who rules darnassus|where is the temple of the moon|where is the cenarion enclave|what districts are in darnassus|where is the craftsmen''s terrace|where is the warrior''s terrace|how do i get to darnassus from the exodar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_exodar', 'The Exodar', 'The Exodar is the draenei capital, a crashed naaru vessel embedded in the western edge of Azuremyst Isle off the coast of Kalimdor. Its wings include the Trader''s Tier, the Crystal Hall, the Vault of Lights, and the Seat of the Naaru, where Prophet Velen resides. It is the least-trafficked Alliance capital, and a boat from Azuremyst Isle connects it to Darnassus and the rest of Kalimdor.', 'exodar,the exodar,draenei capital,traders tier,crystal hall,vault of lights,seat of the naaru,velen,prophet velen,azuremyst capital', 'city,alliance,kalimdor', '', '', 'how do i get to the exodar|where is the exodar|what is the draenei capital|how do i get to darnassus from the exodar|where is the boat from the exodar|who is prophet velen|where is the vault of lights|where is the trader''s tier|where is the crystal hall|what is the seat of the naaru|what is the least visited alliance city|what wings does the exodar have|where is the exodar on the map');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_orgrimmar', 'Orgrimmar', 'Orgrimmar is the orc capital and the main Horde hub, built into the canyons of Durotar. Its districts are the Valley of Strength, the Valley of Honor, the Valley of Wisdom, the Valley of Spirits, the Drag, and the Cleft of Shadow, where warlocks and rogues train and the entrance to Ragefire Chasm sits. Warchief Thrall rules from Grommash Hold. Zeppelin towers outside the gates run to Undercity, Grom''gol in Stranglethorn, Thunder Bluff, and Northrend.', 'orgrimmar,orc capital,horde capital,valley of strength,valley of honor,valley of wisdom,valley of spirits,cleft of shadow,the drag,grommash hold,thrall,warchief,zeppelin tower,og,org', 'city,horde,kalimdor', '', '', 'how do i get to orgrimmar|where is orgrimmar|what is the orc capital|where is the zeppelin to undercity|where is the zeppelin to northrend|where is the zeppelin to stranglethorn|where is the zeppelin to thunder bluff|where is ragefire chasm|where do warlocks train in og|where do rogues train in orgrimmar|who rules orgrimmar|what is the cleft of shadow|where is grommash hold|what are the valleys in orgrimmar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_thunder_bluff', 'Thunder Bluff', 'Thunder Bluff is the tauren capital, a cluster of mesas rising above the plains of Mulgore and joined by rope bridges and wooden elevators. Elder Rise, Spirit Rise, and Hunter Rise ring the central High Rise, where Cairne Bloodhoof leads. It is the Horde''s center for shamanism, druidism, and leatherworking, and the long fall from its bridges is a hazard for players who miss the lift.', 'thunder bluff,tauren capital,mulgore capital,elder rise,spirit rise,hunter rise,high rise,cairne bloodhoof,mesa,rope bridges,elevators,tb', 'city,horde,kalimdor', '', '', 'how do i get to thunder bluff|where is thunder bluff|what is the tauren capital|how do i get to the tauren capital|is thunder bluff in mulgore|where is the elevator in thunder bluff|who rules thunder bluff|where is the high rise|where do shaman train in tb|where do druids train in thunder bluff|can i fall off thunder bluff|where is hunter rise|where is spirit rise|where is elder rise');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_undercity', 'Undercity', 'Undercity is the Forsaken capital, built in the catacombs beneath the ruined city of Lordaeron in Tirisfal Glades. It is laid out as a ring of quarters around a central well: the Trade Quarter, the War Quarter, the Magic Quarter, the Rogues'' Quarter, and the Apothecarium, where Lady Sylvanas Windrunner and the Royal Apothecary Society plot. A zeppelin tower outside the ruins connects it to Orgrimmar and Northrend.', 'undercity,forsaken capital,undead capital,lordaeron,ruins of lordaeron,trade quarter,war quarter,magic quarter,rogues quarter,apothecarium,sylvanas windrunner,royal apothecary society,uc', 'city,horde,eastern_kingdoms', '', '', 'how do i get to undercity|where is undercity|what is the forsaken capital|where is the zeppelin to orgrimmar from undercity|where is the zeppelin to northrend from undercity|where is the apothecarium|who rules undercity|where is sylvanas|where is the trade quarter|where is the war quarter|where is the magic quarter|where is the rogues quarter|how do i get to undercity from tirisfal glades|where is the undercity zeppelin tower');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_silvermoon', 'Silvermoon City', 'Silvermoon City is the blood elf capital in northern Eversong Woods, the last great city of Quel''Thalas. Its districts include the Royal Exchange, the Bazaar, the Walk of Elders, and Sunfury Spire, where Lor''themar Theron rules as regent. It is the most remote Horde capital: players usually arrive through the orb of translocation linking Undercity to Silvermoon, rather than travelling overland through the Ghostlands.', 'silvermoon,silvermoon city,blood elf capital,quelthalas,royal exchange,the bazaar,walk of elders,sunfury spire,lorthemar theron,orb of translocation', 'city,horde,eastern_kingdoms', '', '', 'how do i get to silvermoon|where is silvermoon|what is the blood elf capital|how do i get from undercity to silvermoon|where is the orb of translocation|where is the undercity portal to silvermoon|who rules silvermoon|where is sunfury spire|where is the royal exchange|what districts are in silvermoon|where is the bazaar|where is the walk of elders|how do i get to silvermoon from the ghostlands|who is lor''themar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_shattrath', 'Shattrath City', 'Shattrath City is the neutral hub of Outland, in western Terokkar Forest, and a sanctuary where all PvP, including dueling, is disabled. Reach Outland through the Dark Portal in the Blasted Lands; Hellfire Peninsula, Zangarmarsh and Terokkar Forest are the usual order. Once you know Shattrath''s flight path, Honor Hold and Thrallmar fly straight there, and mages learn Teleport: Shattrath at 60 and Portal at 65. The Terrace of Light holds A''dal and the portals to your capitals; the Aldor or Scryers choice is made here.', 'shattrath,shattrath city,outland hub,neutral city,sanctuary,no pvp,terrace of light,lower city,adal,the shatar,aldor,scryers,terokkar,shatt', 'city,neutral,outland,sanctuary', '', '', 'how do i get to shattrath|where is shattrath|how do i get to shattrath city|where are the portals to capital cities in shattrath|where is a''dal|what is the terrace of light|can i duel in shattrath|aldor or scryers|what happens if i pick aldor|where do i choose aldor or scryers|is shattrath neutral|where is the lower city|can i pvp in shattrath|where do i get a portal to stormwind in shattrath|how do i get to shattrath from stormwind|how do i get to shattrath from orgrimmar|how do i get to shattrath as horde|how do i get to shattrath as alliance|is there a flight path to shattrath|what level is the mage teleport to shattrath|how do i get to outland|how do i get to shattrath from the dark portal|how do i get from honor hold to shattrath|how do i get from thrallmar to shattrath|can i get to shattrath from dalaran|shatt how do i get there');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('city_dalaran', 'Dalaran', 'Dalaran is the neutral city of Northrend, floating above Crystalsong Forest, and a sanctuary: faction combat and dueling are off except in the Underbelly sewers. Alliance sail to Valiance Keep or Valgarde and Horde ride zeppelins to Warsong Hold or Vengeance Landing; once you know its flight path, flight masters link to it, and mages learn Teleport: Dalaran at 71 and Portal at 74. Portals to your capitals, Shattrath and Wintergrasp are in your faction''s enclave, the Silver Enclave or Sunreaver''s Sanctuary. Rhonin leads the Kirin Tor.', 'dalaran,northrend hub,floating city,neutral city,sanctuary,kirin tor,runeweaver square,violet citadel,rhonin,the underbelly,dalaran sewers,crystalsong forest,dal', 'city,neutral,northrend,sanctuary', '', '', 'how do i get to dalaran|where is dalaran|what level do i need for dalaran|where are the portals in dalaran|where is the portal to stormwind in dalaran|can i duel in dalaran|where is the violet citadel|who is rhonin|where is the underbelly|is the dalaran underbelly pvp|is dalaran neutral|can i get ganked in dalaran|where is dalaran in northrend|how do alliance get to dalaran|how do horde get to dalaran|how do i get to dalaran as alliance|how do i get to dalaran as horde|how do i get to dalaran from stormwind|how do i get to dalaran from orgrimmar|is there a flight path to dalaran|what level is the mage teleport to dalaran|where is the silver enclave|where is sunreavers sanctuary|how do i get to dalaran from shattrath|how do i get to dalaran from northrend boat|can i portal to dalaran|where is the portal to wintergrasp in dalaran');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_warrior', 'Warrior Class', 'Warriors are melee fighters who run on rage, built by dealing and taking damage, and switch between Battle, Defensive and Berserker stances. Their trees are Arms and Fury for damage and Protection for tanking. They wear mail until level 40 and plate after, and every race except blood elves can be one.', 'warrior,rage,stance,stances,battle stance,berserker stance,defensive stance,charge,intercept,taunt,heroic strike,execute,challenging shout', 'class,melee,tank,dps,versatile', '', '', 'what does a warrior do|should i roll a warrior|how does rage work for warriors|what are the warrior stances|warrior stance dance how|when do warriors get plate|do warriors wear mail or plate|what are the warrior talent trees|which races can be warrior|can blood elves be warriors|how does warrior get rage|is warrior fun to play|warrior tank or dps|what does charge do warr|is arms fury or prot better for warrior|what is berserker stance for');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_paladin', 'Paladin Class', 'Paladins are plate-wearing holy warriors who run on mana: Holy heals, Protection tanks and Retribution deals melee damage. They buff the group with blessings and auras, use seals and judgements in combat, and carry Divine Shield. The races that can be paladins are humans, dwarves, draenei and blood elves.', 'paladin,pally,blessing,blessings,judgement,judgment,divine shield,seal of', 'class,hybrid,healer,tank,dps', '', '', 'what does a paladin do|should i roll a pally|which races can be paladin|can night elves be paladins|what are pally blessings|how do seals and judgement work|what are the paladin talent trees|can pallys tank and heal|pally armor type|what is divine shield|is pally a good class|what does a paladin use for resource|can orcs be pallies|what are auras for pally|holy prot ret which is which for pally|what races can play pally');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_hunter', 'Hunter Class', 'Hunters fight at range with bows, guns or crossbows, which still use arrows or bullets in Wrath, and keep a tamed beast as a pet. They run on mana, wear mail from level 40, and use traps, aspects and Feign Death. Their trees are Beast Mastery, Marksmanship and Survival.', 'hunter,huntard,traps,feign death,misdirection,aspect of the hawk,aspect of the dragonhawk,deterrence,disengage', 'class,ranged,dps,pets,utility', '', '', 'what does a hunter do|should i roll a hunter|do hunters still need arrows|do hunters use ammo in wrath|what is feign death|what are hunter traps|how does a hunter pet work|when do hunters get mail armor|what are the hunter talent trees|what is misdirection|what are aspects for hunters|hunter bow gun or crossbow|is hunter easy to level|what is deterrence|why do people call hunters huntards|what does disengage do');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_rogue', 'Rogue Class', 'Rogues are leather-wearing melee fighters who run on energy and build combo points to spend on finishers like Eviscerate. They can stealth, sap, pick locks and apply poisons bought from poison vendors. Their trees are Assassination, Combat and Subtlety.', 'rogue,energy,combo points,stealth,vanish,sprint,backstab,sap,kidney shot,eviscerate,cloak of shadows', 'class,melee,dps,stealth,control', '', '', 'what does a rogue do|should i roll a rogue|how do combo points work|what is eviscerate|what armor do rogues wear|can rogues pick locks|what do rogues use for resource|how do rogue poisons work|where do i buy poisons rogue|what are the rogue talent trees|what is sap|is rogue fun|how does rogue stealth work|what is energy for rogue|assassination combat subtlety which is which|what are finishers rogue');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_priest', 'Priest Class', 'Priests wear cloth and run on mana: Discipline and Holy heal and Shadow deals damage from Shadowform. Their utility includes Power Word: Fortitude, Fear Ward, Mind Control and resurrection. The races that can be priests are humans, dwarves, night elves, draenei, undead, trolls and blood elves.', 'priest,mind control,psychic scream,fear ward,power word fortitude,shackle undead', 'class,caster,healer,dps,utility', '', '', 'what does a priest do|should i roll a priest|what races can be priest|can orcs be priests|priest armor type|what is shadowform|what is fear ward|what is mind control|can priests res people|what is power word fortitude|what are the priest talent trees|can a priest dps|disc holy shadow which is which|is priest good for healing|can tauren be priests|what does priest bring to a group');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_shaman', 'Shaman Class', 'Shamans run on mana, wear mail from level 40, and drop totems that buff the group; Bloodlust, called Heroism for the Alliance, speeds up the whole party. Elemental casts, Enhancement fights in melee and Restoration heals, and Reincarnation lets them revive themselves. Only four races can be shamans: orcs, tauren, trolls and draenei.', 'shaman,shammy,totem,totems,bloodlust,heroism,reincarnation,ankh,ghost wolf,purge', 'class,hybrid,healer,dps,elemental', '', '', 'what does a shaman do|should i roll a shammy|what is bloodlust|what is heroism for alliance|what races can be shaman|can humans be shamans|can gnomes play shaman|how do totems work|what is reincarnation|when do shamans get mail|what are the shaman talent trees|elemental enhancement resto which is which|can shammies heal and dps|alliance shaman which race|why is shaman wanted in every group|what does shaman bring to a raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_mage', 'Mage Class', 'Mages wear cloth, like warlocks and priests, and run on mana: Arcane, Fire and Frost are their three damage trees. They polymorph enemies, conjure food and water, teleport themselves to capitals from level 20 and open portals for others from 40.', 'mage,polymorph,sheep,teleport,blink,counterspell', 'class,caster,ranged,dps,control', '', '', 'what does a mage do|should i roll a mage|what is polymorph|how do mages get food and water|when do mages get teleports|when can mages make portals|what are the mage talent trees|what armor do mages wear|what resource do mages use|arcane fire frost which is which for mage|is mage easy to level|mage teleport to capital city level|can mages open portals|what is conjure water|what level do mage portals unlock|is mage a good class');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_warlock', 'Warlock Class', 'Warlocks wear cloth, like mages and priests, and run on mana plus soul shards. Affliction, Demonology and Destruction are their three damage trees, and they summon demons such as the imp, voidwalker, succubus and felhunter. They make healthstones and soulstones and can summon party members with Ritual of Summoning, which needs two helpers to click the portal.', 'warlock,lock,summon,summoning,soulstone,healthstone', 'class,caster,dps,demonic,control', '', '', 'what does a warlock do|should i roll a lock|what demons can warlocks summon|what are soul shards|what is a healthstone|what is a soulstone|how does ritual of summoning work|how many people do you need for a summon|what are the warlock talent trees|can locks summon people|imp voidwalker succubus felhunter which for lock|what armor do warlocks wear|affliction demo destro which is which|is warlock fun|how to summon party members lock|what does a warlock bring to a group|need a summon|can a lock summon me|any locks for a summon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_druid', 'Druid Class', 'Druids shapeshift and wear leather: Balance casts in Moonkin Form, Feral fights as a cat or tanks as a bear, and Restoration heals, the only class that can tank, heal or deal damage in either melee or ranged. Rebirth revives an ally in combat and Innervate restores mana. Only two races can be druids: night elves and tauren.', 'druid,shapeshift,shapeshifting,travel form,flight form,innervate,rebirth,brez,battle rez,hibernate,cyclone,entangling roots', 'class,hybrid,versatile,shapeshift', '', '', 'what does a druid do|should i roll a druid|what races can be druid|can humans be druids|what are druid forms|what is moonkin form|druid tank heal or dps|what is rebirth|what is innervate|can druid do everything|what are the druid talent trees|cat form or bear form|balance feral resto which is which|druid armor type|can trolls be druids|how does druid combat res work');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_classes_death_knight', 'Death Knight Class', 'Death Knights are Wrath''s plate-wearing hero class: they start at level 55 in Ebon Hold and need a level 55 character on the realm to create. They run on runes and runic power, and Blood, Frost and Unholy can each tank or deal damage. Death Grip pulls an enemy to them, and every race can be one.', 'death knight,dk,deathknight,death grip,anti magic shell,antimagic shell,death coil,icy touch,plague strike,blood strike,army of the dead,lichborne,dks', 'class,melee,tank,dps,undead', '', '', 'what does a death knight do|should i roll a dk|how do i make a death knight|what level do dks start at|do i need a level 55 to make a dk|where do death knights start|what is ebon hold|what is death grip|what are runes and runic power|can dk tank|what are the dk talent trees|what races can be death knights|blood frost unholy which is which|why cant i create a death knight|what armor do dks wear|is dk good for leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_factions_alliance', 'Alliance Faction', 'The Alliance is one of the two major factions in Azeroth, consisting of noble and honorable races united against the Horde. Member races include Humans, Dwarves, Gnomes, Night Elves, and Draenei. The Alliance values honor, tradition, and protecting Azeroth from threats. Their capital cities include Stormwind, Ironforge, Darnassus, and the Exodar. Alliance players work together to maintain peace and order.', 'alliance,alliance races,alliance side,alliance capitals', 'faction,alliance,races,cities', '', '', 'what races are alliance|which races are in the alliance|what are the alliance capital cities|what does the alliance stand for|how many races does alliance have|is draenei alliance|alliance cities list|what is the alliance|which cities can alliance go to|are gnomes alliance or horde|what factions are there|alliance vs horde what is the difference|alliance playable races|is the exodar an alliance city');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_factions_horde', 'Horde Faction', 'The Horde is a powerful faction of warrior races who fight for survival and strength. Member races include Orcs, Trolls, Tauren, Undead (Forsaken), and Blood Elves. The Horde values strength, honor in battle, and protecting their way of life. Their capital cities include Orgrimmar, Thunder Bluff, Undercity, and Silvermoon City. Horde players are fierce warriors who respect strength and combat prowess.', 'horde,horde races,horde side,horde capitals,for the horde', 'faction,horde,races,cities', '', '', 'what races are horde|which races are in the horde|what are the horde capital cities|what does the horde stand for|how many races does horde have|are blood elves horde|horde cities list|what is the horde|which cities can horde go to|are undead horde or alliance|horde playable races|is silvermoon a horde city|is thunder bluff horde|alliance vs horde what is the difference');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_humans', 'Human Race', 'Humans are the most widespread and adaptable race in Azeroth, known for their resilience and determination. They founded the Alliance and built the mighty kingdom of Stormwind. Humans excel at all classes and are known for their diplomacy and leadership. Key traits include the Human Spirit (+3% Spirit) and Diplomacy (+10% reputation gains with every faction). Humans start in Elwynn Forest and have access to mounts at level 20.', 'human,humans,human racial,diplomacy,every man for himself,human spirit', 'race,alliance,human,versatile', '', '', 'what are humans good at|should i roll a human|what is the human racial|what does human spirit do|what is diplomacy racial|where do humans start|what is the human starting zone|human racial pve or pvp|human mount level|is human good for any class|what is the human spirit bonus|who founded the alliance|is human a good race|does diplomacy give extra rep');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_orcs', 'Orc Race', 'Orcs are fierce and honorable warriors from Draenor, brought to Azeroth through the Dark Portal. They form the backbone of the Horde and value strength and combat prowess above all. Orcs have Command (+5% pet damage), Axe Specialization, Hardiness (reduced stun duration), and the activated Blood Fury racial. They start in Durotar and have a rich history of shamanism and warfare. Notable orcs include Thrall, Garrosh Hellscream, and Grommash Hellscream.', 'orc,orcs,orc racial,blood fury,hardiness,axe specialization', 'race,horde,orc,warrior', '', '', 'what are orcs good at|should i roll an orc|what is blood fury|what is the orc racial|what does command do orc|where do orcs start|orc starting zone|is orc good for warrior|is orc good for pvp|orc hardiness stun resist|what is axe specialization|orc vs troll which racial is better|who is thrall|orc hunter or lock racial|is orc a good race|what is the best race for horde warrior');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_dwarves', 'Dwarf Race', 'Dwarves are stout, bearded mountain dwellers known for their craftsmanship and love of ale. They are master miners, blacksmiths, and engineers. Dwarves have Gun Specialization, Mace Specialization, passive Frost Resistance, and the activated Stoneform racial, which cures poison, disease, and bleed effects. They start in Dun Morogh and are fiercely loyal to the Alliance. Dwarves excel at warrior, priest, and hunter classes. Famous dwarves include King Magni Bronzebeard and Muradin Bronzebeard.', 'dwarf,dwarves,dwarf racial,stoneform,gun specialization,find treasure', 'race,alliance,dwarf,craftsman', '', '', 'what are dwarves good at|should i roll a dwarf|what is stoneform|what is the dwarf racial|what does stoneform cure|where do dwarves start|dwarf starting zone|is dwarf good for hunter|is dwarf good for priest|dwarf gun specialization|dwarf frost resist|is dwarf good for pvp|who is muradin|does stoneform remove bleeds|what is the best alliance race for hunter|is dwarf a good race');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_night_elves', 'Night Elf Race', 'Night Elves are ancient, immortal beings who protect the natural world of Azeroth. They are master druids, hunters, and warriors with a deep connection to nature. Night Elves have Quickness (melee and ranged attackers are 2% less likely to hit them), Nature Resistance (2% less likely to be hit by Nature spells), and Shadowmeld, an activated near-invisibility used while standing still; on death they briefly become a fast-moving wisp. They start on the sacred tree of Teldrassil and are devoted to Elune. Night Elves excel at druid, hunter, and priest classes. Key figures include Tyrande Whisperwind and Malfurion Stormrage.', 'night elf,night elves,nelf,nelfs,night elf racial,shadowmeld,quickness,wisp spirit,elune', 'race,alliance,night elf,nature', '', '', 'what are night elves good at|should i roll a night elf|what is shadowmeld|what is the night elf racial|where do night elves start|night elf starting zone|is teldrassil the night elf zone|is night elf good for druid|is night elf good for hunter|what is quickness racial|what happens when a night elf dies|is night elf good for pvp|who is tyrande|what does shadowmeld do|night elf rogue worth it|is nelf a good race');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_tauren', 'Tauren Race', 'Tauren are massive, peaceful nomads from the plains of Mulgore, devoted to the spirits of nature. They are natural shamans and druids with a deep spiritual connection to the elements. Tauren have Endurance (+5% base health), War Stomp (an activated stun on nearby enemies), Cultivation (+15 Herbalism skill), and Nature Resistance (2% less likely to be hit by Nature spells). They start in Mulgore and have a rich culture of storytelling and herbalism. Tauren excel at druid, shaman, and warrior classes. Cairne Bloodhoof is the tauren high chieftain, ruling from Thunder Bluff.', 'tauren,tauren racial,war stomp,endurance,cultivation', 'race,horde,tauren,spiritual', '', '', 'what are tauren good at|should i roll a tauren|what is war stomp|what is the tauren racial|where do tauren start|tauren starting zone|is mulgore the tauren zone|is tauren good for druid|is tauren good for shaman|what does endurance do tauren|tauren herbalism bonus|is tauren good for pvp|who is cairne|does war stomp stun|best horde race for warrior|is tauren a good race');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_trolls', 'Troll Race', 'Trolls are fierce jungle warriors from the islands of the South Seas, known for their regeneration and voodoo magic. They are agile hunters and warriors with a tribal culture. Trolls have Berserking (an activated 20% attack and casting speed burst, a flat amount since the Wrath revamp), Regeneration (faster health regen that partly continues in combat), and Beast Slaying (+5% damage to Beasts). They start in Durotar alongside the orcs. Trolls excel at hunter, mage, priest, rogue, shaman, and warrior classes. Notable trolls include Vol''jin and Zul''jin.', 'troll,trolls,troll racial,berserking,regeneration,beast slaying,darkspear', 'race,horde,troll,agile', '', '', 'what are trolls good at|should i roll a troll|what is berserking|what is the troll racial|how much haste does berserking give|where do trolls start|troll starting zone|is troll good for hunter|is troll good for mage|what is beast slaying racial|troll regeneration how does it work|is troll good for pvp|who is voljin|troll vs orc racial|is troll a good race|best horde race for mage');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_gnomes', 'Gnome Race', 'Gnomes are ingenious tinkerers and inventors from the underground city of Gnomeregan. They are brilliant engineers and mages with a love for technology. Gnomes have Expansive Mind (+5% intellect), a 2% reduced chance to be hit by arcane spells (Arcane Resistance), and Engineering Specialization (+15 engineering skill). They start in Dun Morogh and are loyal Alliance members. Gnomes excel at mage, rogue, and warrior classes. Famous gnomes include High Tinker Mekkatorque and Sicco Thermaplugg.', 'gnome,gnomes,gnome racial,escape artist,expansive mind,engineering specialization', 'race,alliance,gnome,ingenious', '', '', 'what are gnomes good at|should i roll a gnome|what is the gnome racial|what is expansive mind|where do gnomes start|gnome starting zone|is gnome good for mage|is gnome good for rogue|gnome engineering bonus|does gnome have arcane resist|is gnome good for pvp|who is mekkatorque|is gnomeregan the gnome city|is gnome a good race|best alliance race for mage|what classes can gnomes be');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_forsaken', 'Forsaken (Undead) Race', 'The Forsaken are undead beings who broke free from the Scourge, fighting for their freedom. They are cunning rogues and warlocks with resistance to fear and sleep. Forsaken have Will of the Forsaken (removes fear, sleep, and charm effects), Cannibalize (health regen from nearby corpses), and passive Shadow Resistance. They start in Tirisfal Glades and rule the Undercity. Forsaken excel at rogue, warlock, priest, mage, and warrior classes. Queen Sylvanas Windrunner leads the Forsaken.', 'forsaken,undead,undead racial,will of the forsaken,wotf,cannibalize', 'race,horde,undead,forsaken', '', '', 'what are forsaken good at|should i roll an undead|what is will of the forsaken|what is cannibalize|what is the undead racial|where do forsaken start|undead starting zone|is tirisfal glades the undead zone|is undead good for rogue|is undead good for warlock|does wotf remove fear|undead racial for pvp|who is sylvanas|is forsaken good for priest|is undead a good race|best horde race for pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_blood_elves', 'Blood Elf Race', 'Blood Elves are magically addicted survivors of the fallen kingdom of Quel''Thalas. They are powerful mages and paladins with a thirst for magic. Blood Elves have Arcane Torrent (a silence that also restores mana, energy, runic power, or rage), Arcane Affinity (+10 Enchanting skill), and passive Magic Resistance. They start in Eversong Woods and are ruled from Silvermoon by Regent Lord Lor''themar Theron; Kael''thas Sunstrider betrayed them and is now an enemy. Blood Elves excel at mage, paladin, priest, rogue, hunter, and warlock classes.', 'blood elf,blood elves,belf,belfs,blood elf racial,arcane torrent,arcane affinity', 'race,horde,blood elf,magical', '', '', 'what are blood elves good at|should i roll a blood elf|what is arcane torrent|what is the blood elf racial|does arcane torrent silence|where do blood elves start|blood elf starting zone|is eversong woods the belf zone|is blood elf good for paladin|is blood elf good for mage|blood elf enchanting bonus|is belf good for pvp|who is lorthemar|what happened to kaelthas|is blood elf a good race|what classes can blood elves be');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('wow_races_draenei', 'Draenei Race', 'Draenei are a tailed, hooved alien race who crashed on Azeroth fleeing demonic pursuers. They are holy paladins and priests with a devotion to the Light. Draenei have Heroic Presence (+1% hit chance for themselves and their party), Gift of the Naaru (an activated heal-over-time), and Gemcutting (+5 Jewelcrafting skill). They start on Azuremyst Isle and have advanced technology. Draenei excel at paladin, priest, shaman, mage, hunter, and warrior classes. Prophet Velen leads the draenei.', 'draenei,draenei racial,gift of the naaru,heroic presence,gemcutting', 'race,alliance,draenei,holy', '', '', 'what are draenei good at|should i roll a draenei|what is gift of the naaru|what is the draenei racial|what is heroic presence|where do draenei start|draenei starting zone|is azuremyst isle the draenei zone|is draenei good for paladin|is draenei good for shaman|draenei hit bonus for raid|draenei jewelcrafting bonus|who is velen|is draenei a good race|best alliance race for shaman|does gift of the naaru heal over time');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_leveling_guide', 'Leveling Strategies', 'Resting in an inn or a capital city builds rested experience, which doubles the experience from kills until it runs out. From level 15 the Dungeon Finder queues random dungeons, which pay well for leveling, and bind-to-account heirloom shoulders and chests add 10% experience each. The level cap is 80; Death Knights start at 55.', 'leveling,level up,lvling,xp,exp,rested xp,rested experience,leveling fast,heirloom,heirlooms,level fast,fastest leveling', 'general,leveling,progression,efficiency', 'general', 'The fastest way to level is the random dungeon queue mixed with questing while you wait, with heirlooms on and rested XP banked; an heirloom chest and shoulders add 20% XP between them. At 58 go to Outland and at 68 Northrend, skipping old zones you have outlevelled. Don''t grind dungeons that have turned grey; the XP falls off fast.', 'how do i level fast|best way to level|fastest way to level up|what is rested xp|how do i get rested exp|how does rested work|are heirlooms worth it|how much xp do heirlooms give|what level do i go to outland|when do i go to northrend|when should i leave outland|what level is the cap|what level do dks start at|tips for leveling|should i grind dungeons for xp|how to power level|do random dungeons give good xp|how do i level my alt quickly|is questing or dungeons faster|why am i getting so little xp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_gold_making', 'Gold Making Methods', 'Steady gold at 80 comes from daily quests, up to 25 a day, and from gathering: Saronite and Titanium ore, Frost Lotus and Lichbloom, and Frostweave Cloth always sell on the auction house. Crafters earn by selling glyphs, cut gems, flasks and enchanting materials like Infinite Dust.', 'gold making,make gold,farm gold,gold farming,earn gold,making money,money', 'general,economy,gold,professions', 'gold', 'The best steady gold at 80 is Inscription: mill Northrend herbs and keep the auction house stocked with every glyph, since glyphs sell one at a time all day. Next best is gathering with two gathering professions, Mining and Herbalism, in Sholazar Basin and the Storm Peaks, where Titanium, Frost Lotus and Eternals turn up. Fill the rest of the 25 dailies with the Argent Tournament and Sons of Hodir, and sell Frozen Orbs from heroics rather than spending them.', 'how do i make gold|best way to farm gold|how do i get rich|how do i make money at 80|what sells on the ah|what should i farm for gold|best gold farm at 80|how much do dailies pay|how many dailies a day|what should i sell|is inscription good for gold|what are the best gold professions|where do i farm gold|gold making tips|what mats sell well|how do i get 5000 gold for epic flying|what sells the best on the auction house|how do i earn gold quickly|best gold per hour');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_ui_customization', 'Interface Customization', 'Interface Options in the Escape menu can turn on four extra action bars beside the main one, and Key Bindings lets you put any spell on any key. /macro opens the macro window, with 36 general macros shared by the account and 18 more per character.', 'ui,interface,interface options,action bars,action bar,key bindings,keybinds,keybind,macro,macros', 'general,interface,customization,addons', '', '', 'how do i change my ui|how do i get more action bars|how do i turn on extra bars|how do i rebind keys|how do i change keybinds|how do i bind a spell to a key|how do i make a macro|what is /macro|how many macros can i have|where is the macro window|how do i add bars to my screen|how do i customize my interface|where are the key bindings|how do i use more hotkeys|how many action bars can i have|how do i set up my keybinds|how do i open interface options');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_addons', 'Essential Addons', 'Popular 3.3.5 addons: Deadly Boss Mods or BigWigs for boss timers, Omen for threat, Recount or Skada for damage meters, QuestHelper or Carbonite for quest routes, Auctioneer or Auctionator for the auction house, Gatherer for herb and ore nodes, and Bartender4 for action bars. An addon has to be the 3.3.5 version (interface 30300); retail builds won''t load. Each addon installs as its own folder in Interface\\AddOns.', 'addons,addon,dbm,deadly boss mods,bigwigs,recount,skada,omen,questhelper,auctioneer,auctionator,gatherer,bartender,damage meter,threat meter', 'general,addons,tools,enhancement', '', '', 'what addons should i use|best addons|what is dbm|what is deadly boss mods|what is bigwigs|what is omen|what addon shows threat|what is recount|what is skada|what addon shows damage|what is questhelper|what is carbonite|what is auctioneer|what is auctionator|what is bartender|what addon for boss timers|do retail addons work|why wont my addon load|which addons work on 3.3.5|where do i put addons');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_server_population', 'Server Types and Population', 'On a PvP realm, entering a contested zone flags you for PvP automatically, so enemy players can attack you anywhere outside your own faction''s zones and sanctuaries. On a PvE realm you can only be attacked once you flag yourself with /pvp or attack an enemy player; the flag wears off five minutes after you turn it off.', 'pvp server,pve server,pvp realm,pve realm,realm type,server type,pvp flag,flagged,pvp flagged', 'general,servers,population,rules', '', '', 'is this a pvp server|is this a pve realm|am i going to get ganked|what is a pvp realm|what is a pve realm|what does pvp realm mean|how long does pvp flag last|when does my pvp flag wear off|why am i flagged for pvp|can people attack me here|can i be attacked in this zone|what is the difference between pvp and pve servers|what is /pvp|how do i avoid pvp|can enemy players attack me anywhere|what are sanctuaries');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_character_creation', 'Character Creation Tips', 'You can play ten races: Alliance humans, dwarves, gnomes, night elves and draenei; Horde orcs, trolls, tauren, undead and blood elves. Only night elves and tauren can be druids, shamans are orcs, trolls, tauren or draenei, and paladins are humans, dwarves, draenei or blood elves. A Death Knight unlocks once you have a level 55 character on the realm.', 'character creation,new character,make a character,create a character,reroll,race and class,which race,what race,race class combo', 'general,character,creation,planning', '', '', 'what races are in the game|what race can be a druid|what races can be shamans|what races can be paladins|can orcs be paladins|can humans be shamans|what classes can dwarves be|can tauren be druids|can blood elves be paladins|can undead be druids|what should i make a new character|how do i unlock death knights|how do i make a death knight|what race is best for my class|how do i unlock a dk|can night elves be shamans|can gnomes be paladins|what races are alliance|what races are horde|can draenei be shamans');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_gear_optimization', 'Gear Optimization', 'Gear is tuned with gems and enchants, including the off-hand. Head enchants are arcanums sold at Revered by factions like the Argent Crusade, Kirin Tor and Knights of the Ebon Blade; shoulder inscriptions come from the Sons of Hodir at Honored and Exalted; and a blacksmith''s Eternal Belt Buckle adds one more socket to any belt.', 'gear,gearing,stat priority,stats,upgrade,upgrades,bis,best in slot,arcanum,head enchant,shoulder enchant,inscription for shoulders,belt buckle,eternal belt buckle,gem,off,offhand,hit cap', 'general,gear,optimization,stats', 'pve', 'Get to the hit cap first: 263 rating for melee special attacks and 446 for spells against a raid boss. Melee also wants 26 expertise, and tanks need 540 defense, 689 rating, to be crit-immune. Gem your main stat in every socket and only follow a socket bonus if it is worth more than the stat you give up. For the meta gem, use Relentless Earthsiege for physical damage, Chaotic Skyflare for casters and Austere Earthsiege for tanks.', 'how do i optimize my gear|how do i min max my gear|what is hit cap|how much hit do i need|what is the hit cap for casters|what is expertise cap|how much expertise do i need|what is the def cap|how much defense for a tank|how do i get crit immune|what meta gem should i use|best meta gem for dps|best meta gem for tanks|how do i get head enchants|how do i get a head enchant|how do i get shoulder enchants|what is the belt buckle|how do i add a belt socket|should i follow the socket bonus|what is arcanum');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_patch_changes', 'Understanding Patches', 'The realm runs patch 3.3.5a, the final patch of Wrath of the Lich King. Patch 3.3 added Icecrown Citadel, the Forge of Souls, Pit of Saron and Halls of Reflection dungeons and the Dungeon Finder, and 3.3.5 added the Ruby Sanctum raid against Halion.', 'patch,patches,patch notes,335,nerf,nerfs,nerfed,expansion', 'general,patches,updates,balance', '', '', 'what patch is this|what patch is the realm on|what version is this server|what is 3.3.5|what is 3.3.5a|what did patch 3.3 add|what did 3.3.5 add|when did icc come out|what is the final wotlk patch|is ruby sanctum in the game|is halion in the game|is icc out|are the frozen halls dungeons out|what is pit of saron|what is the forge of souls|is this the last patch of wrath|what content is out');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_achievement_hunting', 'Achievement Collecting', 'The big meta achievements pay mounts: Glory of the Hero (heroic dungeon feats) gives the Red Proto-Drake, Glory of the Raider gives the Black Proto-Drake on 10-player and the Plagued Proto-Drake on 25, Glory of the Ulduar Raider gives the Rusted or Ironbound Proto-Drake, and What a Long, Strange Trip It''s Been, for every holiday meta, gives the Violet Proto-Drake.', 'achievement hunting,meta achievement,glory of the hero,glory of the raider,glory of the ulduar raider,glory of the icecrown raider,what a long strange trip,proto drake,achievement mount', 'general,achievements,goals,collection', '', '', 'how do i get the red proto drake|how do i get the black proto drake|how do i get the plagued proto drake|what is glory of the hero|what is glory of the raider|what is glory of the ulduar raider|how do i get the violet proto drake|how do i get the ironbound proto drake|how do i get the rusted proto drake|what is the holiday meta achievement|what is what a long strange trip it''s been|which achievements give mounts|how do i get a proto drake|what are the meta achievements|what achievement gives a proto drake|how do i get a drake from achievements|how do i get a mount from an achievement');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_alt_management', 'Managing Multiple Characters', 'You can have up to 10 characters on a realm and 50 across the account. Bind-to-account heirlooms can be mailed between your characters on the realm, and a Death Knight unlocks once one of them reaches level 55. Banks and bags are not shared between characters; the mailbox moves items between them. Many players park a bank alt in a capital to hold materials and run auctions.', 'alt,alts,altoholic,bank alt,alt character,character slots,how many characters', 'general,alts,management,utility', 'general', 'Keep one bank alt in a capital with a mailbox and auction house for materials and sales. Mail heirlooms to each new alt, and pick professions that feed your main, such as gathering on alts and crafting on the main. Rest every alt in an inn so they always have rested XP.', 'how many characters can i have|how many alts can i make|how many chars per realm|how many characters per account|how do i share items between alts|how do i send gear to my alt|can i mail heirlooms to alts|do alts share a bank|is the bank shared between characters|what is a bank alt|how do i move items to my alt|how do i unlock a dk with an alt|tips for managing alts|how do i send stuff to my alt|which professions on alts|how do i organize my alts|do alts share gold|how many toons can i have|how many chars can i make|how many alts per realm|how many characters on an account|max characters per realm|can i share bank with my alt|how do i give my alt gear|mail heirlooms to alt|how do i unlock dk|what level for a dk|alt tips|how do i move gold to my alt|do my alts share a bank|where do i park my bank alt|how do i manage lots of alts');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_endgame_content', 'Endgame and Raids', 'At level 80 the endgame is heroic five-mans, raids, arenas, Wintergrasp, daily quests and reputation. The raids are Naxxramas, Obsidian Sanctum, Eye of Eternity, Vault of Archavon, Ulduar, Trial of the Crusader, Onyxia''s Lair, Icecrown Citadel and Ruby Sanctum; Icecrown Citadel is the top tier and ends with the Lich King.', 'endgame,end game,max level,level cap,raids', 'general,endgame,content,variety', 'pve', 'Fresh 80s should skip straight past Naxxramas and Ulduar: run heroics and the Icecrown five-mans, buy tier 9 with Triumph, then go into Trial of the Crusader and Icecrown Citadel, where the gear is. Hit the weekly raid quest and Vault of Archavon every week, and get attuned to the content your guild is actually on rather than doing it in order.', 'what is there to do at 80|what do i do at max level|what is the endgame|what raids are there|what raids are in wotlk|what is the top raid|what is the best raid|where do i raid at 80|what is the last raid|who is the final boss|what raid should i start with|should i skip naxx|should i do ulduar|what is the raid order|what should a fresh 80 do|how do i gear up for icc|what is the vault of archavon|what do i do after hitting 80|what is the endgame like');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_learning_basics', 'Learning the Basics', 'New characters start at level 1 in their race''s starting zone. Class trainers in towns and capitals teach new spells and ranks every two levels for gold. Talent points start at level 10, riding at 20, and dual specialization at 40; the cap is 80.', 'new player,beginner,just started,how to play,basics', 'general,basics,learning,beginners', '', '', 'how do i start playing|i am new to wow|new player tips|how do i learn new spells|where do i learn spells|where is my class trainer|how often do i get new spells|what level do i get talents|when do i get riding|tips for a new player|how do i get started|beginner guide|where do i start|what do i do at level 1|how do i train my abilities|how much do spells cost to learn|when do i get dual spec');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_finding_groups', 'Finding Groups for Content', 'The Dungeon Finder builds a group for five-man dungeons automatically. Raids aren''t queued: they''re formed in trade chat or the Raid Browser, where you list yourself for a raid and leaders can invite you. On this realm the LookingForGroup channel only opens while you''re queued or listed in the LFG tool. Saying your role and gear level up front gets invites faster.', 'looking for group,lfg,lfm,find a group,find group,pug,pugs,raid browser,lookingforgroup', 'general,groups,social,content', '', '', 'how do i find a group|how do i find a raid|how do i get into a raid|how do i find a dungeon group|where do i look for group|what is the raid browser|what is the lfg channel|how do i find players for icc|how do i join a raid group|how do i find a pug|where do pugs form|how do i get invited to raids|how do i list myself for a raid|does lfd work for raids|how do i get a pug raid|how do i find people for a 10 man|how do i get picked for a group|what is the lookingforgroup channel|can i queue for raids|how do i join the lookingforgroup channel|why cant i join the lfg channel|why is lfg chat closed|how do i get into the lookingforgroup channel|why cant i talk in lfg chat|how do i join lfg chat');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_addon_management', 'Managing Addons Effectively', 'Addons go in World of Warcraft\\Interface\\AddOns, one folder per addon, and are switched on per character from the AddOns button on the character select screen; tick Load out of date AddOns if one is flagged out of date. Their settings are saved in the WTF folder, so copying it backs up your setup, and /reload reloads the interface.', 'install addons,install addon,addon folder,out of date addons,load out of date,wtf folder,reload ui,reloadui,addon broken', 'general,addons,management,technical', '', '', 'how do i install addons|where do addons go|how do i enable an addon|why is my addon out of date|how do i load out of date addons|how do i reload my ui|what is /reload|how do i back up my addon settings|where are addon settings saved|what is the wtf folder|how do i back up my ui|where is the addons folder|how do i fix a broken addon|how do i turn addons off|why wont my addon show up|how do i update addons|how do i copy my ui to another computer|how do i reset my addons');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_questing_efficiency', 'Questing Efficiently', 'Since patch 3.3 the world map and minimap show where each tracked quest''s objectives are, so a quest addon is optional. The quest log holds 25 quests, and up to 25 daily quests can be completed per day. Picking up every quest in a hub before heading out saves the most travel.', 'questing,quest tracking,quest objectives,quest map,daily cap,quest tracker', 'general,questing,efficiency,progression', 'general', 'Grab every quest in a hub, kill along the way to quest objectives, and turn in everything at once before moving on. Skip group quests if you are alone, and abandon anything that sends you far from your route. Set your hearthstone to the hub you will come back to most.', 'how do i quest faster|how do i quest efficiently|best way to do quests|how do i find quest objectives|do i need a quest addon|how do i see where to go for a quest|how many dailies can i do|how many quests in the log|where is the quest marker|should i grab all the quests first|how do i save travel time questing|should i skip group quests|where do i set my hearthstone|should i abandon a quest|tips for questing|how do i use the quest tracker|how do i level through quests|how do i find a quest npc on the map');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_inventory_management', 'Managing Inventory and Bags', 'Characters carry a backpack plus four bag slots; tailors make the 20-slot Frostweave Bag, and profession bags hold more but only their own material. The bank adds 28 slots and seven more bag slots bought with gold. Items have no weight, only slot count matters.', 'bags,bag,bag space,inventory,inventory full,bag slots,bigger bags,frostweave bag,profession bag', 'general,inventory,management,organization', '', '', 'how do i get more bag space|how many bag slots do i have|how many slots in the bank|how many bank slots can i buy|what is the biggest bag|what is a frostweave bag|what are profession bags|what goes in a herb bag|do items have weight|how do i get bigger bags|my bags are full|where do i buy bags|how do i buy more bank slots|what bags hold the most|how do i make a 20 slot bag|can i put anything in a profession bag|how many bags can i carry|how do i manage my inventory');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_reputation_grinding', 'Reputation Grinding Strategies', 'In Northrend, wearing the tabard of the Argent Crusade, Kirin Tor, Knights of the Ebon Blade or Wyrmrest Accord in a level-80 dungeon sends that dungeon''s reputation to the faction, called championing. Factions without a tabard, like the Sons of Hodir, rise only through quests and dailies, and humans gain 10% more reputation from Diplomacy.', 'rep grind,reputation grind,grind rep,rep farm,farm rep,championing,champion tabard,kirin tor rep,hodir rep,sons of hodir rep,diplomacy', 'general,reputation,grinding,progression', 'general', 'Wear the tabard of the faction you need when you run level-80 heroics: championing gives far more reputation than the dailies alone. Sons of Hodir is dailies only, so start it early. Kirin Tor, Argent Crusade, Wyrmrest Accord and Knights of the Ebon Blade sells the head enchants at Revered, and Sons of Hodir at Exalted gives the best shoulder enchant.', 'how do i grind rep|fastest way to get rep|how do i farm reputation|what is championing|how do i champion a faction|how do i get rep from dungeons|how do i get argent crusade rep|how do i get kirin tor rep|how do i get ebon blade rep|how do i get wyrmrest accord rep|how do i get sons of hodir rep|do tabards give rep|what tabard do i wear for rep|where do i get head enchants|who sells head enchants|how do i get exalted with sons of hodir|how do i get shoulder enchants from sons of hodir|how do i get exalted fast|how do i farm rep for head enchants');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_raid_preparation', 'Preparing for Raids', 'Raiders bring a flask, which lasts an hour and stays through death, plus food; a cook''s Fish Feast feeds the whole raid at once. Repair before the first pull, and since raid lockouts reset once a week, check whether the group is on a fresh or a saved raid ID before joining.', 'raid prep,raid ready,pre raid,fish feast,raid consumables,raid requirements', 'general,raids,preparation,strategy', 'pve', 'Flask for your role: Endless Rage for physical damage, Frost Wyrm for spell power, Stoneblood for tanks, Pure Mojo for healers who need mana. Eat the raid''s Fish Feast, drink a Potion of Speed or Wild Magic just before the pull and another during the fight, since the potion cooldown does not start until combat ends. Show up repaired, gemmed and enchanted, with reagents, having read the boss fights.', 'how do i prepare for a raid|what do i bring to a raid|what do i need for raid night|raid prep tips|what flask should i bring|what flask for tanks|what flask for healers|what flask for dps|what is the best flask for casters|what should i eat before a raid|what is a raid id|how do raid lockouts work|what is a saved raid id|should i use a potion before the pull|when do i use a pot|do i need to repair before a raid|what do i do before the first pull|what potion do i use in raids|what reagents do i need for raids|how do i get ready for a raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_pvp_preparation', 'PvP Preparation Tips', 'For PvP, wear gear with resilience, which cuts critical strikes and damage taken from players, and carry the PvP trinket: the Medallion of the Alliance or Medallion of the Horde. It breaks stuns, fears and other crowd control on a 2-minute cooldown; humans'' Every Man for Himself does the same.', 'pvp trinket,medallion of the alliance,medallion of the horde,pvp prep,break cc,cc break', 'general,pvp,preparation,combat', 'pvp', 'Set up macros before you queue: focus target, cast-at-focus for crowd control and interrupts, and a stopcasting interrupt. Trinket the crowd control that would get you killed, not the first one you see, and save your defensive cooldowns for the moment your team is at its lowest. Having healers on a different target than your damage keeps a fight under control.', 'how do i prepare for pvp|what do i need for pvp|what is resilience|what is the pvp trinket|what is a medallion|what does the pvp trinket do|how do i break stuns|how do i get out of a fear|how do i get the horde medallion|how do i get the alliance medallion|what is every man for himself|how long is the trinket cooldown|what macros do i need for pvp|what is a focus macro|tips for pvp|should i use my trinket on the first cc|pvp tips for arenas|how do i win in pvp|how do i set up pvp macros|what does resil do');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_loremaster', 'The Loremaster Achievement', 'The Loremaster achievement needs the four regional Loremaster achievements: Eastern Kingdoms and Kalimdor, each a count of several hundred completed quests, and Outland and Northrend, each a set of zone quest achievements such as Nothing Boring About Borean and To Hellfire and Back. It gives the Loremaster title and the Loremaster''s Colors tabard, mailed from Darnassus for the Alliance and Thunder Bluff for the Horde.', 'loremaster,the loremaster,loremaster title,loremasters colors,loremaster of azeroth', 'achievement,quests,title,goals', '', '', 'what is loremaster|how do i get loremaster|how do i become loremaster|what does the loremaster achievement need|what is the loremaster title|how many quests for loremaster|what do i get for loremaster|what is loremaster''s colors|how do i get the loremaster tabard|what is loremaster of northrend|what is loremaster of outland|what is loremaster of kalimdor|what is loremaster of eastern kingdoms|how long does loremaster take|is loremaster hard|do i have to do every quest for loremaster');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('general_spell_power_gear', 'Spell Power Gear', 'Casters can buy spell power gear from the Emblem vendors in Dalaran: Rueben Lauren, the cloth armor merchant, sells pieces for Emblems of Triumph (item level 232, 30 to 50 emblems each) and Emblems of Frost (item level 251, 60 to 95 each). Tailors craft Frostsavage (item level 187) and Ebonweave, Moonshroud and Spellweave robes and gloves (200), and heroic dungeon and raid bosses drop more. Gems and enchants add spell power too.', 'spellpower,spell power gear,caster gear,frostsavage,rueben lauren', 'general,gear,caster', '', '', 'where do i get caster gear|best gear for casters|how do i gear up my mage|where to get cloth gear at 80|spell power gear for healers|how do i get spellpower|caster gear from emblems|what emblem vendor sells cloth|where to buy cloth armor with emblems|tailoring spell power gear|how do i gear my priest|how do i gear a warlock|what gear should my mage wear|how do i gear my healer|where can i get spell power items|what is frostsavage');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_utgarde_keep', 'Utgarde Keep', 'Utgarde Keep is a level 69 to 72 five-player dungeon in Howling Fjord. It is the first dungeon most players see in Northrend, a vrykul hold built into the cliffs above Daggercap Bay. Its bosses are Prince Keleseth, Dalronn the Controller, and Ingvar the Plunderer.', 'utgarde keep,uk,utgarde', 'instance,dungeon', '', '', 'where is utgarde keep|what level is uk|uk dungeon level range|who are the bosses in utgarde keep|last boss of uk|who is ingvar the plunderer|first northrend dungeon in howling fjord|how many bosses in utk|where is the entrance to utgarde keep|keleseth dalronn ingvar which dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_nexus', 'The Nexus', 'The Nexus is a level 71 to 73 five-player dungeon in Coldarra, in the Borean Tundra. It is the middle ring of Malygos''s spire, and the whole place is frozen blue crystal. Its bosses are Commander Stoutbeard, Grand Magus Telestra, Anomalus, Ormorok the Tree-Shaper, and Keristrasza.', 'the nexus,nexus', 'instance,dungeon', '', '', 'where is the nexus|what level is nexus|who is the last boss in nexus|nexus bosses list|how many bosses in the nexus|where is keristrasza|nexus dungeon coldarra location|is nexus the one with the blue crystals|what dungeon has commander stoutbeard|how do i get to the nexus');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_azjol_nerub', 'Azjol-Nerub', 'Azjol-Nerub is a level 72 to 74 five-player dungeon in Dragonblight. It is a short three-boss run straight down through the old nerubian kingdom, and the second boss fight happens while you retreat up a web tunnel. Its bosses are Krik''thir the Gatewatcher, Hadronox, and Anub''arak.', 'azjol nerub,azjol-nerub,an,nerub', 'instance,dungeon', '', '', 'where is azjol nerub|what level is az dungeon|azjol nerub bosses|how many bosses in azjol-nerub|last boss of an dungeon|is azjol nerub short|who is hadronox|krik''thir hadronox anub''arak which dungeon|how do i get into azjol nerub dragonblight|fastest northrend dungeon spiders');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_ahn_kahet_the_old_kingdom', 'Ahn''kahet: The Old Kingdom', 'Ahn''kahet: The Old Kingdom is a level 73 to 75 five-player dungeon in Dragonblight. It shares an entrance area with Azjol-Nerub but runs deeper and darker, and Amanitar only appears on heroic difficulty. Its bosses are Elder Nadox, Prince Taldaram, Jedoga Shadowseeker, Amanitar, and Herald Volazj.', 'ahnkahet,the old kingdom,old kingdom,ok,ahn kahet', 'instance,dungeon', '', '', 'where is ahn''kahet|what level is old kingdom|ahnkahet bosses|how many bosses in old kingdom|who is amanitar|is amanitar only on heroic|last boss of ahn kahet|how do i get to the old kingdom|who is herald volazj|where is the entrance to ahnkahet');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_drak_tharon_keep', 'Drak''Tharon Keep', 'Drak''Tharon Keep is a level 74 to 76 five-player dungeon in on the border between the Grizzly Hills and Zul''Drak. It is a Drakkari troll fortress; King Dred is a devilsaur kept as a pet, and The Prophet Tharon''ja, who has given himself to the Scourge, waits at the top. Its bosses are Trollgore, Novos the Summoner, King Dred, and The Prophet Tharon''ja.', 'draktharon keep,draktharon,dtk,drak tharon', 'instance,dungeon', '', '', 'where is drak tharon keep|what level is dtk|who are the bosses in drak''tharon|last boss of dtk|who is king dred|tharon''ja location dungeon|how many bosses in drak tharon keep|how do i get to dtk|what dungeon has trollgore|dtk grizzly hills or zul drak');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_violet_hold', 'Violet Hold', 'Violet Hold is a level 75 to 77 five-player dungeon in Dalaran. It is a prison break rather than a crawl: you hold a room against timed waves while sealed cells open, and which mini-bosses you get is randomised each run. Its bosses are Erekem, Moragg, Ichoron, Xevozz, Lavanthor, Zuramat the Obliterator, and Cyanigosa.', 'violet hold,vh', 'instance,dungeon', '', '', 'where is violet hold|what level is vh|who are the bosses in violet hold|is violet hold random bosses|last boss of vh|who is cyanigosa|how do i get to the violet hold|how many bosses in vh|what is violet hold dungeon|dalaran prison dungeon what level');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_gundrak', 'Gundrak', 'Gundrak is a level 76 to 78 five-player dungeon in Zul''Drak. It is where the Drakkari are butchering their own animal gods, and Eck the Ferocious is a bonus boss that only exists on heroic. Its bosses are Slad''ran, Moorabi, Drakkari Colossus, Gal''darah, and Eck the Ferocious.', 'gundrak,gd', 'instance,dungeon', '', '', 'where is gundrak|what level is gundrak|gundrak bosses|who is eck the ferocious|is eck only on heroic|last boss of gundrak|how many bosses in gundrak|where is the entrance to gundrak|gal''darah where|what dungeon is in zul''drak');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_halls_of_stone', 'Halls of Stone', 'Halls of Stone is a level 77 to 79 five-player dungeon in The Storm Peaks. The middle of it is the Tribunal of Ages, an escort-and-defend event where Brann Bronzebeard reads titan records while you keep him alive. Its bosses are Krystallus, Maiden of Grief, and Sjonnir The Ironshaper.', 'halls of stone,hos', 'instance,dungeon', '', '', 'where is halls of stone|what level is hos|who are the bosses in halls of stone|what is the tribunal of ages|who is sjonnir|where is brann bronzebeard in hos|last boss of hos|how many bosses in halls of stone|how do i get to halls of stone|krystallus maiden sjonnir what dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_halls_of_lightning', 'Halls of Lightning', 'Halls of Lightning is a level 79 to 80 five-player dungeon in The Storm Peaks. It sits above Halls of Stone in the same titan complex, and Loken at the end is a straight damage race against a stacking pulse. Its bosses are General Bjarngrim, Volkhan, Ionar, and Loken.', 'halls of lightning,hol', 'instance,dungeon', '', '', 'where is halls of lightning|what level is hol|who are the bosses in halls of lightning|last boss of hol|who is loken|how many bosses in halls of lightning|where is the entrance to hol|bjarngrim volkhan ionar loken dungeon|is hol above halls of stone|how do i get to halls of lightning');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_utgarde_pinnacle', 'Utgarde Pinnacle', 'Utgarde Pinnacle is a level 79 to 80 five-player dungeon in Howling Fjord. It is the upper half of the same vrykul keep as Utgarde Keep but tuned for level 80, and Skadi is fought from the back of a drake. Its bosses are Svala Sorrowgrave, Gortok Palehoof, Skadi the Ruthless, and King Ymiron.', 'utgarde pinnacle,up,pinnacle', 'instance,dungeon', '', '', 'where is utgarde pinnacle|what level is up|who are the bosses in utgarde pinnacle|who is king ymiron|last boss of pinnacle|how do you fight skadi in the pinnacle|how many bosses in utgarde pinnacle|difference between utgarde keep and pinnacle|how do i get to utgarde pinnacle|where is skadi the ruthless');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_oculus', 'The Oculus', 'The Oculus is a level 79 to 80 five-player dungeon in Coldarra, in the Borean Tundra. Most of it is fought from drake mounts in mid-air, which made it the least popular dungeon in the Dungeon Finder by a wide margin. Its bosses are Drakos the Interrogator, Varos Cloudstrider, Mage-Lord Urom, and Ley-Guardian Eregos.', 'the oculus,oculus,occ', 'instance,dungeon', '', '', 'where is the oculus|what level is oculus|who are the bosses in oculus|why does everyone hate oculus|is oculus the one with drakes|last boss of oculus|who is ley-guardian eregos|how many bosses in the oculus|where is the entrance to oculus|varos urom drakos eregos which dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_culling_of_stratholme', 'The Culling of Stratholme', 'The Culling of Stratholme is a level 79 to 80 five-player dungeon in the Caverns of Time in Tanaris. It replays Arthas purging Stratholme, and beating the optional timed run rewards the Bronze Drake mount. Its bosses are Meathook, Salramm the Fleshcrafter, Chrono-Lord Epoch, and Mal''Ganis.', 'culling of stratholme,cos,strat cot,bronze drake', 'instance,dungeon', '', '', 'where is culling of stratholme|what level is cos|who are the bosses in culling|how do i get the bronze drake|what is the timed run in culling|last boss of cos|who is mal''ganis|how many bosses in culling of strat|caverns of time culling entrance|where is meathook');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_trial_of_the_champion', 'Trial of the Champion', 'Trial of the Champion is a level 79 to 80 five-player dungeon in the Argent Tournament grounds in Icecrown. It opens with a mounted jousting round using vehicle controls before turning into a normal fight. Its bosses are The Grand Champions, Eadric the Pure, Argent Confessor Paletress, and The Black Knight.', 'trial of the champion,toc5,totc', 'instance,dungeon', '', '', 'where is trial of the champion|what level is toc 5 man|toc dungeon bosses|toc 5 man last boss|who is the black knight|where is totc entrance|who is eadric the pure|how many bosses in trial of the champion|is toc the jousting dungeon|how do i get to toc argent tournament');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_forge_of_souls', 'The Forge of Souls', 'The Forge of Souls is a level 79 to 80 five-player dungeon in Icecrown Citadel. It is the first of the three patch 3.3 dungeons that lead into Icecrown Citadel itself. Its bosses are Bronjahm, and Devourer of Souls.', 'forge of souls,fos', 'instance,dungeon', '', '', 'where is forge of souls|what level is fos|who are the bosses in forge of souls|who is bronjahm|last boss of fos|how many bosses in forge of souls|first icc dungeon|where is the entrance to fos|devourer of souls dungeon|how do i get into forge of souls');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_pit_of_saron', 'Pit of Saron', 'Pit of Saron is a level 79 to 80 five-player dungeon in Icecrown Citadel. The last stretch is a scripted escape with Jaina or Sylvanas clearing the way ahead of you. Its bosses are Forgemaster Garfrost, Ick, Krick, and Scourgelord Tyrannus.', 'pit of saron,pos', 'instance,dungeon', '', '', 'where is pit of saron|what level is pos|who are the bosses in pit of saron|who is tyrannus|last boss of pos|who are ick and krick|how many bosses in pit of saron|is the escape in pos with jaina|where is garfrost|how do i get to pit of saron');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_halls_of_reflection', 'Halls of Reflection', 'Halls of Reflection is a level 79 to 80 five-player dungeon in Icecrown Citadel. It is two bosses and then a fighting retreat from the Lich King himself, who cannot be killed here. Its bosses are Falric, Marwyn, and The Lich King.', 'halls of reflection,hor', 'instance,dungeon', '', '', 'where is halls of reflection|what level is hor|who are the bosses in halls of reflection|last boss of hor|can you kill the lich king in hor|how many bosses in halls of reflection|who are falric and marwyn|where is the entrance to hor|what is the escape in hor|third icc 5 man dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_naxxramas', 'Naxxramas', 'Naxxramas is a level 80 ten- and twenty-five-player raid in Dragonblight. It was moved from the Eastern Plaguelands and retuned for level 80 as Wrath''s entry raid; it is split into the Arachnid, Plague, Military and Construct quarters, which can be cleared in any order before Sapphiron and Kel''Thuzad. Its bosses are Anub''Rekhan, Grand Widow Faerlina, Maexxna, Noth the Plaguebringer, Heigan the Unclean, Loatheb, Instructor Razuvious, Gothik the Harvester, The Four Horsemen, Patchwerk, Grobbulus, Gluth, Thaddius, Sapphiron, and Kel''Thuzad.', 'naxxramas,naxx,scourge,necropolis', 'instance,dungeon', '', '', 'where is naxx|what level is naxxramas|how many bosses in naxx|who is the last boss of naxx|what are the naxx wings|is naxx 10 or 25|where do i enter naxxramas|who is kel''thuzad|what is sapphiron|is naxx the entry raid for wrath|naxx quarters order|where is the naxx raid in dragonblight');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_obsidian_sanctum', 'The Obsidian Sanctum', 'The Obsidian Sanctum is a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. Leaving Sartharion''s three drake lieutenants alive raises the difficulty and the loot, which is where the ''Sartharion plus three drakes'' achievement runs come from. Its bosses are Tenebron, Shadron, Vesperon, and Sartharion.', 'obsidian sanctum,os,sarth', 'instance,dungeon', '', '', 'where is obsidian sanctum|what level is os raid|who is sartharion|how many bosses in os|what is sarth plus 3 drakes|where is the entrance to obsidian sanctum|os 10 or 25 man|what are the drakes in os|who are tenebron shadron vesperon|how do i get to the obsidian sanctum');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_eye_of_eternity', 'The Eye of Eternity', 'The Eye of Eternity is a level 80 ten- and twenty-five-player raid in Coldarra, in the Borean Tundra. It is a single fight against Malygos that ends with the whole raid on drakes in a vehicle phase. Its boss is Malygos.', 'eye of eternity,eoe,malygos raid', 'instance,dungeon', '', '', 'where is eye of eternity|what level is eoe|who is malygos|how many bosses in eye of eternity|where is the entrance to eoe|is eoe a single boss raid|malygos raid where|eoe 10 or 25|what is the drake phase in eoe|how do i get to the eye of eternity');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_ulduar', 'Ulduar', 'Ulduar is a level 80 ten- and twenty-five-player raid in The Storm Peaks. It opens with a vehicle assault on Flame Leviathan, and most bosses have an optional harder ''hard mode'' triggered in-fight rather than by a difficulty setting; Algalon is a limited-attempt bonus encounter. Its bosses are Flame Leviathan, Ignis the Furnace Master, Razorscale, XT-002 Deconstructor, The Assembly of Iron, Kologarn, Auriaya, Hodir, Thorim, Freya, Mimiron, General Vezax, Yogg-Saron, and Algalon the Observer.', 'ulduar,titan,siege of ulduar,inner sanctum', 'instance,dungeon', '', '', 'where is ulduar|what level is uld|how many bosses in ulduar|who is the last boss of ulduar|what are hard modes in ulduar|who is algalon|where is the entrance to ulduar|is ulduar 10 and 25|who is yogg saron|what is flame leviathan|ulduar storm peaks location|how do i get to ulduar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_trial_of_the_crusader', 'Trial of the Crusader', 'Trial of the Crusader is a level 80 ten- and twenty-five-player raid in the Argent Tournament grounds in Icecrown. It is a single arena room with no trash at all, run as five staged encounters; the Heroic version is separately locked and limited by a shared attempt counter. Its bosses are Northrend Beasts, Lord Jaraxxus, Faction Champions, Twin Val''kyr, and Anub''arak.', 'trial of the crusader,toc,totc25', 'instance,dungeon', '', '', 'where is trial of the crusader|what level is toc raid|toc 10 or 25 man|bosses in trial of the crusader|what is the attempt counter in toc heroic|who is the last boss of toc|totc raid bosses|is there trash in toc|who is jaraxxus|where is the toc raid entrance|how do i get to the coliseum');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_icecrown_citadel', 'Icecrown Citadel', 'Icecrown Citadel is a level 80 ten- and twenty-five-player raid in Icecrown. It is the final raid of Wrath of the Lich King, released wing by wing over patch 3.3, and ends with the Lich King on the roof of the Frozen Throne. Its bosses are Lord Marrowgar, Lady Deathwhisper, Gunship Battle, Deathbringer Saurfang, Festergut, Rotface, Professor Putricide, Prince Valanar, Blood-Queen Lana''thel, Valithria Dreamwalker, Sindragosa, and The Lich King.', 'icecrown citadel,icc', 'instance,dungeon', '', '', 'where is icc|what level is icecrown citadel|how many bosses in icc|who is the last boss of icc|where do i enter icc|is icc 10 and 25|who is sindragosa|what is the gunship battle|who is lich king in icc|icc raid wings|what patch was icc released|bosses in icecrown citadel');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_vault_of_archavon', 'Vault of Archavon', 'Vault of Archavon is a level 80 ten- and twenty-five-player raid in Wintergrasp. Access is a PvP prize rather than a raid lockout: only the faction currently holding Wintergrasp can enter, and each boss drops a mix of PvP and PvE gear. Its bosses are Archavon the Stone Watcher, Emalon the Storm Watcher, Koralon the Flame Watcher, and Toravon the Ice Watcher.', 'vault of archavon,voa,archavon', 'instance,dungeon', '', '', 'where is vault of archavon|what level is voa|who are the bosses in voa|how do i get into vault of archavon|who can enter voa|do i need to win wintergrasp for voa|how many bosses in vault of archavon|does voa drop pvp gear|who is toravon|where is the entrance to voa');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_ruby_sanctum', 'The Ruby Sanctum', 'The Ruby Sanctum is a level 80 ten- and twenty-five-player raid in the Chamber of Aspects beneath Wyrmrest Temple in Dragonblight. It arrived in patch 3.3.5 as the last raid of the expansion, and Halion is fought in both a physical and a shadow version of the room at once. Its bosses are Baltharus the Warborn, General Zarithrian, Saviana Ragefire, and Halion.', 'ruby sanctum,rs,halion', 'instance,dungeon', '', '', 'where is ruby sanctum|what level is rs raid|who is halion|how many bosses in ruby sanctum|last raid of wrath|who are baltharus zarithrian saviana|where is the entrance to ruby sanctum|rs 10 or 25|what patch added ruby sanctum|how do i get to the ruby sanctum');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_onyxia_s_lair', 'Onyxia''s Lair', 'Onyxia''s Lair is a level 80 ten- and twenty-five-player raid in Dustwallow Marsh. Originally a level 60 raid, it was retuned to level 80 in patch 3.2.2 for the game''s fifth anniversary and drops current Wrath-tier loot. Its boss is Onyxia.', 'onyxias lair,onyxia,ony,black dragon,dragonmurk', 'instance,dungeon', '', '', 'where is onyxia lair|what level is ony|is onyxia 80 now|how do i get to onyxia|where is ony entrance dustwallow|ony 10 or 25|who is the boss of onyxia''s lair|what patch retuned onyxia|does ony drop wrath gear|onyxia 5th anniversary raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_hellfire_citadel_ramparts', 'Hellfire Citadel: Ramparts', 'Hellfire Citadel: Ramparts is a level 59 to 62 five-player dungeon in Hellfire Peninsula. It is the first Outland dungeon most players run, and much of it is fought on open walkways rather than corridors. Its bosses are Watchkeeper Gargolmar, Omor the Unscarred, and Vazruden the Herald.', 'hellfire ramparts,ramparts,hfr', 'instance,dungeon', '', '', 'where is ramparts|what level is hellfire ramparts|hfr dungeon level|who are the bosses in ramparts|last boss of ramparts|who is vazruden|how many bosses in hellfire ramparts|first outland dungeon|where is the entrance to ramparts|how do i get to ramparts hellfire peninsula|omor gargolmar vazruden dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_hellfire_citadel_the_blood_furnace', 'Hellfire Citadel: The Blood Furnace', 'Hellfire Citadel: The Blood Furnace is a level 61 to 63 five-player dungeon in Hellfire Peninsula. It is where the Legion was mass-producing fel orcs, and the middle boss is fought through a sequence of gas-filled cells. Its bosses are The Maker, Broggok, and Keli''dan the Breaker.', 'blood furnace,bf', 'instance,dungeon', '', '', 'where is blood furnace|what level is bf|who are the bosses in blood furnace|last boss of blood furnace|who is broggok|how many bosses in the blood furnace|who is keli''dan|where is the entrance to blood furnace|how do i get to bf hellfire|what is the maker boss');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_coilfang_the_slave_pens', 'Coilfang: The Slave Pens', 'Coilfang: The Slave Pens is a level 62 to 64 five-player dungeon in Zangarmarsh. It is the shallowest of the three Coilfang wings and the usual first stop for a Cenarion Expedition reputation grind. Its bosses are Mennu the Betrayer, Rokmar the Crackler, and Quagmirran.', 'slave pens,sp', 'instance,dungeon', '', '', 'where is slave pens|what level is sp|who are the bosses in slave pens|last boss of slave pens|who is quagmirran|how many bosses in the slave pens|where is the entrance to slave pens|what dungeon for cenarion expedition rep|how do i get to slave pens zangarmarsh|mennu rokmar quagmirran dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_coilfang_the_underbog', 'Coilfang: The Underbog', 'Coilfang: The Underbog is a level 63 to 65 five-player dungeon in Zangarmarsh. The Black Stalker at the bottom is a giant electrified spider that levitates the party. Its bosses are Hungarfen, Ghaz''an, Swamplord Musel''ek, and The Black Stalker.', 'underbog,ub', 'instance,dungeon', '', '', 'where is underbog|what level is ub|who are the bosses in underbog|last boss of underbog|who is the black stalker|how many bosses in the underbog|where is the entrance to underbog|how do i get to the underbog|hungarfen ghaz''an musel''ek dungeon|which coilfang dungeon has a spider boss');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_auchindoun_mana_tombs', 'Auchindoun: Mana-Tombs', 'Auchindoun: Mana-Tombs is a level 64 to 66 five-player dungeon in Terokkar Forest. It is the Consortium''s wing of Auchindoun, and the ethereal prince at the end is one of the easier Outland end bosses. Its bosses are Pandemonius, Tavarok, and Nexus-Prince Shaffar.', 'mana tombs,mt', 'instance,dungeon', '', '', 'where is mana tombs|what level is mt dungeon|who are the bosses in mana tombs|last boss of mana tombs|who is nexus prince shaffar|how many bosses in mana-tombs|where is the entrance to mana tombs|is mana tombs easy|pandemonius tavarok shaffar dungeon|how do i get to mana tombs terokkar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_auchindoun_auchenai_crypts', 'Auchindoun: Auchenai Crypts', 'Auchindoun: Auchenai Crypts is a level 65 to 67 five-player dungeon in Terokkar Forest. It is full of undead draenei, and Shirrak the Dead Watcher slows casting for the whole room. Its bosses are Shirrak the Dead Watcher, and Exarch Maladaar.', 'auchenai crypts,crypts,ac', 'instance,dungeon', '', '', 'where is auchenai crypts|what level is ac dungeon|who are the bosses in auchenai crypts|last boss of crypts|who is exarch maladaar|who is shirrak|how many bosses in auchenai crypts|where is the entrance to auchenai crypts|how do i get to the crypts terokkar|which auchindoun wing has undead draenei');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_opening_of_the_dark_portal', 'Opening of the Dark Portal', 'Opening of the Dark Portal is a level 68 to 70 five-player dungeon in the Caverns of Time in Tanaris. Players usually call it the Black Morass. It is a timed defence of Medivh through eighteen portal waves at the moment the Dark Portal was first opened, and it was the attunement step for Karazhan. The Dark Portal itself stands in the Blasted Lands, and this instance is only a vision of its past. Its bosses are Chrono Lord Deja, Temporus, and Aeonus.', 'black morass,bm,opening of the dark portal,cot2', 'instance,dungeon', '', '', 'where is black morass|what level is bm dungeon|what is opening of the dark portal|how many portal waves in black morass|who are the bosses in black morass|last boss of black morass|is bm the karazhan attunement|who is aeonus|where is the entrance to black morass|how do i get to the black morass|is the dark portal instance in blasted lands');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_auchindoun_sethekk_halls', 'Auchindoun: Sethekk Halls', 'Auchindoun: Sethekk Halls is a level 67 to 68 five-player dungeon in Terokkar Forest. The arakkoa wing of Auchindoun, and on heroic it holds Anzu, the raven god summoned by druids for their flight-form quest. Its bosses are Darkweaver Syth, Talon King Ikiss, and Anzu.', 'sethekk halls,sethekk', 'instance,dungeon', '', '', 'where is sethekk halls|what level is sethekk|who are the bosses in sethekk halls|last boss of sethekk|who is anzu|how many bosses in sethekk halls|where do i get anzu for druid flight form|where is the entrance to sethekk|talon king ikiss dungeon|how do i get to sethekk halls terokkar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_auchindoun_shadow_labyrinth', 'Auchindoun: Shadow Labyrinth', 'Auchindoun: Shadow Labyrinth is a level 69 to 70 five-player dungeon in Terokkar Forest. It is the longest and hardest Auchindoun wing, and Murmur at the end is a sound elemental with a room-wide pull-and-detonate. Its bosses are Ambassador Hellmaw, Blackheart the Inciter, Grandmaster Vorpil, and Murmur.', 'shadow labyrinth,shadow lab,slabs', 'instance,dungeon', '', '', 'where is shadow labyrinth|what level is slabs|shadow lab bosses|last boss of shadow labs|who is murmur|how many bosses in shadow labyrinth|is shadow lab the hardest auchindoun|where is the entrance to slabs|who is blackheart the inciter|how do i get to shadow labs terokkar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_hellfire_citadel_the_shattered_halls', 'Hellfire Citadel: The Shattered Halls', 'Hellfire Citadel: The Shattered Halls is a level 69 to 70 five-player dungeon in Hellfire Peninsula. It has a reputation as the hardest of the Hellfire wings, and its heroic version runs on a timer to rescue prisoners. Its bosses are Grand Warlock Nethekurse, Blood Guard Porung, Warbringer O''mrogg, and Warchief Kargath Bladefist.', 'shattered halls,sh', 'instance,dungeon', '', '', 'where is shattered halls|what level is sh dungeon|who are the bosses in shattered halls|last boss of shattered halls|who is kargath bladefist|how many bosses in shattered halls|is shattered halls hard|what is the timer on heroic shattered halls|where is the entrance to shattered halls|nethekurse porung o''mrogg kargath dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_coilfang_the_steamvault', 'Coilfang: The Steamvault', 'Coilfang: The Steamvault is a level 69 to 70 five-player dungeon in Zangarmarsh. It is the deepest Coilfang wing and the last step of the old Karazhan-era Cenarion Expedition grind. Its bosses are Hydromancer Thespia, Mekgineer Steamrigger, and Warlord Kalithresh.', 'steamvault,sv', 'instance,dungeon', '', '', 'where is steamvault|what level is sv dungeon|who are the bosses in steamvault|last boss of steamvault|who is warlord kalithresh|how many bosses in the steamvault|where is the entrance to steamvault|steamvault cenarion expedition grind|who is mekgineer steamrigger|how do i get to steamvault zangarmarsh');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_tempest_keep_the_mechanar', 'Tempest Keep: The Mechanar', 'Tempest Keep: The Mechanar is a level 69 to 70 five-player dungeon in Netherstorm. It is one of the three satellite wings of Tempest Keep, all mechanical, and the shortest of them. Its bosses are Mechano-Lord Capacitus, Nethermancer Sepethrea, and Pathaleon the Calculator.', 'mechanar,mech', 'instance,dungeon', '', '', 'where is mechanar|what level is mech dungeon|who are the bosses in mechanar|last boss of mechanar|who is pathaleon the calculator|how many bosses in the mechanar|where is the entrance to mechanar|which tempest keep dungeon is shortest|capacitus sepethrea pathaleon dungeon|how do i get to mechanar netherstorm');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_tempest_keep_the_botanica', 'Tempest Keep: The Botanica', 'Tempest Keep: The Botanica is a level 69 to 70 five-player dungeon in Netherstorm. It is a greenhouse wing of Tempest Keep, and Warp Splinter at the end summons saplings that must be killed fast. Its bosses are Commander Sarannis, High Botanist Freywinn, Thorngrin the Tender, Laj, and Warp Splinter.', 'botanica,bot', 'instance,dungeon', '', '', 'where is botanica|what level is bota|who are the bosses in botanica|last boss of botanica|who is warp splinter|how many bosses in the botanica|where is the entrance to botanica|which tempest keep dungeon is the greenhouse|who is high botanist freywinn|how do i get to botanica netherstorm');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_tempest_keep_the_arcatraz', 'Tempest Keep: The Arcatraz', 'Tempest Keep: The Arcatraz is a level 69 to 70 five-player dungeon in Netherstorm. It is a prison wing holding things the naaru locked away, and it was the attunement step for the Black Temple. Its bosses are Zereketh the Unbound, Dalliah the Doomsayer, Wrath-Scryer Soccothrates, and Harbinger Skyriss.', 'arcatraz,arc', 'instance,dungeon', '', '', 'where is arcatraz|what level is arc dungeon|who are the bosses in arcatraz|last boss of arcatraz|who is harbinger skyriss|how many bosses in the arcatraz|is arcatraz the black temple attunement|where is the entrance to arcatraz|zereketh dalliah soccothrates skyriss dungeon|how do i get to arcatraz netherstorm');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_magister_s_terrace', 'Magister''s Terrace', 'Magister''s Terrace is a level 69 to 70 five-player dungeon in the Isle of Quel''Danas. It was added in patch 2.4 as the last Burning Crusade dungeon, and its heroic mode drops the Swift White Hawkstrider mount. Its bosses are Selin Fireheart, Vexallus, Priestess Delrissa, and Kael''thas Sunstrider.', 'magisters terrace,mgt,magister''s terrace', 'instance,dungeon', '', '', 'where is magisters terrace|what level is mgt|who are the bosses in magisters terrace|last boss of mgt|how do i get the swift white hawkstrider|who is kael''thas in mgt|how many bosses in mgt|where is the entrance to magister''s terrace|what is the isle of quel''danas dungeon|who is priestess delrissa');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_karazhan', 'Karazhan', 'Karazhan is a level 70 to 73 ten-player raid in Deadwind Pass. It is Medivh''s abandoned tower and the entry raid of the Burning Crusade, known for its chess event and an optional opera encounter that rotates between three scripts. Its bosses are Attumen the Huntsman, Moroes, Maiden of Virtue, Opera Event, The Curator, Terestian Illhoof, Shade of Aran, Netherspite, Chess Event, Prince Malchezaar, and Nightbane.', 'karazhan,kara,kz', 'instance,raid', '', '', 'where is karazhan|what level is kara|how many bosses in karazhan|who is the last boss of kara|is karazhan 10 man|where is the entrance to karazhan deadwind pass|what is the opera event in kara|what is the chess event|who is prince malchezaar|whose tower is karazhan|how do i get to kara|kara bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_gruul_s_lair', 'Gruul''s Lair', 'Gruul''s Lair is a level 70 twenty-five-player raid in Blade''s Edge Mountains. Two bosses only: a five-ogre council fight and then Gruul himself, who grows in size and damage on a timer. Its bosses are High King Maulgar, and Gruul the Dragonkiller.', 'gruuls lair,gruul', 'instance,dungeon', '', '', 'where is gruul''s lair|what level is gruul|how many bosses in gruul''s lair|who is high king maulgar|gruuls lair 25 man|where is the entrance to gruul''s lair|who is the last boss of gruul''s lair|blade''s edge raid|how do i get to gruul|what is gruul the dragonkiller');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_magtheridon_s_lair', 'Magtheridon''s Lair', 'Magtheridon''s Lair is a level 70 twenty-five-player raid in Hellfire Peninsula. A single boss beneath Hellfire Citadel, fought while five channelers hold him in place. Its boss is Magtheridon.', 'magtheridons lair,magtheridon,mag', 'instance,dungeon', '', '', 'where is magtheridon''s lair|what level is mag raid|how many bosses in magtheridon''s lair|what are the channelers in mag|where is the entrance to magtheridon|mag lair 25 man|raid beneath hellfire citadel|how do i get to magtheridon|who is the boss of magtheridon''s lair|magtheridon hellfire peninsula raid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_coilfang_serpentshrine_cavern', 'Coilfang: Serpentshrine Cavern', 'Coilfang: Serpentshrine Cavern is a level 70 twenty-five-player raid in Zangarmarsh. It is the raid wing of Coilfang Reservoir and ends with Lady Vashj, whose fight requires relaying tainted cores between phases. Its bosses are Hydross the Unstable, The Lurker Below, Leotheras the Blind, Fathom-Lord Karathress, Morogrim Tidewalker, and Lady Vashj.', 'serpentshrine cavern,ssc,vashj', 'instance,dungeon', '', '', 'where is ssc|what level is serpentshrine cavern|how many bosses in ssc|who is the last boss of ssc|who is lady vashj|where is the entrance to serpentshrine|ssc 25 man raid|what are tainted cores|who is the lurker below|how do i get to serpentshrine cavern zangarmarsh|ssc bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_tempest_keep', 'Tempest Keep', 'Tempest Keep is a level 70 twenty-five-player raid in Netherstorm. Usually called The Eye; it is the central spire of Tempest Keep and ends with Kael''thas Sunstrider in a long multi-phase fight. Its bosses are Al''ar, Void Reaver, High Astromancer Solarian, and Kael''thas Sunstrider.', 'tempest keep,the eye,tk', 'instance,dungeon', '', '', 'where is the eye|what level is tempest keep raid|tk raid bosses|how many bosses in tk|who is the last boss of the eye|who is kael''thas sunstrider|where is the entrance to the eye netherstorm|tk 25 man|who is void reaver|how do i get to tempest keep raid|who is al''ar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_battle_for_mount_hyjal', 'The Battle for Mount Hyjal', 'The Battle for Mount Hyjal is a level 70 twenty-five-player raid in the Caverns of Time in Tanaris. It replays the battle at the World Tree as eight waves of trash between bosses, which makes it far more trash-heavy than any other raid of its tier. Its bosses are Rage Winterchill, Anetheron, Kaz''rogal, Azgalor, and Archimonde.', 'mount hyjal,hyjal,mh,battle for mount hyjal', 'instance,dungeon', '', '', 'where is hyjal|what level is mount hyjal raid|how many bosses in hyjal|who is the last boss of hyjal|who is archimonde|how many waves in hyjal|where is the entrance to hyjal caverns of time|hyjal 25 man|is hyjal trash heavy|who is rage winterchill|how do i get to battle for mount hyjal');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_black_temple', 'Black Temple', 'Black Temple is a level 70 twenty-five-player raid in Shadowmoon Valley. Illidan Stormrage''s fortress and the intended final raid of the Burning Crusade before the Sunwell was added. Its bosses are High Warlord Naj''entus, Supremus, Shade of Akama, Teron Gorefiend, Gurtogg Bloodboil, Reliquary of Souls, Mother Shahraz, The Illidari Council, and Illidan Stormrage.', 'black temple,bt,illidan', 'instance,dungeon', '', '', 'where is black temple|what level is bt|how many bosses in bt|who is the last boss of black temple|who is illidan|where is the entrance to black temple|bt 25 man raid|black temple shadowmoon valley location|who is the illidari council|how do i get to bt|bt bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_zul_aman', 'Zul''Aman', 'Zul''Aman is a level 70 to 73 ten-player raid in the Ghostlands. Added in patch 2.3, it runs on a timer: clearing the four animal-god bosses fast enough rewards the Amani War Bear. Its bosses are Akil''zon, Nalorakk, Jan''alai, Halazzi, Hex Lord Malacrass, and Zul''jin.', 'zulaman,za,zul aman', 'instance,raid', '', '', 'where is zul''aman|what level is za|how many bosses in za|who is the last boss of zul''aman|how do i get the amani war bear|who is zul''jin|za timed run reward|where is the entrance to zul aman ghostlands|is za a 10 man|who is akil''zon|za bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_the_sunwell', 'The Sunwell', 'The Sunwell is a level 70 twenty-five-player raid in the Isle of Quel''Danas. Added in patch 2.4 as the final raid of the Burning Crusade, and its gear was the last tier before Wrath launched. Its bosses are Kalecgos, Brutallus, Felmyst, The Eredar Twins, M''uru, and Kil''jaeden.', 'sunwell plateau,sunwell,swp', 'instance,dungeon', '', '', 'where is sunwell|what level is sunwell plateau|how many bosses in sunwell|who is the last boss of sunwell|who is kil''jaeden|where is the entrance to sunwell isle of quel''danas|swp 25 man raid|last raid of burning crusade|who is m''uru|how do i get to sunwell|sunwell bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_ragefire_chasm', 'Ragefire Chasm', 'Ragefire Chasm is a level 15 to 16 five-player dungeon in Orgrimmar, through the Cleft of Shadow. It is the lowest-level dungeon in the game and the only one inside a capital city. Its bosses are Oggleflint, Taragaman the Hungerer, Jergosh the Invoker, and Bazzalan.', 'ragefire chasm,rfc', 'instance,dungeon', '', '', 'where is ragefire chasm|what level is rfc|who are the bosses in rfc|last boss of ragefire chasm|who is bazzalan|lowest level dungeon in the game|how do i get to rfc from orgrimmar|where is the cleft of shadow|how many bosses in ragefire chasm|horde starter dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_deadmines', 'Deadmines', 'Deadmines is a level 17 to 20 five-player dungeon in Westfall. It runs through a mine and out onto a pirate ship moored in a cavern, and Edwin VanCleef leads the Defias Brotherhood at the end. Its bosses are Rhahk''Zor, Sneed, Gilnid, Mr. Smite, Cookie, Captain Greenskin, and Edwin VanCleef.', 'deadmines,vc,the deadmines,mine cart,van cleef,defias', 'instance,dungeon', '', '', 'where is deadmines|what level is dm|who are the bosses in deadmines|last boss of deadmines|who is vancleef|how many bosses in dm|where is the entrance to deadmines westfall|how do i get to the deadmines|is the deadmines on a pirate ship|where is the dm ship fight|mr smite cookie greenskin dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_wailing_caverns', 'Wailing Caverns', 'Wailing Caverns is a level 17 to 20 five-player dungeon in the Barrens. It is a maze of twisting tunnels with no clear route, which is most of its reputation. Its bosses are Lady Anacondra, Lord Cobrahn, Kresh, Lord Pythas, Skum, Lord Serpentis, Verdan the Everliving, and Mutanus the Devourer.', 'wailing caverns,wc,naralex,emerald dream', 'instance,dungeon', '', '', 'where is wailing caverns|what level is wc|who are the bosses in wc|last boss of wailing caverns|who is mutanus the devourer|how many bosses in wailing caverns|where is the entrance to wc barrens|how do i get to wailing caverns|is wc a maze|naralex wc');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_shadowfang_keep', 'Shadowfang Keep', 'Shadowfang Keep is a level 18 to 21 five-player dungeon in Silverpine Forest. It is a haunted worgen castle, and the renegade mage Archmage Arugal waits at the top. Its bosses are Rethilgore, Razorclaw the Butcher, Baron Silverlaine, Commander Springvale, Odo the Blindwatcher, Fenrus the Devourer, Wolf Master Nandos, and Archmage Arugal.', 'shadowfang keep,sfk', 'instance,dungeon', '', '', 'where is shadowfang keep|what level is sfk|who are the bosses in sfk|last boss of shadowfang|who is arugal|how many bosses in shadowfang keep|where is the entrance to sfk silverpine|how do i get to sfk|baron silverlaine commander springvale dungeon|worgen castle dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_blackfathom_deeps', 'Blackfathom Deeps', 'Blackfathom Deeps is a level 21 to 24 five-player dungeon in Ashenvale. A flooded night elf temple to an old naga-worshipped god, with a long underwater stretch. Its bosses are Ghamoo-ra, Lady Sarevess, Gelihast, Lorgus Jett, Old Serra''kis, Twilight Lord Kelris, and Aku''mai.', 'blackfathom deeps,bfd,twilight hammer', 'instance,dungeon', '', '', 'where is blackfathom deeps|what level is bfd|who are the bosses in bfd|last boss of blackfathom|who is aku''mai|how many bosses in blackfathom deeps|where is the entrance to bfd ashenvale|how do i get to bfd|is there an underwater part in bfd|gelihast lorgus jett twilight lord kelris dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_stormwind_stockade', 'Stormwind Stockade', 'Stormwind Stockade is a level 22 to 25 five-player dungeon in Stormwind City. A short prison-riot dungeon under the Trade District, and one of the fastest runs in the game. Its bosses are Targorr the Dread, Kam Deepfury, Hamhock, Bazil Thredd, and Dextren Ward.', 'stockade,stocks,stormwind stockade', 'instance,dungeon', '', '', 'where is stockade|what level is the stockade|who are the bosses in the stockade|last boss of stockade|who is dextren ward|how many bosses in stormwind stockade|where is the entrance to the stockade|how do i get to the stockade stormwind|fastest low level dungeon|targorr kam deepfury hamhock dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_razorfen_kraul', 'Razorfen Kraul', 'Razorfen Kraul is a level 24 to 27 five-player dungeon in the Southern Barrens. An outdoor quilboar warren built from thorns rather than an indoor dungeon. Its bosses are Roogug, Aggem Thorncurse, Death Speaker Jargba, Overlord Ramtusk, Agathelos the Raging, and Charlga Razorflank.', 'razorfen kraul,rfk', 'instance,dungeon', '', '', 'where is razorfen kraul|what level is rfk|who are the bosses in rfk|last boss of razorfen kraul|who is charlga razorflank|how many bosses in rfk|where is the entrance to rfk barrens|how do i get to razorfen kraul|roogug agathelos overlord ramtusk dungeon|quilboar thorn warren dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_gnomeregan', 'Gnomeregan', 'Gnomeregan is a level 25 to 28 five-player dungeon in Dun Morogh. The irradiated gnome capital, and Mekgineer Thermaplugg at the end is fought around a room of bomb-dispensing panels. Its bosses are Grubbis, Viscous Fallout, Electrocutioner 6000, Crowd Pummeler 9-60, and Mekgineer Thermaplugg.', 'gnomeregan,gnomer', 'instance,dungeon', '', '', 'where is gnomeregan|what level is gnomer|who are the bosses in gnomer|last boss of gnomeregan|who is thermaplugg|how many bosses in gnomeregan|where is the entrance to gnomer dun morogh|how do i get to gnomeregan|grubbis electrocutioner crowd pummeler dungeon|irradiated gnome city dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_scarlet_monastery', 'Scarlet Monastery', 'Scarlet Monastery is a level 29 to 40 five-player dungeon in Tirisfal Glades. It is four separate wings behind one entrance -- Graveyard, Library, Armory and Cathedral -- run at increasing levels rather than as one dungeon. Its bosses are Interrogator Vishas, Bloodmage Thalnos, Houndmaster Loksey, Arcanist Doan, Herod, High Inquisitor Fairbanks, and High Inquisitor Whitemane.', 'scarlet monastery,sm,smc', 'instance,dungeon', '', '', 'where is scarlet monastery|what level is sm|what are the sm wings|who are the bosses in scarlet monastery|who is herod|who is whitemane|how many bosses in sm|where is the entrance to scarlet monastery tirisfal|graveyard library armory cathedral which levels|how do i get to sm|last boss of scarlet monastery');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_razorfen_downs', 'Razorfen Downs', 'Razorfen Downs is a level 34 to 37 five-player dungeon in the Southern Barrens. The undead half of the quilboar warrens, ending with the lich Amnennar the Coldbringer. Its bosses are Tuten''kash, Mordresh Fire Eye, Glutton, and Amnennar the Coldbringer.', 'razorfen downs,rfd', 'instance,dungeon', '', '', 'where is razorfen downs|what level is rfd|who are the bosses in rfd|last boss of razorfen downs|who is amnennar the coldbringer|how many bosses in rfd|where is the entrance to rfd southern barrens|how do i get to razorfen downs|tuten''kash mordresh glutton dungeon|undead quilboar dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_uldaman', 'Uldaman', 'Uldaman is a level 37 to 40 five-player dungeon in the Badlands. A titan vault, and the first place most players meet the dwarves'' own origin story. Its bosses are Revelosh, Baelog, Ironaya, Ancient Stone Keeper, Galgann Firehammer, Grimlok, and Archaedas.', 'uldaman,ulda', 'instance,dungeon', '', '', 'where is uldaman|what level is ulda|who are the bosses in uldaman|last boss of uldaman|who is archaedas|how many bosses in uldaman|where is the entrance to uldaman badlands|how do i get to uldaman|revelosh baelog ironaya dungeon|titan vault dungeon badlands');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_maraudon', 'Maraudon', 'Maraudon is a level 41 to 48 five-player dungeon in Desolace. Split into orange, purple and pristine sections with separate entrances, ending at Princess Theradras. Its bosses are Noxxion, Razorlash, Lord Vyletongue, Celebras the Cursed, Landslide, Tinkerer Gizlock, Rotgrip, and Princess Theradras.', 'maraudon,mara,centaur,valley of spears', 'instance,dungeon', '', '', 'where is maraudon|what level is mara|who are the bosses in maraudon|last boss of maraudon|who is princess theradras|how many bosses in mara|what are the maraudon wings|where is the entrance to maraudon desolace|orange purple pristine maraudon entrances|how do i get to maraudon|noxxion lord vyletongue celebras dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_zul_farrak', 'Zul''Farrak', 'Zul''Farrak is a level 43 to 46 five-player dungeon in Tanaris. Best known for the pyramid steps, where a huge troll wave attacks at once, and for Gahz''rilla. Its bosses are Hydromancer Velratha, Antu''sul, Theka the Martyr, Witch Doctor Zum''rah, Nekrum Gutchewer, Chief Ukorz Sandscalp, and Gahz''rilla.', 'zulfarrak,zf,sandfury,antusul,zul farrak', 'instance,dungeon', '', '', 'where is zul''farrak|what level is zf|who are the bosses in zf|last boss of zul''farrak|who is gahz''rilla|how many bosses in zul farrak|where is the entrance to zf tanaris|how do i get to zul''farrak|what is the pyramid event in zf|antu''sul theka zum''rah dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_sunken_temple', 'Sunken Temple', 'Sunken Temple is a level 47 to 50 five-player dungeon in the Swamp of Sorrows. Properly the Temple of Atal''Hakkar; it is a confusing layered ruin and a long run for its level. Its bosses are Atal''alarion, Dreamscythe, Weaver, Jammal''an the Prophet, Morphaz, Hazzas, and Shade of Eranikus.', 'sunken temple,st,temple of atalhakkar,atal''ai,avatar of hakkar', 'instance,dungeon', '', '', 'where is sunken temple|what level is st|who are the bosses in sunken temple|last boss of sunken temple|who is shade of eranikus|how many bosses in st|where is the temple of atal''hakkar|where is the entrance to sunken temple swamp of sorrows|how do i get to sunken temple|is sunken temple confusing|atal''alarion jammal''an hazzas dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_blackrock_depths', 'Blackrock Depths', 'Blackrock Depths is a level 49 to 56 five-player dungeon in Blackrock Mountain. By far the largest dungeon in the game, with a bar, an arena and a prison inside it, ending at Emperor Dagran Thaurissan. Its bosses are Lord Roccor, High Interrogator Gerstahn, Houndmaster Grebmar, Pyromancer Loregrain, Lord Incendius, Warder Stilgiss, Fineous Darkvire, Bael''Gar, General Angerforge, Golem Lord Argelmach, Ambassador Flamelash, Magmus, and Emperor Dagran Thaurissan.', 'blackrock depths,brd,dark iron,dwarves', 'instance,dungeon', '', '', 'where is blackrock depths|what level is brd|who are the bosses in brd|last boss of blackrock depths|who is emperor thaurissan|how many bosses in brd|where is the entrance to brd|how do i get to brd|is brd the biggest dungeon|who is general angerforge|what is in the brd arena|who is lord roccor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_blackrock_spire', 'Blackrock Spire', 'Blackrock Spire is a level 57 to 63 five- and ten-player dungeon in Blackrock Mountain. Split into Lower and Upper halves sharing one entrance; Upper was originally a ten-player raid. Its bosses are Highlord Omokk, Shadow Hunter Vosh''gajin, War Master Voone, Mother Smolderweb, Quartermaster Zigris, Halycon, Overlord Wyrmthalak, Pyroguard Emberseer, Warchief Rend Blackhand, The Beast, and General Drakkisath.', 'blackrock spire,lbrs,ubrs,burning steppes,dragonkin', 'instance,raid', '', '', 'where is blackrock spire|what level is brs|lbrs vs ubrs|who are the bosses in brs|last boss of ubrs|who is general drakkisath|who is rend blackhand|where is the entrance to brs|how do i get to blackrock spire|is ubrs 10 man|how many bosses in blackrock spire|what level is ubrs');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_dire_maul', 'Dire Maul', 'Dire Maul is a level 55 to 60 five-player dungeon in Feralas. Three separate wings -- East, West and North -- and the North wing has a well-known trick for looting the king''s tribute without killing him. Its bosses are Zevrim Thornhoof, Hydrospawn, Lethtendris, Alzzin the Wildshaper, Illyanna Ravenoak, Magister Kalendris, Immol''thar, Tendris Warpwood, Prince Tortheldrin, Guard Mol''dar, Stomper Kreeg, Guard Fengus, Guard Slip''kik, Captain Kromcrush, Cho''Rush the Observer, and King Gordok.', 'dire maul,dm east,dm west,dm north,warpwood quarter,capital gardens,gordok commons,ogres,pusillin', 'instance,dungeon', '', '', 'where is dire maul|what level is dm east|who are the bosses in dire maul|last boss of dire maul|who is king gordok|what are the dire maul wings|how many bosses in dm north|where is the entrance to dire maul feralas|how do i get to dire maul|dm north tribute run|how to loot the tribute without killing the king|dm west east north bosses');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_scholomance', 'Scholomance', 'Scholomance is a level 58 to 60 five-player dungeon in the Western Plaguelands. A necromancy school inside Caer Darrow, ending with Darkmaster Gandling. Its bosses are Jandice Barov, Rattlegore, Marduk Blackpool, Vectus, Ras Frostwhisper, Instructor Malicia, Doctor Theolen Krastinov, Lorekeeper Polkelt, The Ravenian, Lord Alexei Barov, Lady Illucia Barov, and Darkmaster Gandling.', 'scholomance,scholo,kirtonos,scourge,caer darrow', 'instance,dungeon', '', '', 'where is scholomance|what level is scholo|who are the bosses in scholo|last boss of scholomance|who is darkmaster gandling|how many bosses in scholomance|where is the entrance to scholomance plaguelands|how do i get to scholo|where is caer darrow|rattlegore ras frostwhisper dungeon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_stratholme', 'Stratholme', 'Stratholme is a level 58 to 60 five-player dungeon in the Eastern Plaguelands. Two separate entrances: the Scarlet side and the undead side, where Baron Rivendare drops the Deathcharger''s Reins on a timed run. Its bosses are The Unforgiven, Hearthsinger Forresten, Timmy the Cruel, Cannon Master Willey, Archivist Galford, Balnazzar, Baroness Anastari, Nerub''enkan, Maleki the Pallid, Ramstein the Gorger, Magistrate Barthilas, and Baron Rivendare.', 'stratholme,strat,live side,baron run,scarlet crusade,scourge,plague', 'instance,dungeon', '', '', 'where is stratholme|what level is strat|who are the bosses in strat|last boss of stratholme|who is baron rivendare|how do i get the deathcharger|how many bosses in strat|where is the entrance to stratholme eastern plaguelands|how do i get to strat|strat live vs strat undead|what is the timed run in stratholme');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_molten_core', 'Molten Core', 'Molten Core is a level 60 to 63 forty-player raid in Blackrock Mountain. The game''s first full raid tier, ten bosses ending at Ragnaros, and the source of Tier 1 armour. Its bosses are Lucifron, Magmadar, Gehennas, Garr, Shazzrah, Baron Geddon, Sulfuron Harbinger, Golemagg the Incinerator, Majordomo Executus, and Ragnaros.', 'molten core,mc,fire elementals', 'instance,raid', '', '', 'where is molten core|what level is mc|how many bosses in mc|who is the last boss of molten core|who is ragnaros|where is the entrance to mc blackrock mountain|mc 40 man raid|how do i get to molten core|what tier set drops in mc|who is majordomo|mc bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_blackwing_lair', 'Blackwing Lair', 'Blackwing Lair is a level 60 to 63 forty-player raid in Blackrock Mountain. Nefarian''s lair above Blackrock Spire, and the source of Tier 2 armour. Its bosses are Razorgore the Untamed, Vaelastrasz the Corrupt, Broodlord Lashlayer, Firemaw, Ebonroc, Flamegor, Chromaggus, and Nefarian.', 'blackwing lair,bwl,black dragonflight,drakes', 'instance,raid', '', '', 'where is blackwing lair|what level is bwl|how many bosses in bwl|who is the last boss of blackwing lair|who is nefarian|where is the entrance to bwl|bwl 40 man raid|how do i get to bwl|what tier set drops in bwl|t2 raid where|bwl bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_zul_gurub', 'Zul''Gurub', 'Zul''Gurub is a level 57 to 63 twenty-player raid in Stranglethorn Vale. A troll city raid on a three-day lockout, ending at the blood god Hakkar. Its bosses are High Priest Venoxis, High Priestess Jeklik, High Priestess Mar''li, Bloodlord Mandokir, Gahz''ranka, High Priest Thekal, High Priestess Arlokk, Jin''do the Hexxer, and Hakkar.', 'zulgurub,zg,gurubashi,zul gurub', 'instance,raid', '', '', 'where is zul''gurub|what level is zg|how many bosses in zg|who is the last boss of zul''gurub|who is hakkar|where is the entrance to zg stranglethorn|zg 20 man raid|how do i get to zg|what is the lockout for zg|who is bloodlord mandokir|zg bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_ruins_of_ahn_qiraj', 'Ruins of Ahn''Qiraj', 'Ruins of Ahn''Qiraj is a level 60 to 63 twenty-player raid in Silithus. The smaller of the two Ahn''Qiraj raids, opened by the same war effort as the Temple. Its bosses are Kurinnaxx, General Rajaxx, Moam, Buru the Gorger, Ayamiss the Hunter, and Ossirian the Unscarred.', 'ruins of ahnqiraj,aq20,qiraji,silithid,ruins of ahn qiraj', 'instance,raid', '', '', 'where is ruins of ahn''qiraj|what level is aq20|how many bosses in aq20|who is the last boss of ruins of ahn qiraj|who is ossirian|where is the entrance to aq ruins silithus|ruins of aq 20 man|how do i get to aq20|difference between aq20 and aq40|kurinnaxx rajaxx moam buru ayamiss which raid|ruins of aq bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('instance_ahn_qiraj_temple', 'Ahn''Qiraj Temple', 'Ahn''Qiraj Temple is a level 60 to 63 forty-player raid in Silithus. The larger Ahn''Qiraj raid, ending at C''Thun, and the source of Tier 2.5 armour. Its bosses are The Prophet Skeram, Battleguard Sartura, Fankriss the Unyielding, Viscidus, Princess Huhuran, Twin Emperors, Ouro, and C''Thun.', 'temple of ahnqiraj,aq40,aq,qiraji,silithid,temple of ahn qiraj', 'instance,raid', '', '', 'where is ahn''qiraj temple|what level is aq40|how many bosses in aq40|who is the last boss of aq temple|who is c''thun|where is the entrance to aq40 silithus|temple of aq 40 man|how do i get to aq40|what tier set drops in aq40|t2.5 raid where|twin emperors skeram viscidus which raid|aq temple bosses list');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_quality', 'Item Quality Colors', 'An item''s name is colored by its quality: grey is poor, junk sold to vendors; white is common; green is uncommon; blue is rare; purple is epic; orange is legendary; and light gold marks bind-to-account heirlooms. Higher quality means better stats for the item level, and purple gear mostly comes from heroics and raids.', 'item quality,item colors,item colours,colors on item,color of items,item rarity,green items,blue items,purple items,grey items,gray items,white items,orange items,greens,blues,purples,epics', 'items,quality,basics', '', '', 'what do the item colors mean|what does purple gear mean|what is a blue item|what color is epic|what is a green item|what color is legendary|what are grey items|can i sell grey items to a vendor|what is orange gear|what is the light gold item color|what does gold item text mean|what is the difference between rare and epic|where does purple gear drop|what is an uncommon item|what is junk gear|which items are heirlooms by color');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_tier_sets', 'Tier Sets', 'Each class''s tier set gives a bonus at 2 and at 4 pieces worn. Wrath has Tier 7 from Naxxramas, Tier 8 from Ulduar, Tier 9 from Trial of the Crusader and Tier 10 from Icecrown Citadel. Tier 9 is bought with Emblems of Triumph and Tier 10 with Emblems of Frost, then upgraded with Marks of Sanctification from ICC bosses.', 'tier sets,tier set,tier,t7,t8,t9,t10,set bonus,tier bonus,2pc,4pc,marks of sanctification,tier token,tier tokens', 'items,equipment,raid,tier', '', '', 'what is tier gear|what is t7|what is t8|what is t9|what is t10|where do i get t10|where does tier 9 come from|how do i get tier sets|what is a 2 piece bonus|what are set bonuses|how do i upgrade tier gear|what are marks of sanctification|how do i buy t9 with triumph|which raid drops t7|what are 4 piece bonuses|tier 8 from ulduar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_legendary_weapons', 'Legendary Weapons', 'Wrath''s legendaries are Val''anyr, Hammer of Ancient Kings, a healer''s mace built from 30 Fragments of Val''anyr from 25-player Ulduar, and Shadowmourne, a two-handed axe for warriors, paladins and death knights from a 25-player Icecrown Citadel quest chain. Older ones include Thunderfury, Sulfuras, the Warglaives of Azzinoth from Illidan and Thori''dal from the Sunwell.', 'legendary,legendaries,shadowmourne,valanyr,val anyr,thunderfury,sulfuras,atiesh,warglaives,glaives,thoridal', 'items,weapons,legendary,rare', '', '', 'what are the legendary weapons|how do i get shadowmourne|how do i get val''anyr|what is shadowmourne|who can use shadowmourne|what is the healer legendary mace|what are fragments of val''anyr|how do i get thunderfury|where does sulfuras drop|how do i get warglaives|where does thori''dal come from|what legendaries are in wotlk|legendary axe icc quest|is there a legendary for healers|legendary weapon quest chain|where do i get a legendary');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_profession_tools', 'Profession Tools', 'Some professions need a tool in the bags before their recipes work: blacksmiths a Blacksmith Hammer, engineers an Arclight Spanner, enchanters a runed rod matched to their skill, miners a Mining Pick and skinners a Skinning Knife. Smithing and smelting also need you standing beside an anvil or a forge. Crafting never fails.', 'profession tool,profession tools,blacksmith hammer,skinning knife,mining pick,runed rod,arclight spanner,anvil,forge', 'items,professions,tools,crafting', '', '', 'what tools do i need for my profession|why cant i craft anything|what do blacksmiths need|do i need a hammer for blacksmithing|what is an arclight spanner|what do enchanters need|what is a runed rod|do i need a mining pick|do i need a skinning knife|why is my smelting not working|do i need to be at a forge|do i need an anvil for blacksmithing|can crafting fail|why cant i smelt|where do i get a skinning knife|which tool for engineering');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_mounts_collection', 'Mount Collection', 'Famous rare mount drops include Invincible from the heroic 25-player Lich King, Mimiron''s Head from Yogg-Saron on 25 with no Keepers, the Blue Proto-Drake from Skadi in heroic Utgarde Pinnacle, Ashes of Al''ar from Kael''thas and Deathcharger''s Reins from Baron Rivendare in Stratholme. Owning 50 mounts earns the Albino Drake.', 'mount collection,rare mount,rare mounts,invincible,mimirons head,ashes of alar,deathcharger,deathchargers reins,blue proto drake,albino drake,mount drop,50 mounts,100 mounts', 'items,mounts,collection,rare', '', '', 'what are the rare mounts|how do i get the invincible mount|how do i get mimiron''s head|how do i get the blue proto drake|where does the blue drake drop|how do i get ashes of al''ar|where does deathcharger drop|how do i get the albino drake|how many mounts for the albino drake|rare mount drops wotlk|how do i get the deathcharger|which boss drops the skull mount|how do i get a drake mount|what mounts drop from raids|mount farming tips|how do i get a rare mount|where do i farm for mounts');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_enchants', 'Weapon and Armor Enchants', 'Enchanters apply enchants directly or onto a scribe''s Armor or Weapon Vellum to make a tradeable scroll; ring enchants are for the enchanter only. Popular Wrath weapon enchants are Berserking and Mongoose for melee, Black Magic for casters and Accuracy for hit. Death knights use Runeforging instead, like Rune of the Fallen Crusader or Razorice, at a runeforge in Ebon Hold.', 'enchant,enchants,weapon enchant,mongoose,black magic,enchant scroll,vellum,runeforge,runeforging,fallen crusader,razorice,crusader enchant', 'items,enchants,enchanting,improvement', 'pve', 'Weapon: Berserking for most melee, Black Magic for casters, Mongoose for agility classes, Massacre on two-handers, Blade Ward or Blood Draining for tanks. Chest takes Powerful Stats. Cloak takes Major Agility for physical damage, Greater Speed for casters, and Mighty Armor for tanks. Leatherworkers'' Icescale Leg Armor and tailors'' Sapphire or Brilliant Spellthread are the leg enchants to get.', 'what enchants should i use|best weapon enchant|what is berserking|what is mongoose|what is black magic enchant|best enchant for casters|best chest enchant|best cloak enchant|best leg enchant|what enchant for tanks|how do death knights enchant weapons|what is runeforging|what is razorice|what is fallen crusader|where is the runeforge|how do i get an enchant scroll|can i enchant someone''s gear|what is massacre enchant|ench for my two hander|how do i get icescale leg armor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_gems', 'Socketed Gems', 'Sockets are red, yellow, blue or meta. Red gems carry strength, agility, attack power or spell power; yellow carry crit, haste or hit; blue carry stamina, spirit or mana regen; orange, purple and green count as both colors. Matching every socket turns on the item''s socket bonus, and a meta gem works only if you meet its color requirement.', 'gems,gem,sockets,socket,gemming,meta gem,socket bonus,cardinal ruby,kings amber,majestic zircon,red gem,yellow gem,blue gem,prismatic', 'items,gems,jewelcrafting,optimization', '', '', 'what do the gem colors mean|what gems should i use|what gems for my dps|what is a socket bonus|do i need to match socket colors|what is a meta gem|why is my meta gem not working|what is an orange gem|what do red gems do|what do yellow gems do|what do blue gems do|which gem gives hit|what is a purple gem|what is a green gem|how do i get a meta gem to activate|best gems for tanks|should i match sockets');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_consumables', 'Consumable Items', 'You can have one battle elixir and one guardian elixir active, or a flask, which counts as both and lasts an hour through death. Only one potion can be drunk per fight, such as a Runic Healing or Runic Mana Potion at 80, and a Well Fed food buff stacks with all of it.', 'consumables,consumable,potion,potions,pots,elixir,elixirs,flask,flasks,food buff,well fed,runic healing potion,runic mana potion', 'items,consumables,buffs,performance', 'pve', 'Raid with a flask rather than two elixirs: it lasts through death and costs less. Use Endless Rage, Frost Wyrm, Stoneblood or Pure Mojo depending on role. Fish Feast covers food for the whole raid. Drink a damage potion just before the pull and another during the fight, since the potion cooldown waits until combat ends.', 'what is a flask|what is the difference between flasks and elixirs|how long does a flask last|does a flask last through death|what is battle elixir|what is a guardian elixir|can i use two potions in a fight|how many potions can i drink in combat|what is well fed|which flask should i use|do i need flasks for raids|do flasks stack with food|what is a runic healing potion|should i use a flask or elixirs|what potion do i use at 80|what consumables do i need');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_trade_goods', 'Trade Goods and Materials', 'Trade goods are crafting materials: cloth drops from humanoids (Frostweave in Northrend), leather comes from skinning beasts (Borean Leather), ore from mining (Cobalt, Saronite, Titanium) and herbs from herbalism. Eternals and Frozen Orbs go into high-end crafts. Gatherers make steady gold selling them on the auction house.', 'trade goods,materials,mats,crafting materials,frostweave,frostweave cloth,borean leather,eternals,eternal,frozen orb,make gold', 'items,materials,trading,economy', '', '', 'what are trade goods|what is frostweave|where do i get cloth|where does leather come from|what are eternals|what is a frozen orb|what are crafting materials|what do i do with mats|what sells on the ah mats|where do i farm cloth|how do i get ore and herbs to sell|can i sell gathered mats on the ah|what are eternals used for|where do i get saronite|what are cobalt and saronite|what is frostweave cloth used for');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_keys', 'Dungeon and Raid Keys', 'Northrend heroic dungeons need no key, only the level cap. Older keys in use include the Crescent Key from Dire Maul, which opens its locked doors, and the Shadowforge Key for the Shadowforge City gate in Blackrock Depths; rogues can pick many of these locks instead.', 'key,keys,attunement,attuned,crescent key,shadowforge key,heroic key,dungeon key', 'items,keys,access,attunement', '', '', 'what key do i need for dire maul|what is the crescent key|what is the shadowforge key|do heroics need a key|do i need a key for northrend heroics|how do i open the brd gate|how do i get into shadowforge city|can rogues pick the lock instead of a key|how do i open locked doors in dm|what keys are still used|are there attunement keys for heroics|where do i get the dm key|what do i need to enter a heroic|how do i get into dire maul');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_containers', 'Special Containers', 'Locked boxes such as the Froststeel Lockbox drop from Northrend monsters and open with a rogue''s Pick Lock or a blacksmith''s skeleton key (the Titanium Skeleton Key is the highest). Rogues also pickpocket junkboxes from humanoids.', 'lockbox,lockboxes,locked box,junkbox,pick lock,lockpicking,skeleton key,titanium skeleton key,froststeel lockbox', 'items,containers,loot,collection', '', '', 'how do i open a lockbox|what is a froststeel lockbox|how do i open locked boxes|what is a skeleton key|what is the titanium skeleton key|can blacksmiths open lockboxes|what is a junkbox|how do rogues get junkboxes|how do i pick a lock|what is pick lock|i have a locked chest how do i open it|who can open my lockbox|where do lockboxes drop|what do i do with a lockbox|how do i pickpocket boxes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_tabards', 'Guild and Faction Tabards', 'Tabards are cosmetic chest-overs. A guild designs its tabard at a guild tabard vendor, and members wear it to show the emblem. Faction tabards are sold by quartermasters; in Northrend the Argent Crusade, Kirin Tor, Knights of the Ebon Blade and Wyrmrest Accord tabards also send dungeon reputation to their faction at level 80.', 'tabard,tabards,guild tabard,faction tabard', 'items,cosmetic,guild,faction', '', '', 'what is a tabard|how do i get a guild tabard|where do i buy a guild tabard|how do i make a guild tabard|what does the argent crusade tabard do|what is the kirin tor tabard|what tabard gives rep in dungeons|what is the ebon blade tabard|what is the wyrmrest accord tabard|do tabards give stats|how do i wear a tabard|where do i get a faction tabard|is a tabard cosmetic|which tabards give reputation|how do i show my guild emblem');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_quest_rewards', 'Quest Reward Items', 'Many quests let you choose one reward from a list; pick the piece for your armor type and spec, since the rest only sells to a vendor. Famous quest rewards include Quel''Serrar from a Dire Maul chain and, in Wrath, Quel''Delar, a level-80 sword chain started by the Battered Hilt that drops in the Frozen Halls dungeons.', 'quest reward,quest rewards,quel delar,queldelar,battered hilt,quel serrar,quelserrar', 'items,quests,lore,story', '', '', 'which quest reward should i pick|how do i pick a quest reward|what quest reward is best|what do i choose from quest rewards|can i take more than one quest reward|what is quel''delar|how do i get quel''delar|what is the battered hilt|how do i get quel''serrar|where do i start the quel''delar quest|what is the sword from frozen halls|what is quel''serrar|should i pick the vendor item|whats the best reward for my spec|which quest item for my class');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_cosmetic', 'Cosmetic Items', 'There is no wardrobe or appearance-change system yet -- an item''s look is simply whatever is equipped, so cosmetic collecting mostly means non-combat companion pets, which follow a player around and do nothing else. Pets are earned from vendors, quest rewards, holiday events, and rare drops, and many players collect them purely for their own sake. Some weapon enchants add a visual glow or proc animation as a side effect of their stat bonus, which is the closest thing to a customizable weapon appearance available this expansion. Holiday events also hand out costume items, like Hallow''s End''s wand that temporarily transforms the user into a ghost, ninja, pirate, skeleton, or leper gnome.', 'cosmetic,companion pet,companion pets,vanity pet,vanity pets,minipet,minipets,costume,transmog,transmogrification,appearance', 'items,cosmetic,appearance,collection', '', '', 'is there transmog|can i change my gear look|is there a wardrobe|how do i change my armor appearance|is there transmogrification|how do i collect pets|how do i get companion pets|what are vanity pets|what do non combat pets do|how do i get a costume|what is the hallow''s end wand|how do i turn into a ghost|where do i get cute pets|is there a way to change how my weapon looks|which enchants glow|how do i get a pet that follows me|cosmetic items wotlk');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_relics', 'Relics and Artifacts', 'Paladins, druids, shamans and death knights carry a relic in the ranged slot instead of a ranged weapon: librams for paladins, idols for druids, totems for shamans and sigils for death knights. Each boosts specific class spells, so the right one depends on spec.', 'relic,relics,libram,librams,idol,idols,sigil,sigils,totem relic', 'items,relics,class,bonuses', '', '', 'what is a relic|what is a libram|what is an idol|what is a totem|what is a sigil|why cant i equip a gun as a paladin|what goes in the ranged slot for a pally|what is the ranged slot for druids|what ranged slot item for dk|what ranged slot for shamans|which libram should i use|which idol for feral|which sigil for my dk|which totem should i use|what do relics do|do i need a relic');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_vault_of_archavon_loot', 'Vault of Archavon Loot', 'Archavon the Stone Watcher drops two items on 10-player or four on 25-player, picked from Wrath tier 7 armor pieces and Gladiator PvP gear: item level 200 (Heroes'' and Hateful Gladiator''s) on 10 and 213 (Valorous and Deadly Gladiator''s) on 25. He also gives two Emblems of Triumph, and there is a 1 percent chance of the Reins of the Grand Black War Mammoth, an Alliance or Horde version.', 'archavon loot,archavon drops,voa loot,voa drops,grand black war mammoth,black war mammoth', 'items,raid,wintergrasp,loot', '', '', 'what does archavon drop|what loot does archavon give|what drops in vault of archavon|voa loot table|does archavon drop tier gear|how many items does archavon drop|does archavon drop emblems|how do i get the grand black war mammoth|what drops from archavon 25|what drops from archavon 10|is there a mount in the vault of archavon|does voa drop pvp gear|what item level is voa gear|does archavon drop a mount|how many emblems from archavon|what gear comes from voa');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_mithril_bar', 'Mithril Bars', 'No vendor sells Mithril Bars and no creature drops them: you smelt them from Mithril Ore, one ore per bar, at a forge with Smelt Mithril, which a mining trainer teaches at skill 175 for 50 silver. Mithril Deposits need 175 Mining and are common in the Hinterlands, Searing Gorge, Arathi Highlands, Desolace, Felwood, Alterac Mountains, Stranglethorn Vale, Tanaris and the Badlands. Otherwise buy bars at the auction house.', 'mithril,mithril bar,mithril bars,mithril ore,mithril deposit,smelt mithril', 'item,profession,mining', '', '', 'where do i get mithril bars|how do i make mithril bars|where to buy mithril bars|how to smelt mithril|where do i find mithril ore|what mining skill for mithril|where is mithril ore|who sells mithril bars|how many mithril ore per bar|what do i need to smelt mithril|where to farm mithril|how do i get mithril for blacksmithing|mithril bars for engineering|where can i find mithril deposits|should i buy mithril bars or smelt them|what level do i need to mine mithril');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_badge_of_justice', 'Badge of Justice', 'Badge of Justice is the Burning Crusade gear currency. It drops from Outland heroic dungeon bosses and from raid bosses from Karazhan to the Sunwell Plateau, and the heroic Wanted daily quests pay 2. It is spent in Shattrath City with G''eras, Anwehu and Ontuvo, and on the Isle of Quel''Danas with Kayri. Nothing in Northrend drops it: Emblems of Triumph and Frost took over there.', 'badge of justice,badges of justice,justice badge,justice badges', 'item,currency,outland', '', '', 'what is a badge of justice|where do i get badges of justice|where do i spend badges of justice|who sells badge gear|what are bc badges|do badges of justice still drop|how do i farm badges of justice|where is the badge vendor in shattrath|what gear can i buy with badges of justice|do badges drop in northrend|what replaced badges of justice|where do i get badges in outland|badge of justice vs emblems|which bosses drop badges of justice|where do i turn in badges of justice|is there a badge vendor on quel danas');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('item_travelers_tundra_mammoth', 'Traveler''s Tundra Mammoth', 'Reins of the Traveler''s Tundra Mammoth are sold by Mei Francis, the Exotic Mounts vendor in Dalaran, for 20,000 gold. It needs character level 40 and Journeyman riding (skill 150), and each faction has its own version, one for the Alliance races and one for the Horde races. It is a very fast ground mount that carries three riders and vendors.', 'travelers tundra mammoth,travelers mammoth,tundra mammoth,mammoth,mei francis,mammoth mount', 'item,mount,dalaran', '', '', 'where do i buy the traveler''s mammoth|how much is the traveler''s tundra mammoth|where do i get the mammoth mount|who sells the mammoth|traveler''s mammoth price|what do i need for the traveler''s tundra mammoth|is the traveler''s mammoth alliance or horde|where is mei francis|how do i get a mammoth with vendors|what level for the traveler''s mammoth|can horde buy the traveler''s mammoth|where do i get a 3 person mount|how much gold for the mammoth|is there a mount that carries vendors|where do i buy a tundra mammoth|what riding skill for the mammoth');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_reputation', 'Reputation System', 'Reputation levels run Hated, Hostile, Unfriendly, Neutral, Friendly, Honored, Revered, Exalted. From Neutral it takes 3,000 points to Friendly, then 6,000 to Honored, 12,000 to Revered and 21,000 to Exalted, 42,000 in all. See your standings in the Reputation tab of the Character window (C). Quartermasters sell more as you climb; humans gain 10% extra, and this realm gives five times the normal reputation from every source.', 'reputation,rep,exalted,revered,standing,faction standing', 'mechanic,reputation,factions,progression', '', '', 'how does rep work|how do i get exalted|how much rep for exalted|what are the reputation levels|how much rep to revered|how much rep to honored|what is neutral to friendly|what is the rep order|how do i check my standing with a faction|why are quartermasters locked|how do i unlock the rep vendor|do humans get extra rep|how much rep to friendly|what is the human rep bonus|what comes after revered|how do i raise my reputation|what is hated and hostile|where do i see my reputation|how do i check my reputation|where is the reputation tab|what key opens reputation|how do i see my rep|how fast is rep gain here|is rep boosted on this realm|how much faster is reputation here|does this realm have boosted rep|rep is so slow is it boosted|how much rep per quest|rep grind how long|is rep 5x here|blizzlike rep rates|how much rep til exalted|exalted rep total|how many rep points for revered|rep vendor locked|do i need honored for the rep vendor|hows rep gain compared to retail|how mch rep to exalted|friendly to honored rep|why is rep so fast|human rep bonus');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_auction_house', 'Auction House', 'Every faction capital has an Auction House, such as Stormwind''s Trade District and Orgrimmar''s Valley of Strength, and so do Booty Bay, Gadgetzan and Everlook; Dalaran and Shattrath have none. On this realm every auction house is the same market, open to both factions, so it doesn''t matter which one you use. Auctions last 12, 24 or 48 hours, the deposit is lost if the item doesn''t sell, and the house keeps 15% of a sale.', 'auction house,ah,auction,auctions,auctioneer,buyout,neutral ah,selling on the ah', 'mechanic,economy,trading,market', 'gold', 'Post on 24 hours and undercut the lowest price by a copper, not by half; if the market is flooded, wait for it to clear instead of racing to the bottom. The house keeps 15% of every sale, so price that in, never list below what a vendor would pay, and park a bank alt next to the auctioneer to save the trip.', 'where is the ah|where do i find the auction house|how does the ah work|where is the auction house in sw|where is the ah in orgrimmar|is the ah neutral|can i buy from the other faction ah|can horde and alliance use the same ah|how long do auctions last|how much does the ah take|what is the ah cut|what is the auction deposit|do i lose my deposit|does dalaran have an ah|is there an ah in shattrath|how do i sell stuff on the ah|how do i price things on the ah|what duration should i post for|should i undercut on the ah|where is the ah in booty bay|ah cut|ah fee|ah tax|how much does ah take|ah deposit|how long can i list on ah|is ah shared|do horde and alliance share the ah|can i buy from horde on ah|where is ah|ah in dalaran|no ah in dalaran why|what happens if my auction doesnt sell|ah duration options|how do i use the ah');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_quests', 'Quest System', 'Quest givers show a yellow ! when they have a quest and a yellow ? when you can turn one in. A quest''s level shows as a color: grey is too low to give much experience, green is easy, yellow is your level, orange is hard and red is well above you. The log holds 25 quests, and most can be shared with your party.', 'quest,quests,quest giver,quest log,turn in,exclamation mark,exclamation point,question mark,quest marker,yellow exclamation,grey exclamation', 'mechanic,progression,story,objectives', '', '', 'how do quests work|what does the yellow question mark mean|what does the yellow exclamation mean|what do the quest colors mean|what is an orange quest|what is a red quest|what is a grey quest|how many quests can i hold|how many quests can i have in my log|how do i share a quest|can i share quests with my party|my quest log is full|what does a green quest mean|what is a yellow quest|why is the quest not giving xp|what does the ? mean on an npc|how many quests can i carry');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_talents', 'Talent System', 'Characters get one talent point per level from level 10, 71 by level 80, spent across their class''s three trees. A class trainer resets talents for gold: 1 gold the first time, rising with each respec to a 50 gold cap and dropping back over time. Dual specialization at 40 lets you keep two builds.', 'talents,talent,talent points,talent tree,talent build,respec,reset talents', 'mechanic,character,specialization,progression', '', '', 'how do talents work|how many talent points do i get|how many talent points at 80|when do i get talents|how do i respec|how much does a respec cost|where do i reset my talents|who resets talents|how do i reset my talents|respec cost|how many points in the talent trees|how do i spend talent points|what level do talents start|how many talent trees are there|what is the cap on respec cost|does respec price go up|how many talents at 70');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_glyphs', 'Glyph System', 'Each character has three major and three minor glyph slots: one of each opens at level 15, another major at 30 and 80, and another minor at 50 and 70. Glyphs are made by scribes with Inscription and sold on the auction house, and putting a new glyph in a slot destroys the old one.', 'glyph,glyphs,major glyph,minor glyph,glyph slot,glyph slots', 'mechanic,customization,spells,inscription', '', '', 'how do glyphs work|how many glyph slots do i have|how do i get glyphs|where do i buy glyphs|what are major and minor glyphs|when do i get glyph slots|what level do glyphs unlock|do glyphs get destroyed|how do i change a glyph|can i swap glyphs|what happens to my old glyph|how many major glyphs do i get|who makes glyphs|where do i get glyphs at lvl 15|how many minor glyphs can i have|do i lose a glyph when i replace it');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_achievements', 'Achievement System', 'Press Y to open achievements; they belong to each character and award points, and some give titles, pets or mounts. For example World Explorer gives the title the Explorer, and Higher Learning, reading the books hidden in Dalaran, gives the Kirin Tor Familiar pet. Feats of Strength give no points.', 'achievement,achievements,achievement points,cheevo,cheevos,feat of strength,achievement title,world explorer,higher learning', 'mechanic,goals,rewards,progression', '', '', 'how do achievements work|what key opens achievements|how do i open the achievement window|how do i see my achievements|what are achievement points|do achievements give titles|do achievements carry over to alts|are achievements account wide|what is the explorer title|how do i get the explorer title|what is higher learning|how do i get the kirin tor familiar|what are feats of strength|which achievements give pets|what achievement gives a title|how do i get a title|where do i see my achievement points');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_pvp', 'Player vs Player Combat', 'Players fight each other in battlegrounds, arenas, Wintergrasp and the open world. Killing enemy players who give honor and winning objectives earns Honor points, spent with PvP vendors on gear. On a PvP realm contested zones flag you automatically; on a PvE realm you flag yourself with /pvp.', 'pvp,player vs player,honorable kill,hk,pvp combat', 'mechanic,combat,pvp,battlegrounds', '', '', 'how does pvp work|how do i get honor|how do i flag for pvp|how do i turn on pvp|what does /pvp do|how do i get pvp gear|where do i spend honor|how do i get off pvp|how do i turn pvp off|am i pvp flagged|why am i flagged|can i get ganked here|is this a pvp realm|what are the pvp options|where can i pvp|what do pvp vendors sell|how do i flag myself for pvp on a pve realm');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_mounts', 'Mount System', 'Riding is trained in steps: Apprentice (60% ground mounts) at level 20 for 4 gold, Journeyman (100% epic ground) at 40 for 50 gold, Expert (flying) at 60 for 250 gold, Artisan (epic flying) at 70 for 5,000 gold, and Cold Weather Flying, needed to fly in Northrend, at 77 for 1,000 gold. Mounts are bought separately from mount vendors.', 'mount,mounts,riding,riding skill,riding trainer,apprentice riding,journeyman riding,expert riding,artisan riding,epic mount,flying,flying mount,learn to fly', 'mechanic,travel,collection,mounts', 'general', 'Buy Expert riding at 60 and go to Outland, where you can fly; Artisan is worth buying once you have the gold. Cold Weather Flying at 77 makes Northrend much faster, and a level 80 can buy a Tome of Cold Weather Flight to let an alt fly from 68. Save gold for each riding skill before spending it on gear you will replace.', 'how do i get a mount|when do i get a mount|what level do mounts start|how much does riding cost|how much is epic flying|how much is artisan riding|how do i learn to ride|how do i learn to fly|where do i learn flying|what is the riding skill|when can i get a flying mount|how much is expert riding|when do i get an epic mount|how do i get my first mount|how much gold for riding at 20|how much gold for 60 mount|how much is journeyman riding|can i fly in northrend|what is the gold cost for riding skills|how fast is a ground mount');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_pets', 'Pet System', 'Hunters learn Tame Beast and Feed Pet at level 10 and keep beasts as permanent combat pets; Beast Mastery hunters can also tame exotic beasts. Feed Pet takes a food the beast eats, such as meat, fish or bread, and keeps it happy, and an unhappy pet deals less damage. Warlocks summon demons, Death Knights raise a ghoul and frost mages get a Water Elemental. Non-combat companion pets are purely cosmetic followers. Stable masters hold the beasts a hunter isn''t using.', 'pet,pets,hunter pet,tame,tame beast,feed pet,pet food,pet happiness,demon pet,warlock pet', 'mechanic,companions,pets,collection', '', '', 'how do i tame a pet|how do i feed my pet|how do i get a hunter pet|when do hunters get pets|my pet is unhappy|what does an unhappy pet do|what food does my pet eat|how do i keep my pet happy|what is feed pet|what is tame beast|can i tame exotic pets|what is an exotic pet|where do i store extra pets|what is the stable master|how do warlocks get pets|do dks have pets|do mages get a pet|what are companion pets|how do i get a water elemental');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_guilds', 'Guild System', 'The Guild tab of the Social window (O) lists the members and who is online. A member whose rank allows it invites a player with /ginvite and their name, or the tab''s Add Member button; /gquit leaves. To found a guild, buy a charter for 10 silver from a Guild Master in a capital or Dalaran, get 3 other players from different accounts, either faction, to sign it, and turn it in at the same NPC. The leader sets ranks and bank rights. Guilds in Wrath have no levels or perks.', 'guild charter,create a guild,start a guild,guild ranks,guild leader,guild master,guild invite,guild permissions,make a guild,guild roster,guild members,ginvite,gquit', 'mechanic,social,guilds,community', '', '', 'how do i join a guild|how do i make a guild|how do i start a guild|how do i get a guild charter|where do i buy a guild charter|how do i invite someone to my guild|what is ginvite|how do i leave my guild|how do i see my guild roster|how do i see who is online in guild|how do i open the guild window|how do i check my guild members|what key opens the guild tab|how do i see guild members|how many signatures for a guild|how do guild ranks work|how do i give guild bank access|do guilds have levels|does wrath have guild perks|how do i set guild permissions|how much does a guild charter cost|how many signatures do i need for a guild|who can sign my guild charter|can the other faction sign my guild charter|where do i turn in a guild charter|can my alts sign my guild charter|how many people do i need to start a guild|can i join a guild of the other faction|how much does it cost to make a guild|where do i find a guild master npc|guild charter sigs|how many sigs for guild|charter sigs needed|charter signatures|how many sigs do i need|guild charter price|can horde sign my charter|can alts sign charter|how do i make a guild with sigs|need 3 signatures for charter|where to turn in charter|guild perks|do guilds level|guild invite command');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_death', 'Death and Your Corpse', 'When you die, release your spirit and you appear as a ghost at the nearest graveyard; run back to your corpse and resurrect there for free. The spirit healer at the graveyard revives you on the spot instead, but from level 11 that costs extra durability on your gear and gives resurrection sickness, weaker stats for up to ten minutes. Every death wears your gear, which a repair vendor fixes for gold.', 'corpse,graveyard,resurrection sickness,res sickness,rez sickness', 'mechanic,death,basics', '', '', 'how do i get my corpse back|where do i go when i die|i died now what|how do i res|how do i get my body|lost my corpse|where is my corpse|how do i release spirit|what is a spirit healer|is the spirit healer worth it|what is resurrection sickness|how do i get rid of res sickness|how do i run back to my body|what happens when i die|where do ghosts go|how do i resurrect|can i res for free');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_instances', 'Instance System', 'Dungeons are five-player and Wrath raids are 10 or 25. Heroic dungeon lockouts reset daily and raid lockouts weekly; a normal dungeon can be reset from your portrait menu, and on this realm you can enter at most ten instances per hour.', 'instance,instances,lockout,raid lockout,raid id,instance reset,reset instance,too many instances,saved to', 'mechanic,instances,group_content,difficulty', '', '', 'how do dungeons work|how many people in a dungeon|how many in a raid|how many people in a 25 man|when do heroic lockouts reset|when do raids reset|how do i reset an instance|how do i reset a dungeon|can i reset instances|what is the instance limit per hour|why cant i enter the instance|how many instances per hour|what is a lockout|what is a saved raid|what is the 5 instance limit|how often do heroics reset|how do i reset my dungeon|what is a 10 man|how long is the raid lockout|too many instances message what now|too many instances|instance limit|why cant i enter dungeons|ten instances an hour|instance cap per hour|dungeon reset|raid lockout reset|when does heroic reset|what is the hourly instance limit|saved to instance how do i reset|10 man or 25 man|when does my raid lockout end|cant zone in instance limit');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_world_events', 'World Events', 'Yearly holidays, all on the in-game calendar: Lunar Festival (Feb 1-14), Love is in the Air (Feb 10-23), Children''s Week (Apr 30-May 6), Midsummer Fire Festival (Jun 21-Jul 4), Brewfest (Sep 20-Oct 4), Hallow''s End (Oct 18-31), Pilgrim''s Bounty (Nov 21-27) and the Feast of Winter Veil (Dec 15-Jan 2).', 'world event,world events,holiday,holidays,seasonal event,calendar,event calendar', 'mechanic,events,world,seasonal', '', '', 'what events are there|when is brewfest|when is hallow''s end|when is winter veil|when is love is in the air|when is the lunar festival|when is midsummer|when is pilgrim''s bounty|when is children''s week|what holidays are in the game|when is the next holiday|what event is on right now|is there an event going on|when is halloween in wow|when is christmas in wow|when does feast of winter veil start|what is the in game calendar|when is thanksgiving in wow|list of world events');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_profession_specializations', 'Profession Specializations', 'Several crafts have a specialization with its own recipes: Blacksmithing has Armorsmith and Weaponsmith (then Axe, Mace or Sword), Leatherworking has Dragonscale, Elemental and Tribal, Tailoring has Mooncloth, Shadoweave and Spellfire, Engineering has Goblin and Gnomish, and Alchemy has Elixir, Potion and Transmutation Master.', 'profession specialization,armorsmith,weaponsmith,goblin engineering,gnomish engineering,transmute master,elixir master,potion master,mooncloth,shadoweave,spellfire,dragonscale,tribal leatherworking,elemental leatherworking', 'mechanic,professions,specializations,crafting', '', '', 'what are profession specializations|what is armorsmith|what is weaponsmith|what specs can a blacksmith take|what are the lw specializations|what is dragonscale|what is elemental leatherworking|what is tribal leatherworking|what is mooncloth tailoring|what is shadoweave|what is spellfire|goblin or gnomish engineering|what is transmutation master|what are the alchemy specializations|what is elixir master|bs spec choices|which engineering spec is better|what is potion master|which weaponsmith spec do i pick|can tailors specialize');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_currency', 'Currency Systems', 'Besides gold, the currency tab tracks Honor and Arena Points for PvP gear, Emblems of Triumph and Frost for PvE gear, Stone Keeper''s Shards from Wintergrasp for its vendors and heirlooms, and Champion''s Seals from the Argent Tournament dailies. Honor caps at 75,000.', 'currency,currencies,badge,badges,stone keepers shard,stone keepers shards,champions seal,champions seals,arena points', 'mechanic,currency,gearing,progression', '', '', 'what currencies are there|what is honor for|what are arena points|what are emblems|what is emblem of frost|what are stone keeper''s shards|what are champion''s seals|what is the honor cap|how many honor can i hold|what is the max honor|what currency do i need for pve gear|what currency for pvp gear|where do i see my currency|how do i get champion''s seals|where do i get stone keeper''s shards|what do i spend wintergrasp shards on|which tokens buy gear');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_raid_item_level', 'Raid and Dungeon Gear Requirements', 'Trial of the Crusader asks only for level 80: no item level or gear score is enforced for it, nor for Icecrown Citadel, Ulduar or Naxxramas, and groups set their own bar. Heroic Trial of the Crusader needs the Call of the Crusade achievement for that raid size, and heroic Icecrown Citadel needs The Frozen Throne. Heroic Northrend five-mans need an average item level of 180, or 200 for Forge of Souls, Pit of Saron and Trial of the Champion and 219 for Halls of Reflection.', 'ilvl,gearscore,gear score,heroic requirements,call of the crusade', 'mechanic,raid,gear', '', '', 'what ilvl do i need for toc|gear score for trial of the crusader|what item level for toc 10|what gearscore for icc|is there a gear requirement for toc|what do i need to enter toc heroic|how do i unlock heroic toc|what ilvl for heroic dungeons|item level needed for heroics|min gearscore for ulduar|what gear do i need for icc|what ilvl for halls of reflection|do i need gear for naxx|how do i unlock heroic icc|what is the item level requirement for forge of souls|what ilvl for pit of saron heroic|how much gear for trial of the crusader');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_xp_to_level', 'Experience Needed to Level', 'Going from level 1 to 80 takes 24,067,200 experience in all: 3,379,400 to reach 60, 4,722,000 more to reach 70, and 15,965,800 more from 70 to 80. One level costs 400 at level 1, 290,000 at 60, 717,000 at 69, 1,523,800 at 70 and 1,670,800 at 79. Kills, quests and discovering new areas give XP; gathering herbs, ore or skins does not. This realm pays triple XP for kills and quests and quadruple for exploring and Dungeon Finder quests.', 'xp to level,xp per level,gathering xp,xp for gathering,xp to 80', 'mechanic,leveling,xp', '', '', 'how much xp to reach 80|how much xp do i need to hit 80|how much xp is level 80|how much xp from 70 to 80|how much xp per level|how much exp for level 60|how many xp to level 70|do you get xp for gathering|does mining give xp|does herbalism give xp|do i get xp from herbs|do gathering professions give experience|can i level by mining|how much xp does it take to get to 80|total xp to max level|how much exp from 1 to 80|do you get xp for skinning|how much xp for the next level|is xp boosted here|is it 3x xp|xp rates|how much xp for lvl 80|exp rates on this server|is leveling faster than retail|blizzlike xp|how much xp does exploring give|do i get xp for exploring|how much xp per level at 70|xp from lfd quests|leveling is so fast whats the xp rate|xp to 60|how much xp for 70|how long to get to 80 xp wise');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_chat_commands', 'Whispers and Chat Commands', 'To whisper someone, type /w, /whisper or /tell, then their name and your message, like /w Name hello; /r answers the last person who whispered you. The other channels are /s say, /y yell, /p party, /g guild and /raid for raid chat. The target has to be online, and on this realm Horde and Alliance can whisper, say and yell to each other.', 'whisper,whispers,whispering,private message,chat command,slash command', 'mechanic,social,chat', '', '', 'how do i whisper|what is the whisper command|how do i send a private message|how do i reply to a whisper|what does /r do|what is /w|how do i tell someone something privately|how do i talk in party chat|what is the command for guild chat|how do i yell|how do i talk in raid chat|can i whisper the other faction|can horde whisper alliance|what are the chat commands|how do i message a player|how do i say something to nearby players|what is the slash command for party chat');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_chat_channels', 'Chat Channels', 'Chat channels are numbered: General is local to your zone, LocalDefense is the zone''s defense channel, and Trade, for buying and selling, only exists in cities. You join them automatically as you travel; type /1, /2 and so on to speak in one (General is usually /1), or /join and a channel''s name to get back into one you left. Horde and Alliance share the same channels on this realm. The LookingForGroup channel only opens while you are queued in the LFG tool.', 'chat channel,chat channels,general chat,trade chat,trade channel,local defense,localdefense', 'mechanic,social,chat,channels', '', '', 'how do i talk in general chat|how do i join the trade channel|how do i use trade chat|where is trade chat|why cant i see trade chat|why is there no trade channel outside cities|what is localdefense|what is the local defense channel|how do i speak in channel 1|what is /1|how do i rejoin a chat channel|how do i join a channel|what chat channels are there|do horde and alliance share general chat|can the other faction see my general chat|how do i type in trade|what is the general channel');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_trading', 'Trading Between Players', 'To trade, stand within about 11 yards of the other player, right-click them and choose Trade. Each side adds up to six items and some gold, plus a seventh slot whose item isn''t handed over, and both must accept to finish. Most soulbound items can''t be traded, and Horde and Alliance can''t trade with each other.', 'trade window,trade request,trade items,trade a player,trading with', 'mechanic,social,trading', '', '', 'how do i trade an item to another player|how do i give someone an item|how do i give gold to a player|how do i open a trade window|how far can i be to trade|why wont the trade window open|how many items can i trade at once|what is the last slot in the trade window|how do i trade gold|what is the seventh trade slot|how do i hand someone my gold|how do i do a trade|how do i start a trade|how many slots in a trade|do both players have to accept a trade');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_party_raid', 'Parties and Raid Groups', 'Invite a player with /invite and their name, or right-click them and choose Invite; only the leader or a raid assistant can invite. A party holds 5 players, and the leader can convert it to a raid once it has two members, all level 10 or higher; a raid group holds up to 40. Logging out normally takes you out of a party, though not a raid or a Dungeon Finder group.', 'party invite,group invite,invite to party,convert to raid,raid group,party leader', 'mechanic,social,groups', '', '', 'how do i invite a player to group|what is /invite|how do i make a party|how do i form a group with someone|how do i convert my party to a raid|how do i turn a party into a raid|how many people can be in a party|how many players in a raid group|why cant i convert to a raid|can anyone invite to the party|why did i get kicked from my party when i logged out|why am i not in my group anymore|what level do you need for a raid group|how do i start a raid|can an assistant invite people|do i stay in my party when i log off|how many can i invite to a party');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_loot_methods', 'Group Loot Methods', 'A new party uses Group Loot: items at or above the loot threshold, green by default, are rolled for, and lower ones aren''t. The party leader can change it from their own portrait''s right-click menu: Master Looter lets one chosen player hand out every threshold item, Need Before Greed is a roll, Round Robin takes turns on corpses, and Free For All lets anyone grab anything. Dungeon Finder groups always use Need Before Greed, and their leader can''t change it.', 'loot method,loot threshold,group loot,master loot,master looter,round robin,ffa loot,need before greed', 'mechanic,loot,groups', '', '', 'how do i set loot to master looter|how do i change the loot method|how do i change loot rules|what is master looter|what is group loot|what is need before greed|what is round robin loot|what is free for all loot|how do i change the loot threshold|what is the loot threshold|who decides loot in a group|how does loot work in a party|what loot method does the dungeon finder use|why cant i change loot in lfd|how do i become master looter|how do i set party loot|what is the default loot setting|who can change the loot method|what does ffa loot mean');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_loot_rolls', 'Need, Greed and Disenchant Rolls', 'When a loot roll pops up, each player picks Need, Greed, Disenchant or Pass within 60 seconds, and the server rolls a random 1 to 100 for everyone who chose. Any Need beats every Greed, so Need is for gear you will actually use; Disenchant shows only when someone in the group has Enchanting skill high enough for the item, and it ranks with Greed. In Dungeon Finder groups you can only Need gear your class can use. /roll gives a random 1 to 100 on its own.', 'greed,greeding,need or greed', 'mechanic,loot,groups,rolls', '', '', 'what does need mean in loot rolls|when should i roll need|when should i roll greed|what is greed|what does disenchant mean in a roll|why is there no disenchant option|what happens if i pass on loot|what is the difference between need and greed|does need beat greed|how long do i have to roll|how do loot rolls work|how do rolls work|what is /roll|how do i roll a random number|can i roll need on gear i cant use|why cant i click need|who wins a loot roll|how do i roll on loot|what do i pick for loot i dont need');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_item_binding', 'Bind on Pickup and Bind on Equip', 'Bind on Pickup (BoP) items become soulbound the moment you loot or receive them, and can''t be traded, mailed or auctioned, only sold to a vendor. Bind on Equip (BoE) items stay tradable until you equip them, and Bind on Use items bind when used. Bind to Account (BoA) items, mostly heirlooms, can be mailed between your own characters but never traded to anyone else. Here, soulbound gear that dropped for a group can still be traded to players who could have looted it, for 2 hours of played time.', 'bind on pickup,bind on equip,bind on use,bind to account,bound to account,account bound,soulbound,bop,boe,boa', 'mechanic,items,binding', '', '', 'what does bop mean|what does boe mean|what does boa mean|what is bind on pickup|what is bind on equip|what is bind on use|what is bind to account|what does soulbound mean|can i trade a soulbound item|can i trade bop items in a group|how long can i trade a boss drop to someone|can i sell bop gear on the ah|can i mail a bop item|can i mail heirlooms to other players|what happens when i equip a boe|why cant i trade this item|how do i trade a drop to someone who needs it|can a boe be sold on the ah');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_mail', 'Mail, Gold and COD', 'At a mailbox, the Send Mail tab takes a recipient, a message, up to 12 attached items and either gold or a cash-on-delivery price, not both. Postage is 30 copper per attached item, or 30 copper for text alone. A COD recipient must pay the price to take the items, and it comes back to you by mail. Items sent to a character on another account arrive after 5 minutes; gold, text and mail between your own characters are instant. Mail lasts 30 days, COD mail 3, and soulbound items can''t be sent.', 'mailbox,mailboxes,send mail,mail attachments,cod,cash on delivery,return to sender,postage', 'mechanic,social,mail,economy', '', '', 'how do i send mail|how do i send gold to someone|how do i send an item to a player|how do i mail gold|what is cod|what does cod mean in mail|how do i send a cod|how much does mail cost|how much is postage|how many items can i attach to mail|how long until mail expires|why hasnt my mail arrived|how long does it take for mail to arrive|can i mail soulbound items|why is my mail delayed|can i send gold and a cod together|how do i mail someone who is offline|how long for mail to arrive|mail delay|why is my mail taking so long|mail takes 5 minutes why|is mail instant|how much is mail postage|cod mail|can i mail gold to my alt|mail to my alt is instant right|mail got delayed|can i send bop items in mail|how many items per mail|mail expiry|my mail didnt arrive yet');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_cross_faction', 'Cross-Faction Play', 'On this realm Horde and Alliance can whisper, say and yell to each other, share chat channels, party and raid together, queue for dungeons together, join and sign for the same guild, and use one auction house. They cannot trade with each other, and mail only crosses factions between your own characters on one account.', 'cross faction,crossfaction,other faction,opposite faction,enemy faction', 'mechanic,social,factions', '', '', 'can i group with the other faction|can horde and alliance party together|can i trade with horde|can i trade with the other faction|can i mail the other faction|can i mail my alt on the other faction|can i invite horde to my guild|can alliance and horde be in the same guild|can i talk to the other faction|can horde and alliance chat|can i do dungeons with the other faction|can i raid with the other faction|is this a cross faction realm|what can horde and alliance do together here|why cant i trade with an alliance player|can i send gold to the other faction|can horde and alliance talk here|can i whisper horde|can alliance trade with horde|cross faction trade|can i trade with other faction|cant trade with horde why|can i group with horde|do cross faction dungeons work|can horde join my guild|cross faction mail|can i mail horde|cross faction here|is this server cross faction|can i queue lfd with horde|can i say hi to the other faction');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_durability', 'Durability and Repairs', 'Armor and weapons have durability that wears as you fight. On this realm dying costs every equipped item 5% of its durability, even when another player kills you, and a spirit healer resurrection takes another 25% from everything you carry. An item at zero is broken and its stats stop working until it is repaired at a repair vendor, which costs twice the usual rate here.', 'durability,broken gear,broken item,repair bill,repair cost,gear wear', 'mechanic,durability,repair,death', '', '', 'what is durability|how much durability do i lose when i die|what happens when my gear breaks|what does broken gear do|why are my stats lower|why did my gear turn red|how much does repair cost|why is repair so expensive|does dying break my gear|does pvp death cost durability|how much durability does the spirit healer cost|can i fight with broken gear|what happens at zero durability|how do i fix broken gear|how fast does gear wear out|do i lose durability when i get killed by a player|do i lose durability when i die|how do i repair my gear|why is my gear broken|how much dura per death|dura loss on death|why is repair so pricey|is repair cost doubled|how much does dying cost me|is repair 2x here|do i lose dura from pvp|what is dura|my gear is red now what|gear broke what do i do|spirit healer dura penalty|why is my armor red|is durability loss higher than retail|repair costs too high');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_combat_state', 'Leaving Combat', 'You stay in combat until no enemy is still fighting you: kill them, or get far enough away that they give up and reset. After a fight with another player, combat drops 5 seconds after the last hostile action. A rogue''s Vanish and a hunter''s Feign Death can drop you out of combat early, and you can''t mount or stealth until you are out of it.', 'leave combat,out of combat,drop combat,stuck in combat,exit combat,end combat,combat timer', 'mechanic,combat,basics', '', '', 'how do i leave combat|how long does combat last|why cant i mount im in combat|why am i still in combat|how do i drop combat|how do i stop being in combat|how long until i leave combat|can i drop combat with vanish|how do i get out of combat fast|does feign death drop combat|why cant i stealth in combat|how long is the pvp combat timer|stuck in combat what do i do|how do i reset combat|how do i end combat');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_orgrimmar_stormwind_travel', 'Orgrimmar to Stormwind', 'Orgrimmar and Stormwind are rival capitals, so no boat, zeppelin or portal joins them. Horde take the zeppelin from Orgrimmar to Grom''gol in Stranglethorn Vale, then ride north through Duskwood and Elwynn Forest to Stormwind. Alliance fly from Stormwind to Booty Bay, sail the neutral boat to Ratchet in the Barrens, then ride across the Barrens to Orgrimmar. Horde can also fly from Orgrimmar to Ratchet and sail to Booty Bay.', 'orgrimmar to stormwind,stormwind to orgrimmar,between orgrimmar and stormwind', 'mechanic,travel,horde,alliance', '', '', 'how do i get from orgrimmar to stormwind|how do i get from stormwind to orgrimmar|how do i get to orgrimmar from stormwind|how to get to sw from og|how to get from sw to og|how do i get from org to sw|is there a zeppelin from orgrimmar to stormwind|is there a boat from stormwind to orgrimmar|is there a portal from orgrimmar to stormwind|can horde get to stormwind|can alliance get to orgrimmar|what is the fastest way from orgrimmar to stormwind|route from stormwind to orgrimmar|how do i travel between orgrimmar and stormwind|how do i get to stormwind as horde|how do i get to orgrimmar as alliance|how do i cross from orgrimmar to stormwind');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_death_gate', 'Death Gate', 'Death Gate is the death knight spell that returns you to Acherus: The Ebon Hold. It is taught by the level 55 quest The Light of Dawn, near the end of the starting chain, and it has a one-minute cooldown. In Acherus a portal on the platform southeast of Highlord Mograine leads to Stormwind or Orgrimmar for the quests Where Kings Walk (Alliance) and Warchief''s Blessing (Horde).', 'death gate,ebon hold,acherus,back to ebon hold,return to acherus', 'mechanic,death_knight,travel', '', '', 'how do death knights get back to ebon hold|how do i get back to ebon hold|how do i get back to acherus|what is death gate|where do i learn death gate|when do death knights get death gate|what level is death gate|how long is the death gate cooldown|how do dks go to ebon hold|dk death gate where|how do i leave ebon hold|how do i get from ebon hold to stormwind|how do i get from ebon hold to orgrimmar|where is the portal in ebon hold|i lost death gate how do i get it|how do i get to acherus as a dk|dk how to return to ebon hold|what quest gives death gate');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_dungeon_finder', 'Dungeon Finder', 'The Dungeon Finder (patch 3.3, December 2009), open from level 15, groups players on this realm for a chosen dungeon or a random one, through a queue where each player selects the Tank, Healer, and/or Damage role they''ll fill. Once a group forms, everyone is teleported directly to the dungeon entrance; this realm applies no Deserter debuff for leaving early. Queuing for a random Northrend heroic is the most common use: the first one completed each day awards 2 Emblems of Frost, and every additional one that day awards 2 Emblems of Triumph instead, making it the fastest way to gear up at level 80.', 'dungeon finder,lfd,rdf,random dungeon,random heroic,lfg tool,deserter,dungeon queue,daily random', 'mechanic,wotlk,dungeons,grouping', 'pve', 'Queue as tank or healer if you can, because those queues pop almost immediately. Do the first random heroic every day for the Frost and run the Icecrown five-mans for the best drops.', 'what is the dungeon finder|how do i use lfd|how do i queue for a dungeon|what is lfg tool|when does lfd unlock|what level can i use the dungeon finder|how do i queue as tank|how do i queue as healer|what is dungeon deserter|why am i deserter|what is a random heroic|how do i get emblems of frost daily|is the random heroic worth it|how fast is the tank queue|do dungeon finder groups cross realm|how do i get teleported to a dungeon|what role do i pick in lfd|how do i get into a dungeon fast|how do i do random dungeons|lfd|rdf|how do i use rdf|lfg queue|is there a deserter debuff|no deserter here right|lfd level req|what lvl for lfd|lfd cross realm|does rdf work here|random heroic reward|how many emblems from random heroic|lfd tank queue long|how do i queue for random dungeon|dungeon finder tips');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_heroic_emblems', 'Heroic Dungeons and Emblems', 'Emblems are the PvE gear currency. Heroic five-mans open at level 80 with no key, and the Dungeon Finder wants about 180 average item level. Emblems of Triumph drop from heroic Northrend dungeon bosses, Naxxramas, Ulduar, the Obsidian Sanctum, Vault of Archavon and Trial of the Crusader; Emblems of Frost from Icecrown Citadel, the Ruby Sanctum and Toravon. Heroism, Valor and Conquest no longer drop, but Usuri Brightcoin in Dalaran swaps an emblem for one of the kind below it. Dalaran quartermasters sell the gear.', 'heroic,heroics,heroic dungeon,heroic dungeons,emblem,emblems,emblem of triumph,emblem of frost,frost emblems,triumph emblems,emblem vendor', 'mechanic,wotlk,dungeons,currency,gearing', 'pve', 'At 80 do the daily random heroic for Emblems of Frost and spend Triumph on tier 9 and other item level 232 gear. Frost buys tier 10 at 60 for shoulders and gloves and 95 for head, chest and legs, plus item level 264 off-pieces. The weekly raid quest from Archmage Lan''dalock in Dalaran adds 5 more Frost, and the Icecrown five-mans drop the best heroic gear.', 'how do heroics work|what level do heroics unlock|do i need a key for heroics|how do i unlock heroic mode|how do i get emblems|what is emblem of triumph|how do i get emblems of frost|where do i spend emblems|what are emblems for|what emblems do heroics give|are emblems of heroism still dropped|do emblems of valor still drop|where do i buy emblem gear|who sells emblem gear|what is the best heroic to farm|how do i gear up at 80|how many emblems for t10|what is the weekly raid quest|how many frost emblems for a tier piece|what is the best emblem gear|can i convert frost emblems to triumph|who exchanges emblems|how do i turn emblems into triumph|where do emblems of triumph drop|which bosses drop emblem of frost|do naxx bosses drop emblems|how do i get emblems of heroism now|what is usuri brightcoin|how do i get emblems of valor|how do i get emblems of conquest|do icc bosses drop emblems of frost|do heroic bosses drop emblems of triumph');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_dual_spec', 'Dual Talent Specialization', 'Dual talent specialization (patch 3.1) lets a character save two separate talent builds -- each with its own glyphs and action bars -- and swap between them outside combat. It costs 1000 gold, requires level 40, and is bought once from your class trainer; after that, switching between the two saved specs is free and unlimited. Players commonly keep one PvE spec and one PvP spec, or a tank/healer spec alongside a damage spec, and swap depending on what the group needs.', 'dual specialization,dual talent specialization,dualspec,dual talent', 'mechanic,wotlk,talents,character', 'general', 'Buy dual specialization as soon as you can pay for it. Keep a damage spec for questing and a tank or healer spec for dungeons and faster queues, and give each spec its own glyphs and action bars.', 'how do i get dual spec|how much is dual spec|what level for dual spec|where do i learn dual spec|how do i get a second spec|how do i switch specs|what is dual talent specialization|do i need to pay to swap specs|can i have two talent builds|how do i have two specs|how much does dual spec cost|do glyphs carry over between specs|can i swap specs in combat|do both specs have their own glyphs|how do i get a pvp spec and a pve spec|can i be tank and dps|is dual spec worth buying|how do i change my spec');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_cold_weather_flying', 'Cold Weather Flying', 'Cold Weather Flying is the extra skill needed to use a flying mount in Northrend; Flying itself is learned at 60 with Expert riding, but Expert or Artisan alone isn''t enough there. It''s trained from a flying trainer in Dalaran or the Storm Peaks for 1,000 gold at level 77. A level 80 can buy the Tome of Cold Weather Flight for 1,000 gold and mail it to an alt, letting that alt fly in Northrend from 68.', 'cold weather flying,cwf,fly in northrend,flying in northrend,tome of cold weather flight', 'mechanic,wotlk,flying,mounts', 'general', 'Buy Cold Weather Flying at 77 even if you are short on gold: flying makes Northrend questing much faster. If you have a level 80 already, buy a Tome of Cold Weather Flight and mail it to your alt so they can fly from 68.', 'how do i fly in northrend|why cant i fly in northrend|what is cold weather flying|where do i learn cold weather flying|how much is cold weather flying|what level for cold weather flying|do i need cold weather flying|why cant i use my flying mount in northrend|where is the flying trainer in dalaran|what is the tome of cold weather flight|how do i fly my alt at 68|how do i get my alt flying early|can an alt fly in northrend at 68|is expert riding enough for northrend|what is cwf|how much gold for cwf|where do i get cwf|how do i get flying in wotlk');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_death_knight_runes', 'Death Knight Runes and Runic Power', 'Death Knights don''t use mana, rage or energy: they have six runes, two Blood, two Frost and two Unholy, plus a Runic Power bar. Spending a rune casts its ability and puts that rune on a short recharge, and spending runes builds the Runic Power that fuels abilities like Death Coil. As Wrath''s hero class, every Death Knight starts at level 55.', 'runes,rune,runic power,blood rune,frost rune,unholy rune,death rune,hero class,dk runes', 'mechanic,wotlk,class,death knight,resource', '', '', 'how do dk runes work|what are runes|what is runic power|how many runes does a dk have|what are the rune types|what is death coil|why dont dks use mana|what resource do death knights use|what do dks use instead of mana|how do i build runic power|how fast do runes recharge|what are blood frost and unholy runes|what level do dks start|what level does a death knight start at|how do i spend runes|how does a dk resource work|what is a rune cooldown');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mechanic_vehicle_combat', 'Vehicle Combat', 'Vehicles are a Wrath of the Lich King addition: mountable siege engines, cannons, and creatures that swap a player''s normal action bars for the vehicle''s own abilities for as long as they''re in the seat. They show up throughout the expansion -- Ulduar''s Flame Leviathan fight, the cannons defending Wintergrasp and Isle of Conquest, the siege engines and demolishers of Strand of the Ancients, and mine-cart or turret sections tucked into several dungeons. Leaving a vehicle returns a player to their normal spellbook immediately, and most vehicles can be destroyed out from under their rider by enemy fire.', 'vehicle,vehicles,vehicle combat,siege engine,demolisher', 'mechanic,wotlk,vehicles,pvp,raiding', '', '', 'how do vehicles work|how do i use a vehicle|what is a vehicle|how do i get out of a vehicle|why did my action bar change|what happens to my spells in a vehicle|how do i use the siege engines|how do i use a demolisher|how do i drive a siege engine|how do i use cannons in wintergrasp|what is the flame leviathan fight|how do i use a turret|how do i leave a vehicle|can vehicles be destroyed|where are vehicles used|how do i use a mine cart|how do i get a vehicle in sota|how do i use the catapult in isle of conquest');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_world_bosses', 'World Bosses', 'World bosses spawn in the open world and anyone can attack them: Doom Lord Kazzak roams Hellfire Peninsula, Doomwalker walks Shadowmoon Valley, and Azuregos, a blue dragon, guards Azshara. They need a raid-sized group and respawn on long timers.', 'world boss,world bosses,kazzak,doom lord kazzak,azuregos,doomwalker', 'npcs,bosses,world,loot', '', '', 'what are the world bosses|where is kazzak|where is doomwalker|where is azuregos|how do i kill doom lord kazzak|can i solo a world boss|world boss locations|where does kazzak spawn|how often do world bosses respawn|what is the blue dragon in azshara|how many people for kazzak|is there a world boss in shadowmoon valley|world bosses in outland|which bosses are in the open world');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_rare_elites', 'Rare Elite Creatures', 'Rare monsters show a silver dragon on their portrait and spawn rarely at fixed spots; elites have a gold dragon and need a group. Killing every Northrend rare earns the Frostbitten achievement, and the most hunted is the Time-Lost Proto-Drake in the Storm Peaks, which drops its own mount.', 'rare,rares,rare elite,rare spawn,elite,elites,silver dragon,frostbitten,time lost proto drake,tlpd', 'npcs,rare,elite,achievements', '', '', 'what is a rare spawn|what is a rare elite|what is the silver dragon on a mob portrait|gold dragon portrait what does it mean|where is the time lost proto drake|how do i get tlpd|what is the frostbitten achievement|where do rares spawn|how do i find rare mobs|how do i get the proto drake mount|is tlpd in the storm peaks|what is an elite mob|do i need a group for elites|rare mob hunting in northrend|how often do rares spawn');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_class_trainers', 'Class and Profession Trainers', 'Class trainers stand in the capitals and in each starting zone''s main town, and teach new spells and ranks for gold, with new ones every two levels. Profession trainers are in the capitals too, and the Grand Master ranks for Northrend (skill 350 to 450) are taught in Dalaran. Class trainers also reset talents and sell dual spec at 40.', 'trainer,trainers,class trainer,profession trainer,training,spell ranks,grand master trainer', 'npcs,training,progression,skills', '', '', 'where is my class trainer|where do i learn new spells|how do i train spells|where do i get new ranks|where is the grand master trainer|where do i learn 450 skill|where do i train northrend professions|how do i reset talents|where do i get dual spec|how much is dual spec|how do i unlearn talents|where do profession trainers hang out|at what level do i get new spells|can i train my class in dalaran|where do i get 350 to 450 skill');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_vendors', 'Special Vendors', 'Reputation quartermasters sell recipes, enchants and gear as your standing rises: the Kirin Tor''s is Archmage Alvareaux in Dalaran, the Sons of Hodir''s is Lillehoff at Dun Niffelem in the Storm Peaks, and the Wyrmrest Accord''s is Cielstrasza at Wyrmrest Temple in Dragonblight.', 'quartermaster,quartermasters,rep vendor,reputation vendor,faction vendor,special vendor,kirin tor quartermaster', 'npcs,vendors,items,reputation', '', '', 'where is the kirin tor quartermaster|who is the sons of hodir vendor|where is lillehoff|who sells wyrmrest accord stuff|where is cielstrasza|where is archmage alvareaux|where do i buy rep recipes|where do i spend my reputation|where is dun niffelem|where is wyrmrest temple|who is the rep vendor for sons of hodir|where do i buy rep gear|what is a quartermaster|where do i buy kirin tor enchants|where is the faction vendor in dalaran');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_flight_masters', 'Flight Masters', 'Speak to a flight master once to learn that flight path; after that you can fly between any paths you know for a fee that grows with distance. Alliance ride gryphons and hippogryphs, Horde ride wyverns, bats and dragonhawks, and Northrend''s flight masters serve both factions in places like Dalaran.', 'flight master,flight masters,flight path,flight paths,fp,gryphon,wyvern,taxi', 'npcs,travel,flight,exploration', '', '', 'how do flight paths work|how do i unlock a flight path|where do i get a flight path|what is a flight master|how much does flying cost|do i need to learn every fp|what do alliance fly on|what do horde fly on|are there flight masters in dalaran|can i fly between any two fps|gryphon or wyvern|how do i fly to another town|how do i get a taxi|why can''t i fly to this fp|how do i discover flight points');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_innkeepers', 'Innkeepers and Hearthstones', 'Speak to any innkeeper and make the inn your home to bind your Hearthstone there; the Hearthstone then brings you back to that inn on a 30-minute cooldown. Logging out in an inn or a capital builds rested experience, and innkeepers also sell food and drink.', 'innkeeper,inn,hearthstone,hearth,hs,set hearth,set my hearth,bind hearth', 'npcs,travel,rest,hearthstone', '', '', 'how do i set my hearth|how do i bind my hearthstone|how do i change my hearthstone location|what is the hearthstone cooldown|how long is the hs cooldown|how do i get rested xp|where do i go to log out for rested|what does an innkeeper do|how do i make this inn my home|where do i hearth to|hearth cd|does logging out in an inn give rested|can i buy food from innkeepers|how do i set hs in dalaran|my hearthstone takes me to the wrong place');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_banker', 'Bankers and Guild Banks', 'Bankers in every capital and in Dalaran hold your personal bank: 28 slots plus seven bag slots bought with gold. Each character has its own bank and bags, nothing is shared between characters, so items go to an alt by mail. A guild bank, opened at a guild vault, has up to six tabs of 98 slots, bought with gold, and the guild leader sets who can withdraw from each.', 'bank,banker,bank slots,bank bag,bank space,shared bank,guild bank,gbank,guild vault', 'npcs,storage,guild,inventory', '', '', 'where is the bank|how many bank slots do i have|how do i get more bank space|how much are bank bag slots|where is the guild bank|how many guild bank tabs|can my alts use my bank|how do i move items to my alt|is the bank shared between characters|how do i set guild bank permissions|how many slots in a gbank tab|is there a bank in dalaran|how do i get items to another character|how do i buy gbank tabs|who can withdraw from the guild vault');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_stable_masters', 'Stable Masters', 'Stable masters hold a hunter''s tamed beasts, letting one hunter keep several pets and swap between them. They do nothing for mounts, which live in the spellbook once learned. Stables are found in most towns and every capital. Swapping at a stable is how a hunter changes to a pet better suited to the fight ahead.', 'stable master,stable,stabled pet,swap pet,stable slot,stable slots', 'npcs,mounts,pets,storage', '', '', 'where is the stable master|how do i stable my pet|how do i swap pets|how many pet slots do hunters have|how do i get my old pet back|can i stable mounts|how do i change pets as a hunter|what does a stable master do|how many stable slots can i have|where do i keep multiple pets|hunter pet stable location|do mounts go in the stable|how do i store my pet|how do i switch hunter pets');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_lore_figures', 'Important Lore Figures', 'Wrath''s story centers on Arthas Menethil, the Lich King, waiting on the Frozen Throne atop Icecrown Citadel. Along the way players face Malygos, the blue Dragon Aspect, in the Eye of Eternity and the Old God Yogg-Saron beneath Ulduar. Tirion Fordring leads the Argent Crusade, and is found at the Argent Vanguard and Crusaders'' Pinnacle in Icecrown (in Eastern Plaguelands before that); Darion Mograine leads the Knights of the Ebon Blade.', 'lore,lich king lore,arthas,tirion fordring,darion mograine,malygos lore,yogg saron lore', 'npcs,lore,story,characters', '', '', 'who is the lich king|who is arthas|who is tirion fordring|who is darion mograine|who is malygos|who is yogg saron|what is the wotlk story|who is the main villain in wrath|where is the frozen throne|what is the argent crusade|what are the knights of the ebon blade|lich king lore|who leads the ebon blade|where is malygos|where do you fight yogg|where is tirion fordring|where is highlord tirion fordring|where is tirion in icecrown|where is tirion fordring in northrend|where is crusaders pinnacle|where did tirion fordring live before northrend');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_faction_leaders', 'Faction Leaders', 'Alliance leaders: King Varian Wrynn in Stormwind, King Magni Bronzebeard in Ironforge, High Tinker Mekkatorque for the gnomes, Tyrande Whisperwind in Darnassus and Prophet Velen in the Exodar. Horde leaders: Warchief Thrall in Orgrimmar, Cairne Bloodhoof in Thunder Bluff, Sylvanas Windrunner in the Undercity, Lor''themar Theron in Silvermoon and Vol''jin of the Darkspear trolls.', 'faction leader,faction leaders,who leads,who rules,mekkatorque,voljin,lorthemar,lor themar,cairne,varian', 'npcs,factions,leaders,politics', '', '', 'who is the horde leader|who leads the alliance|who is the warchief|who rules ironforge|who is the leader of the undercity|who is the leader of silvermoon|who is the leader of thunder bluff|who leads the darkspear trolls|who is the leader of darnassus|who is the leader of the exodar|who is the king of stormwind|who is mekkatorque|who is voljin|who is lor themar|who leads the gnomes|who is sylvanas');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_merchants', 'Specialized Merchants', 'General goods vendors sell food, drink and bags, and reagent vendors carry class reagents. Rogues buy poisons from poison vendors and hunters buy arrows and bullets from ammo vendors. Armorers and weaponsmiths repair your gear, and any vendor buys your loot.', 'reagent vendor,reagents,poison vendor,poisons,ammo,ammo vendor,arrows,bullets,repair,repairs,general goods', 'npcs,merchants,goods,supplies', '', '', 'where do i buy reagents|where do i buy poisons|where can i buy arrows|where do i buy bullets|where do i buy ammo|where do i repair my gear|who sells bags|who sells food and drink|where do i get reagents for my class|where do rogues buy poison|where do i sell my loot|who repairs armor|where is the general goods vendor|where do hunters buy ammo|where can i fix my gear');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_guards', 'City Guards and Sentries', 'Guards in capitals and towns attack enemy-faction players who are flagged and hostile creatures that wander in. Ask any guard for directions and it marks the nearest bank, inn, trainer, flight master or auction house on your minimap.', 'guard,guards,city guard,ask a guard,directions', 'npcs,guards,security,cities', '', '', 'what do guards do|how do i ask a guard for directions|how do i find the bank in a city|how do i find the nearest inn|how do i find the auction house|how do i find my trainer|guard marks nearest flight master|do guards attack enemy players|will guards protect me|where is the flight master in this city|i am lost in the city how do i find stuff|can guards show me the nearest bank|city guards help me find things|do guards kill flagged players');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_transport', 'Transportation NPCs', 'Boats and zeppelins are free. Alliance boats: Stormwind Harbor to Auberdine and to Valiance Keep (Northrend); Auberdine to Rut''theran Village and Azuremyst Isle; Menethil Harbor to Theramore and Valgarde (Northrend). Horde zeppelins: Orgrimmar to Undercity, Grom''gol, Thunder Bluff and Warsong Hold (Northrend); Undercity to Grom''gol and Vengeance Landing (Northrend). The neutral boat links Booty Bay and Ratchet. Shattrath has portals to your capitals.', 'boat,boats,zeppelin,zeppelins,zep,get to northrend,go to northrend,transport,transportation', 'npcs,transport,travel,convenience', '', '', 'how do i get to northrend|where is the boat to northrend|where is the zeppelin to northrend|how do i get to valiance keep|how do i get to howling fjord|how do i get to borean tundra|where is the boat to valgarde|where do horde zeps go to warsong hold|how do i get to vengeance landing|are boats free|how do i get from booty bay to ratchet|where are the portals in shattrath|how do i get to my capital from shattrath|how do i get to northrend as horde|how do i get to northrend as alliance|how do i get to menethil harbor|how do i get to darkshore|how do i get to azuremyst isle|where is the boat to theramore|how do i get to kalimdor from stormwind|where is the zeppelin to thunder bluff|how do i get from orgrimmar to thunder bluff|how do i get from undercity to orgrimmar|where do boats from stormwind go|what boats leave from menethil harbor|how do i get from auberdine to the exodar|which zeppelins leave from orgrimmar|do boats and zeppelins cost gold|how do i get from booty bay to ratchet by boat|how do i get from stranglethorn to the barrens|how do i get to grom''gol from orgrimmar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_old_gods', 'The Old Gods', 'Wrath has no single Old Gods questline: the Old Gods are ancient evil beings, and you meet them as raid bosses. Yogg-Saron waits at the bottom of Ulduar in The Storm Peaks, and the Val''anyr quest is finished by throwing its pieces into his maw. The other Old God in the game is C''Thun, in the Temple of Ahn''Qiraj in Silithus.', 'old gods,old god,yogg-saron lore,n''zoth,nzoth,y''shaarj,yshaarj', 'lore,npcs,story', '', '', 'who are the old gods|what are the old gods|is there an old gods questline|old gods quest line wotlk|which old gods are in wrath|where do i fight an old god|where is yogg saron|where is c''thun|is yogg saron an old god|is c''thun an old god|what is the old god in ulduar|what is the old god in ahn''qiraj|how do i find the old gods|do the old gods have a quest chain');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_riding_trainers', 'Riding Trainers', 'Riding is taught by racial trainers: Randal Hunter in Elwynn Forest for humans, Ultham Ironhorn in Dun Morogh for dwarves, Binjy Featherwhistle in Dun Morogh for gnomes, Jartsam in Darnassus for night elves, Aalun in the Exodar for draenei, Kildar in Orgrimmar for orcs, Xar''Ti in Sen''jin Village for trolls, Kar Stormsinger in Bloodhoof Village for tauren, Velma Warnam in Brill for the Forsaken and Perascamin in Eversong Woods for blood elves. They teach Apprentice at level 20 for 4 gold and Journeyman at 40 for 50 gold.', 'riding trainer,mount trainer,randal hunter,ultham ironhorn,binjy featherwhistle,jartsam,aalun,kildar,xarti,kar stormsinger,velma warnam,perascamin', 'npc,mount,trainer', '', '', 'where do i learn riding|where is the riding trainer|where do i train apprentice riding|where is the riding trainer in stormwind|where do i learn to ride as a human|where is the riding trainer in orgrimmar|where do orcs learn riding|where do tauren learn riding|where do i learn riding as undead|where is the blood elf riding trainer|where do dwarves learn riding|where do gnomes learn to ride|where do night elves learn riding|where do draenei learn riding|where do trolls learn riding|where do i buy my first mount skill|who teaches journeyman riding|where do i go at 20 to learn riding|riding trainer|where is riding trainer|where to learn riding|how much is riding|apprentice riding cost|how much gold for riding|riding lvl 20 cost|journeyman riding cost|how much is journeyman riding|where do i get riding as horde|where do i get riding as alliance|who teaches riding|where do i buy riding skill|when can i learn riding');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('npc_flying_trainers', 'Flying and Cold Weather Flying Trainers', 'Expert and Artisan riding, the flying ranks, are taught in Outland and Northrend: Hargen Bronzewing (Alliance) and Wind Rider Jahubo (Horde) in Hellfire Peninsula, Ilsa Blusterbrew (Alliance) and Olrokk (Horde) in Terokkar Forest, and Maigra Keenfeather (Alliance) and Wind Rider Sabamba (Horde) in Borean Tundra. Cold Weather Flying is taught by Hira Snowdawn in Dalaran, Roxi Ramrocket at K3 in the Storm Peaks and Pilot Vic at River''s Heart in Sholazar Basin.', 'flying trainer,flight trainer,hargen bronzewing,wind rider jahubo,ilsa blusterbrew,olrokk,maigra keenfeather,wind rider sabamba,hira snowdawn,roxi ramrocket,pilot vic', 'npc,mount,trainer', '', '', 'where do i learn to fly|where is the flying trainer|where do i learn expert riding|where do i learn artisan riding|where do i train flying in outland|where is the flying trainer in hellfire|where do i learn cold weather flying|where is the cold weather flying trainer|where is hira snowdawn|where do i learn epic flying|where do i get flying skill|where do horde learn flying|where do alliance learn flying|who teaches cold weather flying in dalaran|where is the flying trainer in northrend|where do i learn 280 flying');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_alchemy', 'Alchemy Profession', 'Alchemists turn herbs into potions, elixirs and flasks, so the profession pairs with Herbalism. Its Mixology perk makes the flasks and elixirs an alchemist knows stronger and longer-lasting on them, and transmutes turn materials into rarer ones, such as Titanium. Grand Master alchemy is taught in Dalaran.', 'alchemy,alchemist,alch,transmute,transmutes,transmutation,mixology', 'profession,crafting,consumables,raiding,all classes', 'gold', 'Transmute: Titanium has no cooldown, so run it whenever a Titanium Bar sells for more than the Saronite Bars it uses. Eternal transmutes share the daily transmute cooldown, so spend it on whichever Eternal sells highest. Pick Transmutation Master for procs on transmutes, or Elixir Master to proc extra flasks, and stock Flask of Endless Rage and Flask of the Frost Wyrm before raid nights.', 'what does alchemy do|is alchemy worth it|how do i make flasks|alch or herbalism|what is transmute titanium|where do i learn grand master alchemy|how do i make potions and elixirs|what profession makes flasks|does alch need herbalism|what is mixology|best way to make gold with alch|which flask for raids alch|transmutation master or elixir master|what profession do i take for potions|alchemist perks wotlk|how do i turn saronite into titanium');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_blacksmithing', 'Blacksmithing Profession', 'Blacksmiths make plate and mail armor, weapons and the Eternal Belt Buckle from bars smelted out of ore, so it pairs with Mining. Trainers are in most capitals, the Grand Master rank (skill 350 to 450) is taught in Dalaran, and at 400 skill a blacksmith can add a socket to their own bracers and gloves.', 'blacksmithing,blacksmith,smithing,socket bracer,socket gloves,plate crafting', 'profession,crafting,weapons,armor,raiding,warrior,paladin', '', '', 'what does blacksmithing do|is bs worth it|bs or jc|where do i train grand master blacksmithing|how do i add a socket to my bracers|what profession makes plate armor|how do i get an extra gem slot on gloves|what is the eternal belt buckle|does blacksmithing need mining|blacksmith perk wotlk|what can blacksmiths craft|what profession makes weapons|how do i get a belt buckle socket|where is the bs trainer|what skill do i need for bs sockets');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_enchanting', 'Enchanting Profession', 'Enchanters disenchant green and better items into dusts, essences and shards (Infinite Dust, Greater Cosmic Essence and Dream Shards in Northrend, Abyss Crystals from epics) and use them to enchant gear. It needs no gathering profession, and its perk is enchanting your own rings. To level it, disenchant spare greens for materials and craft enchants shown orange or yellow, training the next rank at skill 50, 125, 200, 275 and 350.', 'enchanting,enchanter,disenchant,disenchanting,dust,infinite dust,dream shard,abyss crystal,cosmic essence,ring enchant,ench', 'profession,crafting,enhancements,auction house,all classes', 'gold', 'Disenchant the cheap green and blue items other players list and sell the Infinite Dust, Greater Cosmic Essence and Dream Shards that come out, or use them yourself. Put popular enchants on a scribe''s vellum and sell the scrolls: weapon enchants like Berserking and Black Magic and cloak and boot enchants move every day.', 'what does enchanting do|is ench worth it|how do i disenchant stuff|what is infinite dust|what do i get from disenching greens|can i enchant my own rings|does enchanting need a gathering profession|how do i get abyss crystals|how do i make enchant scrolls|what are dream shards for|how do i make money with enchanting|what is greater cosmic essence|enchanter perk wotlk|which profession lets me enchant gear|how do i de items|can i sell enchants on the ah|what enchants sell best|how do i level enchanting|how to level enchanting fast|how do i get enchanting to 450|what do i craft to level enchanting|enchanting leveling guide|how do i skill up enchanting|what do i enchant to level up|how do i level up ench|how do i get enchanting skill');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_engineering', 'Engineering Profession', 'Engineers build guns, scopes, explosives and gadgets from mined metal, so it pairs with Mining. Their perk is tinkers like Hyperspeed Accelerators on gloves and Nitro Boosts on boots, plus the Wormhole Generator: Northrend and the Mekgineer''s Chopper or Mechano-Hog. To level it, smelt bars and craft each rank''s orange recipes: Rough Blasting Powder first, then Handful of Copper Bolts (30), Copper Tube and Rough Boomstick (50) and Coarse Blasting Powder (75), training the next rank at skill 50, 125, 200, 275 and 350.', 'engineering,engineer,engi,hyperspeed accelerators,nitro boosts,wormhole,wormhole generator,mechano hog,mekgineers chopper,scope,scopes', 'profession,crafting,devices,specialized,all classes', '', '', 'what does engineering do|is engi worth it|how do i get a motorcycle|how do i get the chopper|what is mekgineer''s chopper|what are hyperspeed accelerators|what is a nitro boost|what is the wormhole generator|does engineering need mining|what profession makes guns|how do i make scopes|engineer perks wotlk|what can engineers make|how do i get the mechano hog|how do i get gloves with a speed boost|engi tinkers for boots|how to level engineering fast|how do i get engineering to 450|what do i craft to level engineering|what do i make to skill up engineering|engineering leveling guide|how do i skill up engineering from 1|what engineering recipes level fastest|how do i level up engi');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_herbalism', 'Herbalism Profession', 'Herbalists gather herbs for Alchemy and Inscription, with Find Herbs showing nodes on the minimap. Skill needed in Northrend: Goldclover 350, Tiger Lily 375, Talandra''s Rose 385, Adder''s Tongue 400, Lichbloom 425, Icethorn 435 and the rare Frost Lotus 450. The perk Lifeblood is a self-heal.', 'herbalism,herbalist,herb,herbs,herbing,frost lotus,lichbloom,icethorn,adders tongue,goldclover,lifeblood,find herbs,peacebloom,silverleaf', 'profession,gathering,materials,alchemy,inscription', 'gold', 'Farm a loop in Sholazar Basin for Adder''s Tongue, or Icecrown and the Storm Peaks for Lichbloom and Icethorn; any Northrend node can also give a Frost Lotus, which sells high. Herbs sell in stacks of 20 to scribes and alchemists.', 'what does herbalism do|is herbalism worth it|how do i find herbs|what is find herbs|where do i farm lichbloom|where is frost lotus|where do i get icethorn|where do i farm adder''s tongue|what herbs are in northrend|what is lifeblood|best herb farming spot wotlk|herbs for alchemy and inscription|how do i make gold with herbing|how do i get frost lotus|tiger lily location|where do i farm herbs at 80|what is goldclover|what herbalism skill for lichbloom|what skill do i need for frost lotus|herbalism skill for icethorn|what skill to pick adders tongue|herb skill requirements northrend|can i pick frost lotus at 400|what skill for goldclover|how much herbalism for tiger lily|what herbalism level for talandras rose');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_inscription', 'Inscription Profession', 'Scribes mill herbs, five at a time, into pigments, turn those into inks, and make glyphs, off-hand books, Darkmoon Cards and vellums. Their perk is Master''s Inscription shoulder enchants for themselves, and Grand Master Inscription is taught in Dalaran.', 'inscription,scribe,scribes,milling,mill herbs,pigment,pigments,ink,inks,darkmoon card,darkmoon cards,vellum', 'profession,crafting,spell mods,cosmetic,all classes', 'gold', 'Glyphs are the money: learn as many as you can through Northrend Inscription Research and Minor Inscription Research, mill the cheapest Northrend herbs for pigments, and list a few of every glyph so you are never out of stock. A finished Darkmoon Card deck, such as the one that makes Greatness, sells for a lot.', 'what does inscription do|is inscription worth it|how do i make glyphs|what is milling|how do i mill herbs|what do scribes make|what are pigments and inks|how do i learn new glyphs|how do i make darkmoon cards|how do i make gold with inscription|what is master''s inscription|scribe perk for shoulders|where do i learn grand master inscription|how do i make a vellum|what is the greatness card|best profession for glyphs|how do i make an offhand book');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_jewelcrafting', 'Jewelcrafting Profession', 'Jewelcrafters prospect ore, five at a time, for raw gems, cut them, and make rings, necklaces and trinkets, so it pairs with Mining. Their perk is Dragon''s Eye gems only they can socket, up to three. Timothy Jones in Dalaran gives a daily quest paying tokens for new designs.', 'jewelcrafting,jewelcrafter,jc,prospect,prospecting,dragons eye,dragons eyes,cut gems', 'profession,crafting,jewelry,sockets,valuable,all classes', 'gold', 'Prospect Saronite and Titanium ore for gems; Titanium is the one that gives the epic gems. Cut what raiders actually socket, red strength, agility and spell power gems sell fastest, and do the Timothy Jones daily in Dalaran every day: its tokens buy new designs, Dragon''s Eye designs included. Selling cut gems beats selling raw gems almost every time.', 'what does jewelcrafting do|is jc worth it|how do i get dragon''s eye gems|what is prospecting|how do i prospect ore|how do i cut gems|who is timothy jones|what is the jc daily in dalaran|how do i get epic gems|what are dragon''s eyes|how many dragon''s eye gems can i use|jewelcrafter perk wotlk|does jc need mining|how do i make gold with jc|how do i learn new gem designs|what profession makes rings and necklaces|which gems sell fastest');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_leatherworking', 'Leatherworking Profession', 'Leatherworkers make leather and mail armor, armor kits, leg armors like Icescale Leg Armor, and drums from skinned leather, so it pairs with Skinning. Their perk is Fur Lining bracer enchants for themselves.', 'leatherworking,leatherworker,lw,fur lining,leg armor,armor kit,drums', 'profession,crafting,armor,bags,leather classes,druid,rogue,hunter', '', '', 'what does leatherworking do|is lw worth it|what is fur lining|what is icescale leg armor|how do i get leg armor for my pants|what profession makes armor kits|what profession makes mail armor|how do i make drums|does leatherworking need skinning|leatherworker perks wotlk|what is the lw bracer enchant|what can leatherworkers make|lw or skinning|what profession makes leather gear|how do i get a leg enchant');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_mining', 'Mining Profession', 'Mining is learned from a mining trainer in any capital or large town. Miners gather ore from nodes shown with Find Minerals and smelt it into bars at a forge. Skill needed to mine: Mithril 175, Fel Iron 275, Adamantite 325, Cobalt 350, Khorium and Rich Cobalt 375, Saronite 400, Rich Saronite 425, Titanium 450. Cobalt grows in Borean Tundra, Howling Fjord, Grizzly Hills, Dragonblight and Zul''Drak; Saronite and Titanium in Icecrown, Sholazar Basin and Zul''Drak. Toughness adds stamina.', 'mining,miner,ore,ores,smelting,smelt,cobalt,saronite,titanium,toughness,find minerals,mining node', 'profession,gathering,materials,crafting,blacksmithing,engineering,jewelcrafting', 'gold', 'Saronite is the volume ore, thickest in Sholazar Basin, Icecrown and the Storm Peaks, and a Saronite node can be a Titanium vein at random. Sell Titanium raw, or smelt it only when the bar is worth more than the ore. Mining plus Herbalism is the best pair for pure farming, since you pick up both nodes on one route.', 'what does mining do|is mining worth it|where do i learn mining|where is the mining trainer|how do i find ore|what is find minerals|how do i smelt ore|where do i farm saronite|how do i get titanium|where do i find titanium ore|what is toughness|what ore is in northrend|best ore farming spot wotlk|how do i make gold mining|mining and herbalism together|where do i learn to mine|where do i get a mining pick|which profession smelts bars|what mining skill do i need for saronite|what skill for cobalt|mining skill for titanium|what skill to mine adamantite|what mining level for mithril|what skill is needed to mine saronite|can i mine saronite at 350|what do i need to mine titanium|mining skill requirements northrend|how high does mining need to be for cobalt|what skill do i need to mine fel iron|how much mining skill for rich saronite|where is cobalt|where do i find cobalt');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_skinning', 'Skinning Profession', 'Skinners skin dead beasts, and some dragonkin, for leather and hides used in Leatherworking; humanoids drop cloth instead. From skill 100 a mob needs about five skill per mob level, so a level 70 mob needs 350 and a level 80 one needs 400. To level it, skin mobs close to your limit, since those within 25 skill of yours always raise it. Northrend gives Borean Leather and the rare Arctic Fur; the perk Master of Anatomy adds critical strike rating.', 'skinning,skinner,hides,borean leather,arctic fur,master of anatomy', 'profession,gathering,materials,leatherworking', 'gold', 'Skinning pays well alongside an AoE class: pull groups of beasts in Sholazar Basin or Zul''Drak and skin them all. Borean Leather sells by the stack, Arctic Fur is the prize, and Heavy Borean Leather is worth making when it sells for more than the leather that goes into it.', 'what does skinning do|is skinning worth it|how do i skin mobs|what is borean leather|how do i get arctic fur|where do i farm leather|what is master of anatomy|can i skin humanoids|where is the best place to skin in northrend|skinning for leatherworking|how do i make gold skinning|what is heavy borean leather|what can i skin|skinner perk wotlk|why cant i skin this mob|skinning with an aoe class|what skill do i need to skin level 80 mobs|why cant i skin level 70 mobs|how do i level skinning|how to level skinning fast|what skinning level for northrend|what skill to skin level 75|skinning skill needed per mob level|which mobs should i skin to level|how do i get skinning to 450|how high does skinning need to be for northrend mobs');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_tailoring', 'Tailoring Profession', 'Tailors sew cloth gear and bags from cloth looted off humanoids, like Frostweave Cloth in Northrend, and need no gathering profession. Their perk is cloak embroideries only they can use, Lightweave, Darkglow and Swordguard, and they make Moonshroud, Ebonweave and Spellweave cloth for the best tailored gear.', 'tailoring,tailor,frostweave bag,embroidery,lightweave,darkglow,swordguard,moonshroud,ebonweave,spellweave', 'profession,crafting,armor,bags,cloth classes,mage,priest,warlock', 'gold', 'Frostweave Bags always sell, since everyone needs bag space, and the 22-slot Glacial Bag is the prize, though it can only be sewn about once a week. Moonshroud, Ebonweave and Spellweave have no cooldown and go into the best tailored gear, so make them when the cloth is cheap.', 'what does tailoring do|is tailoring worth it|how do i make bags|what is frostweave cloth|what is the glacial bag|how do i make a 22 slot bag|what is lightweave embroidery|what are darkglow and swordguard|how do i make moonshroud|what is ebonweave|what is spellweave|tailor perks wotlk|how do i make cloth gear|does tailoring need a gathering profession|what profession makes bags|how do i get cloak embroidery');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_cooking', 'Cooking Profession', 'Cooking is a secondary profession anyone can learn alongside two primaries. Food gives Well Fed buffs, and the Fish Feast feeds a whole raid. Dozens of Northrend recipes are bought with Dalaran Cooking Awards from the cooking dailies of Katherine Lee or Awilo Lon''gomba in Dalaran.', 'cooking,cook,fish feast,cooking recipe,cooking recipes,dalaran cooking award', 'profession,secondary,consumables,buffs,raiding', '', '', 'what does cooking do|is cooking worth it|how do i make food|what is the fish feast|what are dalaran cooking awards|who is katherine lee|who is awilo lon''gomba|how do i get cooking recipes in northrend|how do i get well fed|can anyone learn cooking|is cooking a primary profession|how do i make food for a raid|where do i get northrend cooking recipes|what is the cooking daily|how do i level cooking');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_fishing', 'Fishing Profession', 'Learn Fishing from a fishing trainer, buy a Fishing Pole, and cast in any open water; lures like Nightcrawlers add skill for ten minutes. Marcia Chase in Dalaran gives a daily fishing quest, and Stranglethorn Vale''s Fishing Extravaganza runs on Sundays.', 'fishing,fish,fishing pole,lure,lures,fishing skill,fishing trainer,fishing extravaganza,kaluak fishing derby,nightcrawlers', 'profession,secondary,gathering,materials,consumables', '', '', 'what does fishing do|is fishing worth it|how do i fish|where do i learn fishing|where do i get a fishing pole|what is a nightcrawler|how do i use lures|who gives the fishing daily|who is marcia chase|what is the fishing extravaganza|when is the stv fishing contest|how do i level fishing|do i need a pole to fish|where can i cast my line|is fishing a secondary profession');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_first_aid', 'First Aid Profession', 'First Aid is a secondary profession every character can learn, used to make bandages from cloth that heal over a short channel. Damage interrupts a bandage, and Recently Bandaged blocks another for a minute. The best one, Dense Frostweave Bandage, is learned from a manual at 450 skill.', 'first aid,bandage,bandages,recently bandaged,frostweave bandage', 'profession,secondary,consumables,healing,solo', '', '', 'what does first aid do|how do i make bandages|how do i learn first aid|what is dense frostweave bandage|where do i get the frostweave bandage manual|what is recently bandaged|why did my bandage stop|can i bandage in combat|is first aid a secondary profession|how do i level first aid|do i need first aid|what skill is the best bandage|can any class use bandages|what do bandages need');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('mage_professions_guide', 'Best Professions for Mages', 'For mages the useful perks are Tailoring''s Lightweave Embroidery, a spell power proc on the cloak, and Enchanting''s ring enchants, and Tailoring makes cloth gear a mage can wear. Jewelcrafting''s Dragon''s Eyes are another option.', 'mage professions,professions for mage,best professions for mage,mage crafting,mage tradeskills,mage profession perks', 'profession,mage,cloth classes,spellcaster', '', '', 'what profession should my mage take|best professions for mage|best prof for a mage|mage tailoring or enchanting|what is lightweave for mages|what should my mage pick|good professions for a mage|should my mage do jc|is tailoring good for mages|what profession for a mage at 80|mage professions wotlk|which professions help casters most');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('warrior_professions_guide', 'Best Professions for Warriors', 'For warriors, Blacksmithing adds sockets to bracers and gloves and makes plate, Jewelcrafting gives Dragon''s Eyes, and Mining''s Toughness adds stamina for tanks. Engineering''s Hyperspeed Accelerators suit DPS warriors.', 'warrior professions,professions for warrior,best professions for warrior,warrior crafting,warrior tradeskills,warrior profession perks', 'profession,warrior,plate classes,melee', '', '', 'what profession should my warrior take|best professions for warrior|best prof for a warrior|warrior bs and mining|should my warrior be a blacksmith|good professions for a warrior|what should a tank warrior pick|best professions for a tank|warrior professions wotlk|should my warrior mine|is engineering good for dps warriors|what profession should my war pick');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('paladin_professions_guide', 'Best Professions for Paladins', 'For paladins, Blacksmithing adds sockets to bracers and gloves and makes plate, and Jewelcrafting gives Dragon''s Eyes; holy paladins often add Enchanting for ring enchants or Inscription for shoulder inscriptions.', 'paladin professions,professions for paladin,best professions for paladin,paladin crafting,paladin tradeskills,paladin profession perks', 'profession,paladin,plate classes,healer,tank', '', '', 'what profession should my paladin take|best professions for pally|best prof for a paladin|pally blacksmithing or jc|should my pally be a blacksmith|good professions for a paladin|what should a holy pally pick|what profession for a holy paladin|paladin professions wotlk|should my pally take enchanting|best professions for a ret pally|what should my pally pick for professions');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('hunter_professions_guide', 'Best Professions for Hunters', 'For hunters, Engineering makes guns and scopes and gives Hyperspeed Accelerators, Leatherworking makes mail and Fur Lining, and Jewelcrafting gives Dragon''s Eyes. Skinning pairs with Leatherworking.', 'hunter professions,professions for hunter,best professions for hunter,hunter crafting,hunter tradeskills,hunter profession perks', 'profession,hunter,leather classes,ranged', '', '', 'what profession should my hunter take|best professions for hunters|best prof for a hunter|hunter engineering or lw|should my hunter do engi|good professions for a hunter|what should a hunter pick|hunter professions wotlk|does a hunter need skinning|what profession makes guns and scopes for hunters|best professions for a bm hunter|hunter jc or leatherworking');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('rogue_professions_guide', 'Best Professions for Rogues', 'For rogues, Leatherworking makes leather gear and gives Fur Lining, Engineering adds Hyperspeed Accelerators and gadgets, and Jewelcrafting gives Dragon''s Eyes. Rogues open lockboxes themselves, so they need no key-making profession.', 'rogue professions,professions for rogue,best professions for rogue,rogue crafting,rogue tradeskills,rogue profession perks', 'profession,rogue,leather classes,melee,stealth', '', '', 'what profession should my rogue take|best professions for rogue|best prof for a rogue|rogue leatherworking or engi|should my rogue be an engineer|good professions for a rogue|do rogues need a key profession|do rogues need blacksmithing for keys|rogue professions wotlk|what should my rogue pick|can rogues open lockboxes without a profession|best professions for a combat rogue');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('priest_professions_guide', 'Best Professions for Priests', 'For priests, Tailoring makes cloth gear and gives Lightweave Embroidery, Enchanting gives ring enchants, and Inscription gives shoulder inscriptions and glyphs. Jewelcrafting gives Dragon''s Eyes.', 'priest professions,professions for priest,best professions for priest,priest crafting,priest tradeskills,priest profession perks', 'profession,priest,cloth classes,healer,caster', '', '', 'what profession should my priest take|best professions for priests|best prof for a priest|priest tailoring and enchanting|should my priest do inscription|good professions for a priest|best professions for a holy priest|priest professions wotlk|what should my priest pick|is tailoring good for priests|what profession for a shadow priest|should my priest take jc');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('shaman_professions_guide', 'Best Professions for Shamans', 'For shamans, Leatherworking makes mail and gives Fur Lining, Jewelcrafting gives Dragon''s Eyes, and Enchanting gives ring enchants. Skinning or Mining pair with those for materials.', 'shaman professions,professions for shaman,best professions for shaman,shaman crafting,shaman tradeskills,shaman profession perks', 'profession,shaman,leather classes,healer,caster,melee', '', '', 'what profession should my shaman take|best professions for shamans|best prof for a shaman|shaman leatherworking or jc|should my shaman do lw|good professions for a shaman|what should my shammy pick|shaman professions wotlk|best professions for an ele shaman|does a shaman need skinning|best professions for a resto shaman|what profession makes mail for shamans');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('warlock_professions_guide', 'Best Professions for Warlocks', 'For warlocks, Tailoring makes cloth gear and gives Lightweave Embroidery, Enchanting gives ring enchants, and Jewelcrafting gives Dragon''s Eyes. Soulstones and healthstones are warlock spells, not crafts.', 'warlock professions,professions for warlock,best professions for warlock,warlock crafting,warlock tradeskills,warlock profession perks', 'profession,warlock,cloth classes,caster', '', '', 'what profession should my warlock take|best professions for warlocks|best prof for a lock|lock tailoring or enchanting|should my lock be a tailor|good professions for a warlock|do warlocks craft healthstones|does a lock need a profession for soulstones|warlock professions wotlk|what should my warlock pick|best professions for a destro lock|what profession for an affliction lock');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('druid_professions_guide', 'Best Professions for Druids', 'For druids, Leatherworking makes leather gear and gives Fur Lining, Jewelcrafting gives Dragon''s Eyes, and Enchanting gives ring enchants. Herbalism also heals with Lifeblood.', 'druid professions,professions for druid,best professions for druid,druid crafting,druid tradeskills,druid profession perks', 'profession,druid,leather classes,healer,caster,melee', '', '', 'what profession should my druid take|best professions for druids|best prof for a druid|druid leatherworking or jc|should my druid take herbalism|good professions for a druid|what should my resto druid pick|druid professions wotlk|does a druid need skinning|best professions for a feral druid|what profession for a balance druid|is herbalism good for druids');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_overview', 'Professions', 'A character can have two primary professions, and most fill both: two gathering ones (Herbalism, Mining, Skinning) make the most gold, or one gathering plus the crafting one it feeds (Alchemy, Blacksmithing, Enchanting, Engineering, Inscription, Jewelcrafting, Leatherworking, Tailoring). Cooking, Fishing and First Aid are secondary and don''t count. Skill caps at 450, taught by Grand Master trainers in Northrend.', 'profession,professions,prof,profs,primary profession,secondary profession', 'profession,overview', '', '', 'how many professions can i have|how many professions can i learn|what are the primary professions|which professions make the most gold|what is the best profession combo|what are secondary professions|best two professions for gold|which professions go together|what is the max profession skill|how high can profession skill go|which profession should i pick|can i learn all the professions|what professions are there|where do i learn professions in northrend|should i get two gathering professions|what is a gathering profession|which crafting profession goes with mining|can i have more than two professions|how many primary professions can i have|how many crafting professions can i have|can i have two gathering and two crafting professions|what is the profession limit');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_skill_ranks', 'Profession Skill Ranks', 'Primary professions train in six ranks: Apprentice (skill 1-75), Journeyman (75-150), Expert (150-225), Artisan (225-300), Master (300-375) and Grand Master (375-450). Apprentice is learned at level 5 for a few copper. Journeyman costs 5 silver, Expert 50 silver, Artisan 5 gold, Master 10 gold and Grand Master 35 gold. Each rank unlocks when your skill is within 25 of the cap and you reach level 10, 20, 35 and 50, with Grand Master needing level 55 to 65 depending on the craft.', 'profession ranks,skill ranks,journeyman,profession tiers,skill tiers', 'profession,mechanic,trainer', '', '', 'how do profession ranks work|what are the profession ranks|what are the profession tiers|what is journeyman|what level for artisan professions|when can i learn expert engineering|how much does grand master cost|how much is artisan blacksmithing|what level do i need for grand master|why cant i level my profession past 75|how do i get past 150 skill|what level for master trainer|how much gold for master tailoring|what skill do i need to train expert|how much do profession ranks cost|what do apprentice and journeyman mean|how much is journeyman enchanting|when do i go back to the profession trainer');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_grand_master_trainers', 'Master and Grand Master Profession Trainers', 'Apprentice through Artisan are taught by trainers in the capitals and many towns. Master (skill 300-375) is taught in Outland, in Hellfire Peninsula and Shattrath City among others, and also by the Northrend trainers. Grand Master (375-450) is taught in Northrend: Dalaran, Valgarde and Vengeance Landing in Howling Fjord, Valiance Keep and Warsong Hold in Borean Tundra, and Hrothgar''s Landing in Icecrown for most crafts. Blacksmiths also have one in Wintergrasp.', 'grand master trainer,master trainer,grand master engineering,grand master enchanting,grand master blacksmithing,grand master tailoring,grand master alchemy,grand master leatherworking,grand master jewelcrafting,grand master mining,grand master skinning,grand master herbalism,master profession trainer', 'profession,npc,trainer,northrend', '', '', 'where do i learn grand master engineering|where is the grand master enchanting trainer|where do i train 375 to 450|where do i learn master tailoring|where are master profession trainers|where do i go to get past 300 skill|where do i learn artisan alchemy|where do i train 350 skill|where is the 450 blacksmith trainer|where do i train jewelcrafting in northrend|grand master trainer location|where do i get 375 skill|where to learn master mining|which towns have grand master trainers|do i have to go to dalaran for grand master|where do i learn grand master skinning|where is the grand master inscription trainer|where do i learn master engineering in outland');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_leveling', 'Leveling a Profession', 'Orange recipes and nodes always raise skill, yellow ones usually, green ones sometimes and grey ones about 10% of the time. On this realm each skill-up gives 3 points when crafting and 4 when gathering. Gathering skills level by gathering or skinning a little above your skill. Crafting skills eat materials: bars for Blacksmithing, Engineering and Jewelcrafting, herbs for Alchemy and Inscription, leather, cloth, and disenchanted items for Enchanting. Train the next rank at skill 50, 125, 200, 275 and 350.', 'level profession,leveling professions,recipe colors,orange recipes,yellow recipes', 'profession,mechanic,leveling', '', '', 'how do i level my profession|how do i level a profession fast|how do i skill up crafting|what do the recipe colors mean|do grey recipes give skill|why am i not gaining skill|how many skill points per craft|how fast do professions level here|tips for leveling professions|what is the fastest way to 450|how do i get my profession to 450|does gathering raise skill|should i craft green recipes|what does orange mean on a recipe|how do i raise my profession skill|how do i get skill points in a profession|do yellow recipes always skill up|how many points per skill up|how much skill per craft|is prof leveling boosted|does crafting give 3 skill points|prof skill gain here|how to skill up fast|why wont my skill go up|do gray recipes skill up|what does yellow mean on recipe|orange recipe skill up|how do i level mining|how do i level herbalism|grey recipe skill chance|when do i train next prof rank');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('profession_unlearn', 'Dropping a Profession', 'To drop a primary profession, open the Skills tab of the character pane, select the profession and press its Unlearn button. You lose all its skill points and every recipe you know for it, and learning it again means starting over from Apprentice with a trainer. Secondary professions (Cooking, Fishing, First Aid) can''t be unlearned. With two primaries allowed, dropping one is how you switch.', 'drop profession,unlearn profession,forget profession,abandon profession,unlearn mining,unlearn skinning,unlearn herbalism,unlearn engineering', 'profession,mechanic', '', '', 'how do i unlearn a profession|how do i forget a profession|how do i remove a profession|can i change my profession|how do i switch professions|how to unlearn mining|how do i get rid of a profession|can i unlearn cooking|will i lose my recipes if i drop a profession|do i lose skill if i unlearn a profession|how do i abandon my profession|can i reset my profession|how do i unlearn skinning|can i relearn a profession after dropping it|where is the unlearn button for professions|i picked the wrong profession how do i drop it');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_battlegrounds', 'Battlegrounds', '3.3.5 has six battlegrounds: Warsong Gulch (capture the flag, from level 10), Arathi Basin (five nodes, from 20), Alterac Valley (40 a side, from 51), Eye of the Storm (from 61), and Strand of the Ancients and Isle of Conquest (both from 71). Queue from a Battlemaster or the PvP window. Wintergrasp is a zone, not a battleground.', 'battleground,battlegrounds,bg,bgs,queue for bg,pvp queue', 'pvp,battlegrounds,teamwork,honor', 'pvp', 'Do the random battleground for its daily first-win bonus. In node maps like Arathi Basin and Eye of the Storm, holding three nodes and defending them wins; chasing a five-cap loses. Fight on objectives, not in the middle of the road, and call out incoming players in chat.', 'what bgs are there in wotlk|how many battlegrounds are there|list of battlegrounds|which bgs are there|how do i queue for a bg|is wintergrasp a bg|what level does each bg start at|best bg for honor farming|how do i win node bgs|why do we lose ab when we chase kills|should i do random bg|how many nodes should we hold in bg|what bgs open at 71|bg tips for newbies|do i need to call incoming in bg');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_arenas', 'Arena Combat', 'Arena teams fight 2v2, 3v3 or 5v5 in Nagrand Arena, Blade''s Edge Arena, the Ruins of Lordaeron, the Dalaran sewers and the Ring of Valor. Rated matches move your team rating, and Arena Points are paid out weekly by rating if you played at least 10 games that week; skirmishes are unrated practice.', 'arena,arenas,2v2,3v3,5v5,arena team,arena rating,skirmish,skirmishes,ring of valor,dalaran arena', 'pvp,arena,skill,competition', 'pvp', 'The strong 3v3 teams are Rogue, Mage and Priest, Warrior or Death Knight with a Holy Paladin, and two casters with a healer. In 2v2 a damage dealer with a healer is the easy start. Arena Points need 10 games a week, and you must play at least 30% of your team''s games to get them. Focus one target, chain crowd control through diminishing returns, and save your trinket for the stun that would actually kill you.', 'how do arenas work|what arenas are there|what is a skirmish|how do i get arena points|how many games for arena points|best 3v3 comp|best 2v2 comp|what comp should i run in arena|how do i start arena|what is an arena team|how does arena rating work|what is ring of valor|where is the dalaran arena|arena tips|when should i use my trinket in arena|2v2 or 3v3 easier|how do i make an arena team');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_world_pvp', 'World PvP', 'World PvP happens anywhere outside sanctuaries: classic hot spots are Tarren Mill against Southshore in Hillsbrad Foothills and the Gurubashi Arena in Stranglethorn Vale, and Wintergrasp is Northrend''s open-world PvP zone, where the attackers besiege the fortress with siege vehicles on a timer.', 'world pvp,wpvp,tarren mill,southshore,gurubashi arena,open world pvp', 'pvp,world,open_world,rivalries', '', '', 'where is good world pvp|what is tarren mill vs southshore|where do i do open world pvp|what is gurubashi arena|how does wintergrasp work|wpvp spots|where can i find pvp fights outside bgs|is there world pvp in northrend|what is tm vs ss|where do the horde and alliance fight in hillsbrad|where is gurubashi|is wg open world pvp|how do attackers win wintergrasp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_ranks', 'PvP Ranks and Titles', 'The old Vanilla system of 14 numbered PvP ranks was replaced when the honor system was overhauled in the Burning Crusade: honor points are now spent directly on gear instead of being ground through ranks. The prestigious ''Grand Marshal'' (Alliance) and ''High Warlord'' (Horde) titles still exist, but are now awarded to the single highest-rated arena player of each class and faction at the end of a PvP season, alongside seasonal Gladiator titles for the top-rated teams. Titles are prestigious and show PvP dedication.', 'pvp rank,pvp ranks,pvp title,pvp titles,grand marshal,high warlord,gladiator,rank 14,duelist', 'pvp,ranks,titles,prestige', '', '', 'how do pvp ranks work|are there still pvp ranks|how do i get grand marshal|how do i get high warlord|what happened to rank 14|how do i get the gladiator title|pvp titles in wotlk|how do you get a pvp title|is rank 14 still a thing|what is the old honor system|who gets grand marshal now|do i need to grind ranks for pvp gear');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_gear_progression', 'PvP Gear Progression', 'PvP gear carries resilience, which lowers the chance to be crit and the damage taken from players. Entry pieces are bought with Honor, the season''s best pieces need Arena Points, and the top items also require a personal arena rating. Honor caps at 75,000, so spend it before hitting the cap.', 'pvp gear,honor gear,arena gear,resilience,resil,resi,gladiator gear,pvp set,pvp sets', 'pvp,gear,progression,equipment', 'pvp', 'Buy honor gear for the off-pieces first, neck, rings, cloak, belt, bracers and boots, then get the five-piece set with Arena Points, since the set bonuses matter. The season''s best weapons and shoulders need a personal rating, so climb in 3v3 where rating is easiest to earn.', 'how do i gear for pvp|what is resilience|what does resil do|how do i get pvp gear|best way to get arena gear|honor gear or arena gear first|what gear should i buy with honor|what is the honor cap|do i need rating for pvp weapons|how do i get gladiator gear|is resi worth stacking|which pvp pieces need arena points|pvp set bonus worth it|how do i get pvp shoulders|what pvp gear do i buy first');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_faction_conflicts', 'Faction Conflicts', 'The faction war flared at the Wrathgate in Dragonblight, where Grand Apothecary Putress unleashed a plague that killed both Bolvar Fordragon and Dranosh Saurfang. Varimathras seized the Undercity at the same time, and Thrall and King Varian Wrynn retook it together in the Battle for the Undercity.', 'wrathgate,battle for the undercity,putress,faction war,alliance vs horde,horde vs alliance', 'pvp,factions,conflicts,lore', '', '', 'what happened at the wrathgate|who killed bolvar|what is the battle for the undercity|who is putress|who took over the undercity|who killed saurfang|what is the faction war about|what happened to varimathras|alliance vs horde story|where is the wrathgate|who is grand apothecary putress|did thrall and varian retake the undercity|what is the lore behind horde vs alliance in wotlk|how did bolvar fordragon die');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_honor_system', 'Honor System', 'Honor comes from honorable kills, battleground wins and objectives, and Wintergrasp; a player low enough to show grey to you gives none. Honor doesn''t decay and caps at 75,000, and it''s spent with PvP vendors on gear.', 'honor,honor points,honor cap,honor farm,farm honor,honor system,honorable kills,hks', 'pvp,honor,system,rewards', 'pvp', 'The fastest honor is the random battleground: the first win each day pays a big bonus and Arena Points, and later wins pay less. Winning Alterac Valley and Isle of Conquest is the most honor per match, and holding Wintergrasp gives honor plus Vault of Archavon access. Spend honor before you reach the 75,000 cap.', 'how do i farm honor|fastest way to get honor|what is the honor cap|does honor decay|how do i get honor points|best bg for honor|what gives honor|do grey kills give honor|what do i spend honor on|how much honor does the random bg give|does wintergrasp give honor|is av good for honor|honor farm tips|what is a hk');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_ganking', 'Ganking and Ambush Tactics', 'Ganking is a much higher-level player killing a low-level one, common on PvP realms in contested zones like Stranglethorn Vale and Hillsbrad Foothills. It earns the ganker nothing, since a target low enough to show grey gives no honor. The usual answers are calling friends or a guard, or leaving the area.', 'gank,ganking,ganked,ganker,gankers,corpse camping,corpse camped,camping', 'pvp,tactics,ganking,controversy', '', '', 'what is ganking|how do i stop getting ganked|someone keeps ganking me|how do i deal with a ganker|what is corpse camping|i got corpse camped help|is ganking worth honor|do you get honor for ganking low levels|how do i avoid gankers in stv|gankers in hillsbrad what do i do|why do high levels gank|how do i stop being camped|what to do when a high level is camping me');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_objectives', 'Battleground Objectives', 'How each battleground is won: Warsong Gulch, capture the enemy flag three times; Arathi Basin, hold more of the five nodes to win the resource race; Alterac Valley, kill the enemy general, Drek''Thar or Vanndar; Eye of the Storm, hold towers and carry the center flag; Strand of the Ancients, reach the relic faster; Isle of Conquest, break the keep and kill its general.', 'bg objectives,battleground objectives,flag carrier,efc,capture flag,cap a node,nodes', 'pvp,objectives,battlegrounds,strategy', '', '', 'how do you win each bg|what is the objective in av|what is the objective in wsg|what does efc mean|what is a flag carrier|how do i win sota|how do you win ioc|how do i cap a node|what do i do in eots|how many flag caps to win|what is the goal in arathi basin|who do i kill to win av|what is the objective of each battleground|how do you win a bg');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('pvp_rewards', 'PvP Rewards and Incentives', 'Beyond gear, PvP pays titles and mounts: each season''s top arena teams earn the Gladiator title and that season''s frost wyrm, the Deadly, Furious, Relentless and Wrathful Gladiator''s Frost Wyrm in Wrath, and the For the Alliance and For the Horde achievements, killing the enemy faction''s leaders, award a Black War Bear.', 'pvp rewards,pvp mount,gladiator mount,frost wyrm,black war bear', 'pvp,rewards,incentives,motivation', '', '', 'what are the pvp rewards|how do i get a gladiator mount|how do i get the frost wyrm|how do i get a black war bear|what are pvp mounts|what mounts can i get from pvp|how do i get the for the horde achievement|how do i get the for the alliance achievement|what is the deadly gladiator frost wyrm|pvp titles and mounts|is the black war bear still available|what do top arena teams get|how do you get the wrathful gladiator''s frost wyrm|what do i get for killing faction leaders');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_class_stories', 'Class-Specific Storylines', 'The best-known class storyline is the Death Knight''s: starting at level 55 in Acherus, the Ebon Hold, death knights serve the Lich King in the Scarlet Enclave of the Eastern Plaguelands, earn the Acherus Deathcharger, and break free at the Battle for Light''s Hope Chapel before being sent to their faction''s capital.', 'class quest,class quests,class storyline,death knight quests,dk starting zone,acherus,ebon hold,scarlet enclave', 'quests,story,class,lore', '', '', 'do classes have their own quest lines|what is the dk starting zone|where do death knights start|what is acherus|what is ebon hold|what level do dks start at|how do i get the acherus deathcharger|where is the scarlet enclave|what is the battle for light''s hope chapel|where do dks go after the starting zone|dk quest line|what is the dk story|are there class quests|how long is the death knight storyline|how do i get my dk mount');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_zone_storylines', 'Zone Story Arcs', 'Each Northrend zone follows its own story: the vrykul of Utgarde in Howling Fjord, the blue dragonflight and the Nexus in Borean Tundra, the Wrathgate in Dragonblight, the Drakkari trolls'' dying gods in Zul''Drak, Thorim and the secrets of Ulduar in the Storm Peaks, and the war on the Lich King''s doorstep in Icecrown.', 'zone story,zone storyline,zone storylines,storyline,storylines,story quests', 'quests,story,zones,progression', '', '', 'what is the story of each northrend zone|what are the storylines in northrend|what is the story in howling fjord|what is the story in borean tundra|what is the story in zul''drak|what is the story in the storm peaks|what is the story in icecrown|what is the story in dragonblight|which zone has the wrathgate|which zone is about the vrykul|what are the story quests in wotlk|zone story arcs in wrath|where is the thorim story');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_reputation_grinds', 'Reputation Quest Hubs', 'Northrend''s reputation dailies: the Argent Tournament in Icecrown, the Sons of Hodir at Dun Niffelem in the Storm Peaks, the Kalu''ak at their fishing villages, and in Sholazar Basin either the Oracles or the Frenzyheart, since siding with one turns the other hostile.', 'rep dailies,reputation dailies,reputation quests,daily hub,kaluak,argent tournament dailies', 'quests,reputation,grinding,rewards', '', '', 'what are the rep dailies in northrend|where do i farm reputation dailies|where are the argent tournament dailies|where do i do sons of hodir dailies|what are kalu''ak dailies|what is the oracles vs frenzyheart choice|can i be friends with both oracles and frenzyheart|which rep daily hubs are there|where is dun niffelem|where do i get kaluak rep|how do i grind rep in northrend|what are the daily hubs in wotlk|which sholazar faction should i pick|where do i do argent tournament|best rep grind in northrend');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_dungeon_quests', 'Dungeon and Raid Quests', 'Dungeons usually have quests from NPCs at or just inside the entrance, so check before zoning in. In Dalaran, Archmage Lan''dalock gives the weekly raid quest to kill a named boss, such as Patchwerk Must Die! or Lord Marrowgar Must Die!, for extra Emblems.', 'dungeon quest,dungeon quests,landalock,lan dalock', 'quests,dungeons,raids,lore', '', '', 'do dungeons have quests|where do i get dungeon quests|who is lan''dalock|where is landalock|what is the weekly raid quest|what is patchwerk must die|what is lord marrowgar must die|where do i get the weekly raid quest|how do i get extra emblems from a raid|do i check for quests before a dungeon|how do i pick up the raid weekly|where do i get weekly raid quest in dalaran|are there quests inside instances|what is the weekly boss quest');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_epic_questlines', 'Epic Quest Chains', 'A quest chain is a series where each quest unlocks the next. Wrath''s long ones include the Wrathgate and the Battle for the Undercity, the Sons of Hodir chain in the Storm Peaks, Quel''Delar from the Battered Hilt, and Shadowmourne for Icecrown Citadel raiders.', 'quest chain,quest chains,questline,questlines,epic quest,chain quest,long quest', 'quests,epic,storylines,rewards', '', '', 'what are the long quest chains in wotlk|what is a quest chain|how do i get quel''delar|what is the battered hilt|how do i get shadowmourne|what is the sons of hodir quest chain|which questlines are the longest|what are the epic questlines in wrath|what is the wrathgate questline|how do i start the shadowmourne quest|is shadowmourne a quest|what is the battle for the undercity quest|quel''delar questline help|what are the best quest chains|do i need icc for shadowmourne');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_profession_quests', 'Profession Quest Lines', 'Dalaran has the Northrend profession dailies: the Grand Master cooking trainers, Katherine Lee for the Alliance and Awilo Lon''gomba for the Horde, give cooking dailies paying Dalaran Cooking Awards; Marcia Chase gives a fishing daily; and Timothy Jones gives a jewelcrafting daily paying Dalaran Jewelcrafter''s Tokens.', 'profession quest,profession quests,profession dailies,cooking daily,cooking dailies,fishing daily,jewelcrafting daily,jc daily,dalaran cooking award,jewelcrafters token', 'quests,professions,lore,recipes', '', '', 'what are the profession dailies|where do i do the cooking daily|where do i do the fishing daily|where is the jewelcrafting daily|who gives the jc daily|who gives the cooking daily in dalaran|who is katherine lee|who is awilo lon''gomba|who is marcia chase|who is timothy jones|what are dalaran cooking awards|what are jewelcrafter''s tokens|what do cooking awards buy|where do i get dalaran jewelcrafting tokens|profession dailies in dalaran|cooking dailies worth it');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_escort_quests', 'Escort and Protection Quests', 'In an escort quest the NPC walks a fixed route and fights beside you; if it dies the quest fails, and you abandon it and take it again once the NPC is back. Party members on the same quest who stay nearby all get credit.', 'escort,escort quest,escort quests,escorting', 'quests,escort,protection,challenging', '', '', 'how do escort quests work|what happens if the escort npc dies|how do i redo a failed escort|i failed my escort quest what now|do party members get credit for escorts|can i do an escort quest in a group|escort quest tips|my escort npc died can i restart|do escort npcs fight|why did my escort quest fail|do i abandon an escort quest|how do i retry an escort');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_group_quests', 'Group and Raid Quests', 'Quests tagged Group in the log suggest a party size because their targets are elites, which show a gold dragon on their portrait. While you''re in a raid group, ordinary quest kills and items don''t count, only quests tagged Raid do, so convert back to a party to finish quests.', 'group quest,group quests,elite quest,raid quest,raid quests,quest in raid,party quest', 'quests,group,raid,coordination', '', '', 'what is a group quest|what does group mean on a quest|how many people for a group quest|why can''t i complete quests in a raid|do quest kills count in a raid group|quests don''t count when in raid|why is my quest not updating in a raid|can i do quests in a raid group|what is a raid quest|do i need to leave raid for quests|why do group quests have elites|how do i finish quests while in raid|how do i convert raid to party for quests');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_repeatable_quests', 'Repeatable and Daily Quests', 'Daily quests can be done once per day and reset at the realm''s daily reset; you can finish up to 25 of them a day. Big Northrend daily hubs are the Argent Tournament, the Sons of Hodir and Wyrmrest Temple, plus the Dalaran cooking and fishing dailies. Some quests, like the raid weekly, reset once a week.', 'daily,dailies,daily quest,daily quests,repeatable,repeatable quest,daily reset,weekly quest,how many dailies', 'quests,repeatable,daily,grinding', '', '', 'what are dailies|how many dailies can i do a day|what is the daily quest limit|when do dailies reset|when is daily reset|what is the 25 daily cap|what are weekly quests|when does the weekly reset|how many daily quests per day|what are the best daily hubs in northrend|can i repeat quests|are there repeatable quests|where do i do dailies in wotlk|how do the dalaran dailies work|how often do dailies reset');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_paladin_mount', 'Paladin Class Mount', 'Paladins earn their mount through class quests. On this realm the Warhorse quest, The Tome of Nobility, needs level 40 and is handed in to Duthorian Rall in Stormwind; blood elf paladins do The Thalassian Warhorse with Knight-Lord Bloodvalor in Silvermoon. The paladin trainer then teaches the Charger at level 40, once you know the Warhorse and have Journeyman Riding.', 'paladin mount,pally mount,warhorse,charger,thalassian warhorse,tome of nobility,duthorian rall', 'quest,class,paladin,mount', '', '', 'how do i get my paladin mount|where do i get the paladin warhorse|what level do pallies get a mount|paladin class mount quest|where does the pally mount quest start|how do i get the charger as a paladin|what level is the paladin charger|who teaches the paladin charger|what is the tome of nobility|where is duthorian rall|do paladins need a quest for a mount|how do blood elf paladins get their mount|what is the thalassian warhorse|where do i get the thalassian charger|do i need riding for the charger|when do paladins get warhorse|pally mount|pally mount quest|paladin mount level|when do pallies get mount|how do i get my pally mount|where is the pally mount trainer|charger quest|paladin horse|what level is the pally warhorse|do pallies get a free mount|pally charger how|paladin epic mount quest|where do i start the pally mount quest|blood elf pally mount quest|paladin mount requirements');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_warlock_mount', 'Warlock Class Mount', 'Warlocks earn their mount through class quests. On this realm the Summon Felsteed quest chain needs level 40 and ends with Strahad Farsan in Ratchet, in the Barrens, who teaches you to summon the Felsteed. The warlock trainer then teaches the Dreadsteed at level 40, once you know the Felsteed and have Journeyman Riding.', 'warlock mount,lock mount,felsteed,dreadsteed,strahad farsan,summon felsteed', 'quest,class,warlock,mount', '', '', 'where do i get the felsteed|what level do locks get a mount|warlock class mount quest|where does the felsteed quest start|how do i get the dreadsteed|what level is the dreadsteed|who teaches the warlock dreadsteed|who is strahad farsan|where is strahad farsan|do warlocks need a quest for a mount|where is ratchet for the felsteed|do i need riding for the dreadsteed|when do warlocks get felsteed|what is the summon felsteed quest|where do i learn the lock mount|lock mount|lock mount quest|warlock mount level|felsteed quest|where do i get my lock mount|lock dreadsteed|dreadsteed quest|how do i get felsteed|when do locks get a mount|warlock epic mount|where do locks get their mount|warlock horse quest|lock mount lvl|where is the felsteed trainer|do locks need riding for felsteed');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_warlock_demons', 'Warlock Demon Summoning Quests', 'A warlock has the imp at level 1. The voidwalker comes from a level 10 quest called The Binding, the succubus from a level 20 one, and the felhunter from a level 30 one. The first two are given by Gakin the Darkbinder in Stormwind, Gan''rul Bloodeye in Orgrimmar or Carendin Halgar in Undercity; blood elves hand in their voidwalker quest to Talionia in Silvermoon. The felhunter quest is Strahad Farsan''s in Ratchet, in the Barrens.', 'voidwalker,succubus,felhunter,the binding,gakin the darkbinder,gakin,carendin halgar,gan''rul bloodeye,talionia,warlock demon quest', 'quest,class,warlock,pets', '', '', 'how do i get a voidwalker|what level do locks get a voidwalker|how do i get the succubus|what level is the succubus|how do i get a felhunter|what level do warlocks get the felhunter|where do i get my warlock demons|what is the binding quest|where is gakin the darkbinder|where is gan''rul bloodeye|where is carendin halgar|where does the felhunter quest start|warlock pet quest voidwalker where|which demon at level 20|do warlocks need quests for demons|where do blood elf warlocks get a voidwalker|what level is the imp for locks');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_shaman_totems', 'Shaman Totem Quests', 'Each shaman totem element has a class quest: Call of Earth at level 4 gives the Stoneskin Totem, Call of Fire at 10 the Searing Totem, Call of Water at 20 the Healing Stream Totem and Call of Air at 30 the air totem. Orcs and trolls start Earth with Canaga Earthcaller in the Valley of Trials and tauren with Seer Ravenfeather in Camp Narache. Fire ends at Kranal Fiss in the Barrens, Water at Islen Waterseer there, and Air with Prate Cloudseer in Thousand Needles.', 'call of earth,call of fire,call of water,call of air,totem quest,totem quests,stoneskin totem,searing totem,healing stream totem,kranal fiss,islen waterseer,prate cloudseer', 'quest,class,shaman,totems', '', '', 'how do i get my first totem|where do shamans get their totems|what level are the shaman totem quests|what is call of earth|what is call of fire|what is call of water|what is call of air|where do i start the earth totem quest|where is kranal fiss|where is islen waterseer|where is prate cloudseer|how do i get the water totem|how do i get the fire totem|how do i get the air totem|what level do shamans get the earth totem|do shamans have to quest for totems|how do i get the searing totem|how do i get stoneskin totem');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('quest_hunter_pet_training', 'Hunter Pet Leveling and Training', 'A hunter''s pet quests start at level 10: Taming the Beast has you use a Taming Rod on a beast near your starting zone and report back, then Training the Beast, or Beast Training for blood elves and draenei, sends you to your hunter trainer in the capital to learn Beast Training, which is how a pet is taught abilities. A pet earns experience when you kill things, never goes above your own level, and this realm triples pet experience. You can tame only beasts at or below your level.', 'taming the beast,training the beast,beast training,taming rod,pet leveling,level my pet,pet experience', 'quest,class,hunter,pets', '', '', 'how do i level my pet|how does hunter pet leveling work|how do i tame my first pet|what is taming the beast|what is the taming rod|where do hunters learn beast training|how do i train my pet abilities|what is training the beast|what level can my pet be|can my pet be higher level than me|how fast does my pet level|how does pet xp work|what level can i tame a beast|can i tame a higher level beast|where do i go after taming the beast|how do i teach my pet new skills|what level do hunters get a pet|how do i get a pet as hunter|hunter pet quest|where do i learn beast training|taming rod|hunter first pet|how to tame|how to teach my pet skills|pet wont level|how fast does pet level|is pet xp boosted|do pets level faster here|what lvl can i tame|how do i train my pet|pet training quest');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_arms_warrior', 'Arms Warrior', 'Arms is the two-handed warrior tree, built around Mortal Strike and the healing debuff it leaves. Overpower punishes a target that dodges and Rend bleeds it, while Sweeping Strikes spreads damage across a pack. Bladestorm is the deep talent: a channelled spin that hits everything nearby and cannot be interrupted by most crowd control.', 'arms warrior,mortal strike,bladestorm,sweeping strikes,overpower,two handed warrior', 'spec,warrior', '', '', 'what does arms warrior do|arms warr guide|how does mortal strike work|what is bladestorm|arms warrior two hander build|what does sweeping strikes do|is arms warrior good for pvp|how do i play arms warrior|what is overpower for arms|arms or fury warrior|arms warrior rend and overpower|arms warrior talents|mortal strike healing debuff|what is the deep talent for arms|arms warr dps worth it');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_fury_warrior', 'Fury Warrior', 'Fury dual-wields and runs on Bloodthirst and Whirlwind, spending rage about as fast as it builds. Titan''s Grip is the tree''s signature: it allows two-handed weapons in both hands at a hit penalty. Death Wish and Rampage push damage higher, the first by taking more of it.', 'fury warrior,bloodthirst,titans grip,death wish,rampage,dual wield warrior', 'spec,warrior', '', '', 'what does fury warrior do|fury warr guide|what is titans grip|how does fury dual wield|what is bloodthirst|fury warrior rotation|what does whirlwind do for fury|what is death wish|what does rampage do|is fury warrior good|fury warr 2h in both hands|fury or arms warrior|how do i play fury warrior|fury warrior rage problems|fury warr talents');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_protection_warrior', 'Protection Warrior', 'Protection is the warrior tanking tree. Shield Slam and Devastate hold threat, and Shockwave stuns everything in a cone ahead of you. Last Stand and Spell Reflection are the survival cooldowns, and Vigilance hands threat back from whoever is pulling too much.', 'protection warrior,prot warrior,warrior tank,shield slam,devastate,shockwave,vigilance,spell reflection', 'spec,warrior', '', '', 'what does prot warrior do|prot warr tanking guide|how do i tank as a warrior|what is shield slam|what does devastate do|what is shockwave|what is last stand|what does spell reflection do|what is vigilance warrior|prot warrior survival cooldowns|how does prot warrior hold threat|is prot warrior a good tank|prot warrior talents|how to play prot warr|what does vigilance do for tank');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_holy_paladin', 'Holy Paladin', 'Holy is the paladin healing tree, built on Holy Light and Flash of Light with Holy Shock as the instant. Beacon of Light defines it: heals landed on one target are duplicated onto the beacon, so healing the tank also heals whoever is beaconed. Sacred Shield and Divine Favor fill out the kit, and it runs on mana like every paladin spec.', 'holy paladin,holy pally,paladin healer,beacon of light,holy shock,holy light,flash of light,sacred shield', 'spec,paladin', '', '', 'what does holy paladin do|holy pally healing guide|how does beacon of light work|what is holy shock|how to heal as a paladin|holy light and flash of light|what does sacred shield do|what is divine favor|is holy pally a good healer|holy pally talents|how do i play holy paladin|what does beacon do|paladin healer spec which|holy pally mana problems|holy pally vs resto druid');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_protection_paladin', 'Protection Paladin', 'Protection is the paladin tanking tree and the best in the game at holding several targets at once. Avenger''s Shield pulls at range, Hammer of the Righteous strikes three targets, and Holy Shield turns blocked hits into damage. Ardent Defender and Righteous Fury are what keep the plate standing.', 'protection paladin,prot paladin,prot pally,paladin tank,avengers shield,hammer of the righteous,holy shield,ardent defender', 'spec,paladin', '', '', 'what does prot paladin do|prot pally tanking guide|how do i tank as a paladin|what is avengers shield|what is hammer of the righteous|what does holy shield do|what is ardent defender|what is righteous fury|is prot pally a good tank|best tank for aoe pulls|prot pally talents|how to play prot pally|prot pally aoe threat|who tanks multiple mobs best|what does righteous fury do');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_retribution_paladin', 'Retribution Paladin', 'Retribution is the paladin melee damage tree. Crusader Strike and Divine Storm are the core, and Divine Storm hits everything around you while healing part of the group. Seal of Command and Repentance come from this tree too.', 'retribution paladin,ret paladin,ret pally,crusader strike,divine storm,seal of command,repentance', 'spec,paladin', '', '', 'what does ret paladin do|ret pally guide|what is crusader strike|what is divine storm|how do i play ret pally|what does seal of command do|what is repentance|is ret pally good|ret pally talents|ret paladin rotation|ret pally dps worth it|which paladin spec for melee damage|what does divine storm heal|ret pally leveling spec|ret or holy pally');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_beast_mastery_hunter', 'Beast Mastery Hunter', 'Beast Mastery pushes the pet as far as it will go: extra pet talent points, exotic pets no other tree can tame, and Bestial Wrath as a burst window. The Beast Within extends that window to the hunter as well. Kill Command and Intimidation come from here, and it is the easiest hunter tree to level alone with.', 'beast mastery,bm hunter,beast mastery hunter,bestial wrath,kill command,the beast within,exotic pet,pet hunter', 'spec,hunter', '', '', 'what does bm hunter do|bm hunter guide|what is bestial wrath|what is the beast within|how do exotic pets work|what is kill command|what does intimidation do|is bm hunter good for leveling|best hunter spec for leveling alone|bm hunter talents|how do i play bm hunter|which hunter tree tames exotic pets|bm hunter pet talent points|bm hunter pvp worth it|bm or survival hunter');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_marksmanship_hunter', 'Marksmanship Hunter', 'Marksmanship is the ranged damage tree, built on Aimed Shot and Chimera Shot. Trueshot Aura raises the group''s attack power, Silencing Shot interrupts casters, and Readiness resets the hunter''s shot cooldowns outright. It leans on the hunter rather than the pet.', 'marksmanship hunter,mm hunter,marksman hunter,aimed shot,chimera shot,silencing shot,trueshot aura,readiness', 'spec,hunter', '', '', 'what does mm hunter do|marksmanship hunter guide|what is aimed shot|what is chimera shot|what is trueshot aura|what does silencing shot do|what does readiness do|how do i play mm hunter|mm hunter talents|marks hunter rotation|is mm hunter good for raids|best hunter spec for dps|mm or bm hunter|mm hunter pvp|what does trueshot aura give the group');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_survival_hunter', 'Survival Hunter', 'Survival is the traps-and-fire tree. Explosive Shot is its core attack and Lock and Load refunds it from traps and periodic damage. Black Arrow and Wyvern Sting come from here, and the tree raises the whole group''s melee critical strike chance.', 'survival hunter,sv hunter,explosive shot,lock and load,black arrow,wyvern sting', 'spec,hunter', '', '', 'what does surv hunter do|survival hunter guide|what is explosive shot|what is lock and load|what is black arrow|what is wyvern sting|how do i play survival hunter|surv hunter talents|is survival hunter good|hunter spec for traps|survival hunter crit buff for group|surv hunter rotation|survival or marksmanship hunter|surv hunter pvp|how does lock and load work for hunter');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_assassination_rogue', 'Assassination Rogue', 'Assassination is the poison and dagger tree, built on Mutilate, which strikes with both weapons at once and requires daggers. Envenom spends combo points as poison damage, Hunger For Blood ramps it up, and Cold Blood guarantees a critical strike. It is at its best on a single target.', 'assassination rogue,mutilate rogue,mutilate,envenom,cold blood,hunger for blood,poison rogue,dagger rogue', 'spec,rogue', '', '', 'what does assassination rogue do|assa rogue guide|what is mutilate|what is envenom|what is hunger for blood|what is cold blood|do i need daggers for mutilate|assassination rogue poisons|how do i play assassination rogue|assa rogue talents|is assassination rogue good|rogue spec for single target dps|assa or combat rogue|assa rogue rotation|what does cold blood do');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_combat_rogue', 'Combat Rogue', 'Combat is the steady damage tree and the one indifferent to which weapons you carry. Sinister Strike builds combo points, Blade Flurry adds a second target, and Adrenaline Rush floods energy. Killing Spree is the deep talent: the rogue teleports between nearby targets, swinging at each.', 'combat rogue,sinister strike,blade flurry,adrenaline rush,killing spree', 'spec,rogue', '', '', 'what does combat rogue do|combat rogue guide|what is blade flurry|what is adrenaline rush|what is killing spree|what is sinister strike|what weapons for combat rogue|how do i play combat rogue|combat rogue talents|is combat rogue good for raids|combat rogue rotation|best rogue spec for leveling|combat or assassination rogue|rogue spec that hits two targets|what does blade flurry do');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_subtlety_rogue', 'Subtlety Rogue', 'Subtlety is the stealth and burst tree and the strongest rogue tree in PvP. Shadowstep closes from behind, Hemorrhage replaces the standard builder, and Preparation resets the escape cooldowns. Shadow Dance is the deep talent: a window where stealth-only abilities work in the open.', 'subtlety rogue,sub rogue,shadow dance,shadowstep,hemorrhage,premeditation,stealth rogue', 'spec,rogue', '', '', 'what does sub rogue do|subtlety rogue guide|what is shadowstep|what is shadow dance|what is preparation rogue|what does hemorrhage do|best rogue spec for pvp|how do i play sub rogue|sub rogue talents|is sub rogue good|sub rogue stealth burst|sub rogue arena|what does preparation reset|sub or combat rogue|subtlety rogue rotation');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_discipline_priest', 'Discipline Priest', 'Discipline heals by preventing damage rather than repairing it: Power Word: Shield absorbs the hit before it lands and Rapture returns mana when the shield breaks. Penance is the tree''s signature, a channelled three-tick heal that can also be aimed at an enemy. Pain Suppression and Power Infusion are the cooldowns that earn it a raid slot.', 'discipline priest,disc priest,penance,power word shield,pain suppression,power infusion,rapture,shield healer', 'spec,priest', '', '', 'what does disc priest do|disc priest guide|what is penance|what is pain suppression|what does power word shield do|what is rapture|what is power infusion|how do i play disc priest|disc priest talents|is disc priest good for raids|how does disc healing work|disc or holy priest|disc priest pvp|disc priest absorbs|can penance hit enemies');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_holy_priest', 'Holy Priest', 'Holy is the priest throughput tree, built for keeping several people up at once. Circle of Healing hits a target''s whole party, Prayer of Mending bounces to whoever takes damage next, and Lightwell is the tree''s much-ignored free heal. Guardian Spirit is the emergency button: it prevents one death outright.', 'holy priest,circle of healing,guardian spirit,prayer of mending,lightwell,priest healer', 'spec,priest', '', '', 'what does holy priest do|holy priest guide|what is circle of healing|what is prayer of mending|what is lightwell|what is guardian spirit|how do i play holy priest|holy priest talents|is holy priest good for raids|best priest spec for group healing|holy priest raid healing|holy or disc priest|what does guardian spirit do|holy priest aoe heals|does anyone use lightwell');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_shadow_priest', 'Shadow Priest', 'Shadow is the priest damage tree and it is played entirely in Shadowform. Shadow Word: Pain, Vampiric Touch and Mind Flay keep damage rolling while Mind Blast fills the gaps. Vampiric Embrace and Vampiric Touch feed health and mana back to the group, which is most of why raids bring one. Dispersion is the escape and mana cooldown.', 'shadow priest,shadowform,mind flay,vampiric touch,vampiric embrace,shadow word pain,mind blast,dispersion', 'spec,priest', '', '', 'what does shadow priest do|spriest guide|what is vampiric touch|what is mind flay|what is vampiric embrace|what is dispersion|how do i play shadow priest|shadow priest talents|is shadow priest good|why do raids want a shadow priest|shadow priest rotation|shadowform dps priest|shadow word pain and mind blast|shadow priest mana for group|shadow priest pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_blood_death_knight', 'Blood Death Knight', 'Blood is the self-healing death knight tree, and in this expansion it is a damage tree that happens to be very hard to kill. Heart Strike is the core strike, Vampiric Blood and Rune Tap keep it standing, and Dancing Rune Weapon summons a copy of the weapon to fight alongside it. It is the usual choice for levelling alone.', 'blood death knight,blood dk,heart strike,vampiric blood,dancing rune weapon,rune tap', 'spec,death knight', '', '', 'what does blood dk do|blood death knight guide|what is heart strike|what is vampiric blood|what is rune tap|what is dancing rune weapon|how do i play blood dk|blood dk talents|is blood dk good|best dk spec for leveling|best dk spec for solo|blood dk tank or dps|blood dk self heal|blood or frost dk|what does dancing rune weapon do');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_frost_death_knight', 'Frost Death Knight', 'Frost is the dual-wield and burst death knight tree. Obliterate and Frost Strike are the core, Howling Blast hits everything around the target, and Killing Machine and Rime make those strikes free or guaranteed to crit. Hungering Cold freezes everything nearby. It also tanks perfectly well.', 'frost death knight,frost dk,obliterate,howling blast,frost strike,killing machine,hungering cold', 'spec,death knight', '', '', 'what does frost dk do|frost death knight guide|what is obliterate|what is frost strike|what is howling blast|what is killing machine|what is hungering cold|how do i play frost dk|frost dk talents|is frost dk good|frost dk dual wield|can frost dk tank|frost dk rime|frost or unholy dk|frost dk burst damage');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_unholy_death_knight', 'Unholy Death Knight', 'Unholy is the disease and pet tree. Scourge Strike scales with the diseases already on the target and Unholy Blight spreads damage around it. Master of Ghouls makes the ghoul a permanent pet rather than a short summon, Summon Gargoyle is the deep cooldown, and Bone Shield keeps the death knight alive while it works.', 'unholy death knight,unholy dk,scourge strike,summon gargoyle,bone shield,unholy blight,permanent ghoul', 'spec,death knight', '', '', 'what does unholy dk do|unholy death knight guide|what is scourge strike|what is summon gargoyle|what is master of ghouls|what is bone shield|what is unholy blight|how do i play unholy dk|unholy dk talents|is unholy dk good|unholy dk ghoul pet|unholy dk diseases|dk spec with a pet|frost or unholy dk|what does gargoyle do');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_elemental_shaman', 'Elemental Shaman', 'Elemental is the caster shaman tree. Lightning Bolt and Chain Lightning are the filler and Lava Burst is the payoff, since it always critically strikes a target burning from Flame Shock. Thunderstorm knocks everything back and returns mana, and Elemental Mastery guarantees a critical strike. Its totems buff the whole group.', 'elemental shaman,ele shaman,lava burst,chain lightning,thunderstorm,elemental mastery,caster shaman', 'spec,shaman', '', '', 'what does ele shaman do|elemental shammy guide|what is lava burst|what is thunderstorm|what is elemental mastery|what is chain lightning|how do i play ele shaman|ele shaman talents|is ele shaman good|ele shaman rotation|flame shock and lava burst|caster shaman spec|ele shaman totems|ele or enhance shaman|ele shaman pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_enhancement_shaman', 'Enhancement Shaman', 'Enhancement is the melee shaman tree, dual-wielding behind Windfury Weapon for extra attacks. Stormstrike and Lava Lash are the strikes, and Maelstrom Weapon turns melee swings into instant Lightning Bolts and Chain Heals. Feral Spirit calls two wolves as a cooldown.', 'enhancement shaman,enh shaman,stormstrike,lava lash,feral spirit,maelstrom weapon,windfury weapon,melee shaman', 'spec,shaman', '', '', 'what does enh shaman do|enhancement shammy guide|what is maelstrom weapon|what is stormstrike|what is feral spirit|what is windfury weapon|what is lava lash|how do i play enhance shaman|enh shaman talents|is enhancement shaman good|enhance shaman rotation|melee shaman spec|enh shaman dual wield|enhance or ele shaman|best shaman spec for leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_restoration_shaman', 'Restoration Shaman', 'Restoration is the shaman healing tree and the strongest party healer of this expansion. Chain Heal bounces between injured group members, Riptide is the instant that strengthens the next Chain Heal, and Earth Shield sits on the tank soaking hits. Mana Tide Totem gives the group its mana back.', 'restoration shaman,resto shaman,chain heal,riptide,earth shield,mana tide totem,earthliving weapon,shaman healer', 'spec,shaman', '', '', 'what does resto shaman do|resto shammy guide|what is chain heal|what is riptide|what is earth shield|what is mana tide totem|how do i play resto shaman|resto shaman talents|is resto shaman good|best party healer in wrath|resto shaman raid healing|shaman healer spec|what does earth shield do|resto shaman vs holy priest|resto shaman pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_arcane_mage', 'Arcane Mage', 'Arcane is the burst and mana-management tree. Arcane Blast hits harder with every stack and costs more mana for it, so the spec is a constant decision about when to dump the stack with Arcane Barrage or Arcane Missiles. Presence of Mind and Arcane Power are the burst cooldowns. It has the highest ceiling and the worst mana problems.', 'arcane mage,arcane blast,arcane barrage,arcane missiles,arcane power,presence of mind,missile barrage', 'spec,mage', '', '', 'what does arcane mage do|arcane mage guide|what is arcane blast|what is arcane barrage|what is presence of mind|what is arcane power|how do i play arcane mage|arcane mage talents|is arcane mage good|arcane mage mana problems|arcane mage rotation|arcane missiles when to use|arcane or fire mage|arcane mage burst|mage spec with highest ceiling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_fire_mage', 'Fire Mage', 'Fire is built on critical strikes feeding themselves: Hot Streak turns two crits in a row into an instant Pyroblast. Fireball and Scorch are the fillers, Living Bomb ticks and then explodes, and Combustion is the burst cooldown. Without critical strike rating the whole tree stalls.', 'fire mage,hot streak,living bomb,pyroblast,combustion,fireball', 'spec,mage', '', '', 'what does fire mage do|fire mage guide|what is hot streak|what is living bomb|what is combustion|what does pyroblast do|how do i play fire mage|fire mage talents|is fire mage good|fire mage rotation|fire mage crit rating|fireball and scorch rotation|fire or frost mage|fire mage pvp|why does fire mage need crit');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_frost_mage', 'Frost Mage', 'Frost is the survivable mage tree and the usual choice for levelling alone. Frostbolt slows whatever it hits and Frost Nova roots, while Shatter turns frozen targets into guaranteed critical strikes for Ice Lance. Summon Water Elemental gives Frost a pet, and Deep Freeze is a stun that instead deals heavy damage to anything immune to stuns.', 'frost mage,frostbolt,ice lance,deep freeze,icy veins,water elemental,fingers of frost,frost nova', 'spec,mage', '', '', 'what does frost mage do|frost mage guide|what is shatter|what is deep freeze|what is frost nova|what is ice lance|how do i play frost mage|frost mage talents|is frost mage good|best mage spec for leveling|best mage spec for solo|frost mage water elemental|frost mage rotation|frost or fire mage|frost mage pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_affliction_warlock', 'Affliction Warlock', 'Affliction is the damage-over-time tree. Corruption, Curse of Agony and Unstable Affliction tick on the target while Haunt raises all of that damage and returns the healing to the warlock. Drain Soul hits far harder on a target about to die. Strong on one target and unforgiving if the timers are left to lapse.', 'affliction warlock,affli warlock,unstable affliction,haunt,curse of agony,drain soul,dot warlock,affli lock,aff lock', 'spec,warlock', '', '', 'what does affliction lock do|aff lock guide|what is haunt|what is unstable affliction|what is drain soul|how do dots work for warlock|what is curse of agony|how do i play affliction warlock|affliction warlock talents|is aff lock good|affliction warlock rotation|warlock spec for dots|aff lock corruption|aff or destro lock|affliction lock pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_demonology_warlock', 'Demonology Warlock', 'Demonology is the pet tree. The Felguard is its own summon, Demonic Empowerment buffs whatever demon is out, and Soul Link splits damage between warlock and pet. Metamorphosis is the deep talent: the warlock becomes a demon with its own abilities. Demonic Pact hands the raid spell power off the pet''s critical strikes.', 'demonology warlock,demo warlock,felguard,metamorphosis,demonic empowerment,soul link,demonic pact,pet warlock,demo lock', 'spec,warlock', '', '', 'what does demo lock do|demonology warlock guide|what is metamorphosis|what is the felguard|what is demonic pact|what is demonic empowerment|what is soul link|how do i play demo lock|demonology warlock talents|is demo lock good|warlock pet spec|demo lock felguard leveling|demo or destro lock|demo lock pvp|what does metamorphosis do');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_destruction_warlock', 'Destruction Warlock', 'Destruction is the direct damage tree, built on Immolate and Incinerate with Conflagrate consuming the Immolate for a burst. Chaos Bolt is the deep talent: it cannot be resisted and ignores absorption shields. Backdraft speeds up casting afterwards and Shadowburn is the finisher.', 'destruction warlock,destro warlock,chaos bolt,conflagrate,incinerate,immolate,shadowburn,backdraft,destro lock', 'spec,warlock', '', '', 'what does destro lock do|destruction warlock guide|what is chaos bolt|what is conflagrate|what is backdraft|what is shadowburn|what does immolate do for destro|how do i play destro lock|destro lock talents|is destro lock good|destro lock rotation|warlock spec for direct damage|incinerate and immolate|destro or aff lock|destro lock pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_balance_druid', 'Balance Druid', 'Balance is the caster druid tree, played in Moonkin Form, which is why everyone calls it boomkin. Eclipse alternates a bonus between Starfire and Wrath, so the spec swings between arcane and nature damage. Moonfire and Insect Swarm keep damage ticking, Starfall rains on everything nearby, and Typhoon knocks targets back.', 'balance druid,boomkin,moonkin,moonkin form,starfall,eclipse,starfire,insect swarm,typhoon,caster druid', 'spec,druid', '', '', 'what does balance druid do|boomkin guide|what is moonkin form|what is eclipse|what is starfall|what is typhoon|how do i play boomkin|balance druid talents|is boomkin good|balance druid rotation|moonfire and insect swarm|starfire and wrath eclipse|druid caster spec|boomy pvp|why is it called boomkin');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_feral_druid', 'Feral Druid', 'Feral covers both melee roles: cat form for damage, dire bear form for tanking. As a cat it builds combo points with Rake and Shred and spends them on Rip and Savage Roar; as a bear it holds threat with Maul and Mangle. Mangle is the tree''s shared signature and Berserk is its cooldown in either form.', 'feral druid,cat form,bear form,dire bear form,mangle,shred,savage roar,rake,kitty druid,feral tank', 'spec,druid', '', '', 'what does feral druid do|feral druid guide|how do i tank as a druid|what is mangle|what is savage roar|what is berserk|cat or bear feral|how do i play feral|feral druid talents|is feral druid good|feral cat rotation|rake shred and rip|druid bear tank spec|feral dps or tank|feral druid leveling');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('spec_restoration_druid', 'Restoration Druid', 'Restoration heals with rolling periodic spells rather than large casts: Rejuvenation and Lifebloom tick away while Nourish and Regrowth cover the gaps. Wild Growth is the tree''s raid heal and Swiftmend consumes a Rejuvenation or Regrowth for an instant one. Tree of Life is the form the spec heals in.', 'restoration druid,resto druid,tree of life,wild growth,swiftmend,rejuvenation,lifebloom,nourish,druid healer', 'spec,druid', '', '', 'what does resto druid do|resto druid guide|what is lifebloom|what is wild growth|what is swiftmend|what is tree of life|how do i play resto druid|resto druid talents|is resto druid good|resto druid hots|rejuvenation and regrowth|nourish when to use|druid healer spec|resto druid raid healing|resto druid pvp');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_hallows_end', 'Hallow''s End', 'Hallow''s End runs each year from October 18 to October 31, decorating capital cities with pumpkins and candy buckets in inns for trick-or-treating. Its centerpiece is the Headless Horseman, who appears in Scarlet Monastery''s graveyard and can be queued for through the Dungeon Finder. He drops one of three epic rings (Ring of Ghoulish Glee, The Horseman''s Seal or Wicked Witch''s Band) and Weighted Jack-o''-Lanterns, and the run rewards a Loot-Filled Pumpkin that can hold the Magic Broom, the Flying Broom or, rarely, The Horseman''s Reins mount.', 'hallow''s end,headless horseman,magic broom,trick or treat,candy bucket,scarlet monastery', 'event,holiday,seasonal', '', '', 'when is hallow''s end|when does hallows end start|how do i get the headless horseman|where is the headless horseman|how do i get the magic broom|where are the candy buckets|how do i trick or treat|is the horseman in the dungeon finder|what do i get from the headless horseman|how do i get a halloween costume|what is the halloween event|how do i turn into a ghost or pirate|what are the costume wands|how do i get the broom mount|where do i summon the headless horseman|what does the headless horseman drop|what loot does the horseman give|what rings drop from the headless horseman|how do i get the horseman''s reins|what is in the loot filled pumpkin|what is a loot-filled pumpkin|where does the magic broom come from|how do i get the flying broom|does the horseman drop a mount|what is the ring of ghoulish glee|what is the horseman''s seal|what is the wicked witch''s band');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_winter_veil', 'Feast of Winter Veil', 'The Feast of Winter Veil is WoW''s Christmas-themed holiday, running from December 15 through January 2. Players collect a daily gift from under the tree beside Greatfather Winter in Ironforge or Orgrimmar, buy toys and treats from the traveling Smokywood Pastures vendor, and can start snowball fights or use a Handful of Snowflakes to turn friends into reindeer. There is no dedicated Winter Veil mount, but achievements like Merrymaker (completing every holiday task) award a title, and the classic ''Metzen the Reindeer'' summon is a well-known joke item tied to the season.', 'feast of winter veil,winter veil,greatfather winter,smokywood pastures,reindeer,snowball', 'event,holiday,seasonal', '', '', 'when is winter veil|when does feast of winter veil start|where is greatfather winter|how do i get winter veil gifts|what is the christmas event|where is smokywood pastures|how do i turn into a reindeer|how do i get the winter veil gift under the tree|is there a winter veil mount|what is metzen the reindeer|what is merrymaker|how do i start a snowball fight|how long does winter veil last|what do i get from winter veil|what is the handful of snowflakes');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_brewfest', 'Brewfest', 'Brewfest runs from September 20 to October 4 at fairgrounds outside Ironforge and Orgrimmar, where players ram-race, sample brews from the Brewfest quartermaster for tokens, and fight the drunken boss Coren Direbrew inside Blackrock Depths (also queueable through the Dungeon Finder). Defeating Direbrew drops a loot bag with a chance at the Great Brewfest Kodo or the Swift Brewfest Ram mount, making his fight the event''s main draw for collectors. Brewfest carries no reputation of its own; the daily quests and the ram race pay Brewfest Prize Tokens, spent with a Token Redeemer on holiday-only gear, steins, and trinkets.', 'brewfest,coren direbrew,brewfest kodo,brewfest ram,ram racing,blackrock depths', 'event,holiday,seasonal', '', '', 'when is brewfest|when does brewfest start|how do i get the brewfest kodo|how do i get the brewfest ram|who is coren direbrew|how do i kill coren direbrew|where do i fight coren direbrew|how does ram racing work|what are brewfest prize tokens|where is the brewfest fairground|can i queue for direbrew in dungeon finder|what do i get from brewfest|does brewfest have a reputation|what is the token redeemer|how do i get a stein');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_midsummer_fire_festival', 'Midsummer Fire Festival', 'The Midsummer Fire Festival burns from June 21 to July 4 around bonfires placed in most major cities and zones. Players tend their own faction''s flame, try to douse the rival faction''s fire and relight their own from it, and dance around the Ribbon Pole for a festive buff; visiting every bonfire and completing the fire-themed dailies works toward the Fire Festival meta-achievement and title. Rewards are mostly cosmetic -- torch-tossing toys and a Brazier of Dancing Flames trinket -- with no dedicated mount tied to the holiday.', 'midsummer fire festival,bonfire,ribbon pole,torch,brazier of dancing flames', 'event,holiday,seasonal', '', '', 'when is midsummer|when does fire festival start|what is the midsummer fire festival|what are the bonfires for|what is the ribbon pole|how do i douse the enemy bonfire|how do i get the brazier of dancing flames|is there a midsummer mount|how long does midsummer last|what are the rewards for midsummer|how do i get the fire festival title|what do i do at the bonfire|how do i get the midsummer meta achievement|what are the fire festival dailies|where do i dance for the ribbon pole buff');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_lunar_festival', 'Lunar Festival', 'Lunar Festival runs from February 1 to February 14 and centers on visiting Elders scattered across nearly every zone on both continents, each granting the Elders'' Blessing buff and a bit of Lunar Festival lore. Players also toss coins into the fountain at Moonglade for a random small reward, and can take on Omen, an enormous spectral beast that spawns as a group-killable target in Moonglade for the duration of the event. Collecting blessings from enough Elders unlocks the elder title and a fireworks-launching trinket.', 'lunar festival,elders,elders'' blessing,moonglade,omen,coin toss', 'event,holiday,seasonal', '', '', 'when is lunar festival|when does the lunar festival start|what are the elders for|how do i get the elders blessing|where do i find lunar festival elders|what is omen|where is omen|how do i kill omen|what is the coin toss in moonglade|how do i get the lunar festival title|what does the lunar festival trinket do|what is the fireworks trinket|how long does the lunar festival last|what do i get from lunar festival');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_love_is_in_the_air', 'Love is in the Air', 'Love is in the Air runs from February 10 to February 23; Wrath of the Lich King''s patch 3.3 expanded it from a minor vanilla holiday into a full event centered on a farcical boss fight against Apothecary Hummel and his two partners in Shadowfang Keep, queued through the Dungeon Finder. Defeating Hummel drops a loot bag with a small chance at the Big Love Rocket, one of the game''s most sought-after rare mounts. Players also collect Lovely Charms from monsters everywhere to trade for perfume, cologne, and the companion pet Peddlefeet, and can propose to friends with a Silver Bell or invite them to disco-dance atop a caged Love Fool.', 'love is in the air,apothecary hummel,big love rocket,lovely charms,peddlefeet', 'event,holiday,seasonal', '', '', 'when is love is in the air|how do i get the big love rocket|who is apothecary hummel|where is hummel|where do i fight hummel|can i queue for hummel in dungeon finder|what are lovely charms|how do i get peddlefeet|what is the valentines event|how do i get perfume or cologne|how do i propose with a silver bell|what is the love fool|how long does love is in the air last|what drops from apothecary hummel|is the big love rocket rare');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_childrens_week', 'Children''s Week', 'Children''s Week runs from April 30 to May 6. Players adopt a war orphan from the Orphan Matron in their faction''s capital and escort it on a tour of iconic locations, including a Northrend leg added for Wrath of the Lich King that has players take their orphan through Icecrown or Borean Tundra. It is also when the School of Hard Knocks achievement is available, which sends players into the battlegrounds with the orphan following them to capture a flag, assault a tower, and the like -- a notoriously unpopular week for battleground regulars. Completing the full questline awards a faction-specific orphan companion pet.', 'children''s week,orphan,orphan matron,school of hard knocks,companion pet', 'event,holiday,seasonal', '', '', 'when is children''s week|where is the orphan matron|how do i adopt an orphan|what is the school of hard knocks|how do i get the orphan pet|how do i do children''s week in northrend|is children''s week in bgs annoying|what do i get from children''s week|how long does children''s week last|what does the war orphan do|how do i do the school of hard knocks achievement|where do i take the orphan in icecrown|where do i take the orphan in borean tundra|how do i get a companion pet from children''s week|what is the orphan questline');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_pilgrims_bounty', 'Pilgrim''s Bounty', 'Pilgrim''s Bounty is WoW''s Thanksgiving-themed holiday, added with Wrath of the Lich King and running from November 21 to November 27 at a feast table set up outside every major city. Players cook and serve dishes like Cranberry Chutney, Pumpkin Pie, and Slow-Roasted Turkey to seated guests of both factions for reputation and Pilgrim''s Bounty Buckets, and can earn the Pilgrim''s Paunch food-coma buff for overeating. The Turkinator achievement, earned by killing wild turkeys that spawn worldwide during the event, rounds out the holiday''s meta-achievement.', 'pilgrim''s bounty,turkinator,pilgrim''s paunch,cranberry chutney,thanksgiving', 'event,holiday,seasonal,wotlk', '', '', 'when is pilgrim''s bounty|when does thanksgiving start in wow|what is pilgrim''s bounty|how do i get the turkinator|what is the pilgrim''s paunch|how do i get cranberry chutney|how do i serve the feast|where is the pilgrim''s bounty feast table|how do i kill wild turkeys|what is the food coma buff|how long does pilgrim''s bounty last|how do i get pilgrim''s bounty buckets|what is the turkey achievement|how do i cook for pilgrim''s bounty|what is the thanksgiving event');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_darkmoon_faire', 'Darkmoon Faire', 'The Darkmoon Faire is a travelling carnival with games, vendors and the fortune teller Sayge. It sets up for about a week in Elwynn Forest, Mulgore or Terokkar Forest, and each of those three places gets it once every three months. Silas Darkmoon is there, Selina Dourman gives information, Gelvas Grimegate redeems Darkmoon Faire Prize Tickets, and Lhara and Professor Thaddeus Paleo sell exotic goods and cards.', 'darkmoon faire,darkmoon,dmf,sayge,silas darkmoon,gelvas grimegate,darkmoon faire prize ticket,darkmoon prize ticket,prize tickets', 'event,darkmoon,faire', '', '', 'where is the darkmoon faire|when is the darkmoon faire|when does dmf start|is the darkmoon faire up|where is dmf right now|how often does the darkmoon faire come|how long does the darkmoon faire last|who is sayge|what do prize tickets do|where do i turn in darkmoon prize tickets|who is gelvas grimegate|is the darkmoon faire in elwynn|is the darkmoon faire in mulgore|is dmf in terokkar|what can i do at the darkmoon faire|who is silas darkmoon');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('event_argent_tournament', 'Argent Tournament', 'The Argent Tournament is the Argent Crusade''s jousting hub in Icecrown, with daily quests from level 77. Dailies pay Champion''s Seals, which each faction''s quartermaster there takes: 100 seals buy the city''s racial mount (Stormwind Steed, Ironforge Ram, Gnomeregan Mechanostrider, Exodar Elekk, Darnassian Nightsaber, Orgrimmar Wolf, Thunder Bluff Kodo, Silvermoon Hawkstrider, Darkspear Raptor or Forsaken Warhorse) and 150 buy the Argent Hippogryph mount.', 'argent tournament,champions seal,champion''s seal,champions seals,argent hippogryph,tournament mount,mariel trueheart', 'event,icecrown,mounts,reputation', '', '', 'what is the argent tournament|what level for the argent tournament|how do i get champion''s seals|what are champion''s seals for|how do i get the argent hippogryph|how many seals for the argent hippogryph|how do i get the stormwind steed|how do i get the orgrimmar wolf|what mounts can i buy at the argent tournament|how many champions seals for a mount|who sells the tournament mounts|who is justicar mariel trueheart|what are the argent tournament dailies|what is the argent tournament for|where do i buy the darkspear raptor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_elwynn_forest', 'Elwynn Forest', 'Elwynn Forest is the level 1-10 starting zone for humans, just outside Stormwind City. New characters begin at Northshire Abbey, then move to Goldshire, the main town, with its Lion''s Pride Inn. Common enemies are wolves, kobolds in the mines and Defias bandits.', 'elwynn,elwynn forest,goldshire,northshire,northshire abbey,northshire valley,lions pride inn', 'zone,starting_area,human,leveling', '', '', 'where do humans start|what level is elwynn forest|what is the human starting zone|where is northshire abbey|where do i go after northshire|where is goldshire|what level is elwynn|where is the lion''s pride inn|elwynn forest mobs|what do i kill in elwynn|how do i get to elwynn from stormwind|is elwynn the human newbie zone|what are the kobolds in elwynn mines|where is the human starter area');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_durotar', 'Durotar', 'Durotar is the level 1-10 starting zone for orcs and trolls, outside Orgrimmar. New characters begin in the Valley of Trials, then quest from Razor Hill and Sen''jin Village near the Echo Isles. Common enemies are boars, scorpids, Razormane quilboar and Burning Blade cultists.', 'durotar,razor hill,valley of trials,sen jin village,echo isles', 'zone,starting_area,horde,leveling', '', '', 'where do orcs start|what level is durotar|where is the valley of trials|what is the troll starting zone|where is razor hill|how do i get to sen''jin village|where do trolls start|where do i go after valley of trials|what do i kill in durotar|durotar quests what level|is durotar the orc newbie zone|where are the echo isles|what are razormane|where is durotar from orgrimmar');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_teldrassil', 'Teldrassil', 'Teldrassil is the level 1-10 starting zone for night elves, on the giant tree that holds Darnassus. New characters begin in Shadowglen beneath Aldrassil, then quest from Dolanaar. Common enemies are nightsabers, spiders and corrupted furbolgs, and the boat at Rut''theran Village goes to Darkshore.', 'teldrassil,shadowglen,dolanaar,aldrassil', 'zone,starting_area,alliance,night_elf,leveling', '', '', 'where do night elves start|what level is teldrassil|where is shadowglen|what is the nelf starting zone|where is dolanaar|how do i leave teldrassil|where is the boat to darkshore|where is rut''theran village|where do i go after shadowglen|what mobs are in teldrassil|what is the giant tree zone|tel''drassil level range|where is aldrassil|how do i get to darkshore from teldrassil');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_mulgore', 'Mulgore', 'Mulgore is the level 1-10 starting zone for tauren, below Thunder Bluff. New characters begin at Camp Narache on Red Cloud Mesa, then quest from Bloodhoof Village. Common enemies are plainstriders, prairie wolves, Palemane gnolls, Bristleback quilboar and Venture Company miners.', 'mulgore,bloodhoof village,camp narache,red cloud mesa', 'zone,starting_area,horde,tauren,leveling', '', '', 'where do tauren start|what level is mulgore|where is camp narache|where is bloodhoof village|what is the tauren starting zone|where is red cloud mesa|what do i kill in mulgore|where do i go after camp narache|what are palemane gnolls|mulgore quest level|how do i get to mulgore|where is mulgore relative to thunder bluff|what are venture company miners in mulgore');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_dun_morogh', 'Dun Morogh', 'Dun Morogh is the level 1-10 starting zone for dwarves and gnomes, around Ironforge. New characters begin at Anvilmar in Coldridge Valley, then quest from Kharanos and its Thunderbrew Distillery inn. Common enemies are Rockjaw troggs, Frostmane trolls, boars and wolves.', 'dun morogh,kharanos,coldridge valley,anvilmar,thunderbrew distillery', 'zone,starting_area,alliance,dwarf,gnome,leveling', '', '', 'where do dwarves start|where do gnomes start|what level is dun morogh|where is coldridge valley|where is anvilmar|where is kharanos|what is the dwarf starting zone|where is thunderbrew distillery|what do i kill in dun morogh|what are rockjaw troggs|where do i go after coldridge|dun morogh level range|gnome starting zone where|where is dun morogh from ironforge');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_tirisfal_glades', 'Tirisfal Glades', 'Tirisfal Glades is the level 1-10 starting zone for the undead, above the Undercity. New characters rise in Deathknell, then quest from the town of Brill. Common enemies are mindless zombies, Scourge, and the Scarlet Crusade, whose monastery sits in the zone''s north.', 'tirisfal,tirisfal glades,deathknell,brill', 'zone,starting_area,horde,undead,leveling', '', '', 'where do undead start|what level is tirisfal glades|where is deathknell|where is brill|what is the forsaken starting zone|where is the scarlet monastery in tirisfal|what do i kill in tirisfal|where do i go after deathknell|tirisfal level range|where is tirisfal relative to undercity|what are the mindless zombies|how do i get to tirisfal|where do ud start');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_azuremyst_isle', 'Azuremyst Isle', 'Azuremyst Isle is the level 1-10 starting zone for draenei, beside the Exodar. New characters begin in Ammen Vale by the Crash Site, then quest from Azure Watch. Common enemies are owlkin, Bristlelimb furbolgs and crash-mutated wildlife; the next zone is Bloodmyst Isle.', 'azuremyst,azuremyst isle,ammen vale,azure watch,crash site', 'zone,starting_area,alliance,draenei,leveling', '', '', 'where do draenei start|what level is azuremyst isle|where is ammen vale|where is azure watch|what is the draenei starting zone|where is the crash site|what do i kill in azuremyst|where do i go after azuremyst|what zone is after azuremyst|azuremyst level range|where is azuremyst relative to the exodar|what are owlkin|where do i go after ammen vale');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_eversong_woods', 'Eversong Woods', 'Eversong Woods is the level 1-10 starting zone for blood elves, outside Silvermoon City. New characters begin on Sunstrider Isle, then quest from Falconwing Square and Fairbreeze Village. Common enemies are mana wyrms, arcane wraiths and Wretched elves; the next zone is the Ghostlands.', 'eversong,eversong woods,sunstrider isle,falconwing square,fairbreeze village', 'zone,starting_area,horde,blood_elf,leveling', '', '', 'where do blood elves start|what level is eversong woods|where is sunstrider isle|where is falconwing square|what is the blood elf starting zone|where is fairbreeze village|what do i kill in eversong|where do i go after sunstrider isle|what zone is after eversong|eversong level range|what are mana wyrms|where is eversong from silvermoon|where do belfs start|how do i get to ghostlands from eversong');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_borean_tundra', 'Borean Tundra', 'Borean Tundra is a level 68-72 Northrend zone. Alliance arrive by boat at Valiance Keep and Horde by zeppelin at Warsong Hold. Its quests fight the Scourge, nerubians and the blue dragonflight, whose Nexus stands on Coldarra in the zone''s west.', 'borean,borean tundra,valiance keep,warsong hold,coldarra,riplash,amber ledge', 'zone,northrend,leveling,wrath,contested', '', '', 'what level is borean tundra|how do i get to borean tundra as alliance|how do i get to borean tundra as horde|where is valiance keep|where is warsong hold|what is the first zone in northrend|where is the nexus in borean tundra|what level do i need for northrend|where do i start questing in northrend|borean tundra or howling fjord|what is coldarra|how do i get to northrend|what zone should i go to in northrend first');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_howling_fjord', 'Howling Fjord', 'Howling Fjord is a level 68-72 Northrend zone. Alliance arrive by boat at Valgarde and Horde by zeppelin at Vengeance Landing. Its quests fight the vrykul, whose stronghold Utgarde Keep is the zone''s dungeon, and the Forsaken''s plague works at New Agamand.', 'howling fjord,valgarde,vengeance landing,camp winterhoof,new agamand,westguard keep', 'zone,northrend,leveling,wrath,contested', '', '', 'what level is howling fjord|how do i get to howling fjord as alliance|how do i get to howling fjord as horde|where is valgarde|where is vengeance landing|where is utgarde keep|where is new agamand|borean tundra or howling fjord|what is the first zone in northrend|hfjord or borean which first|how do i get to northrend|where do i start in northrend|who do i fight in howling fjord');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_westfall', 'Westfall', 'Westfall is a level 10 to 20 Alliance zone of failing farmland west of Elwynn Forest. The Defias Brotherhood and their harvest golems have overrun the farms, and the People''s Militia works out of Sentinel Hill. It holds the entrance to the Deadmines and the long-running Defias questline, and Alliance players usually quest here right after Elwynn.', 'westfall,sentinel hill,defias brotherhood,harvest golem,peoples militia,deadmines entrance,moonbrook', 'zone,alliance,eastern_kingdoms,leveling', '', '', 'what level is westfall|where is westfall|where do i go after elwynn forest|where is sentinel hill|where is the deadmines entrance|what is the defias questline|where do alliance quest after elwynn|who are the harvest golems|westfall level range|how do i get to westfall from stormwind|where is the people''s militia|is westfall alliance or horde|where to level 10 to 20 alliance');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_loch_modan', 'Loch Modan', 'Loch Modan is a level 10 to 20 dwarven zone east of Dun Morogh, built around a great lake and the Stonewrought Dam. Thelsamar is the quest hub. Troggs, kobolds, and the Dark Iron dwarves press in from the hills, and the Explorers'' League digs at the Farstrider Lodge and Ironband''s excavation site.', 'loch modan,thelsamar,stonewrought dam,the loch,ironbands excavation,farstrider lodge', 'zone,alliance,eastern_kingdoms,leveling', '', '', 'what level is loch modan|where is loch modan|where is thelsamar|where is stonewrought dam|how do i get to loch modan from ironforge|where do i go after dun morogh|what are the dark iron dwarves doing in loch modan|where is farstrider lodge|loch modan quest hub|where do dwarves quest after dun morogh|loch modan level range|where is ironband''s excavation site|what zone is east of dun morogh');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_silverpine_forest', 'Silverpine Forest', 'Silverpine Forest is a level 10 to 20 Horde zone south of Tirisfal Glades, dark and worgen-haunted. The Sepulcher is the Forsaken quest hub, and Shadowfang Keep sits at its southern edge above Pyrewood Village. Dalaran''s old magical dome once stood here, and the Dalaran mages still hold ruins in the east.', 'silverpine forest,silverpine,the sepulcher,shadowfang keep entrance,pyrewood village,ambermill', 'zone,horde,eastern_kingdoms,leveling', '', '', 'what level is silverpine forest|where is silverpine|where is the sepulcher|where is shadowfang keep|where is pyrewood village|where do horde go after tirisfal|where do undead quest after tirisfal glades|silverpine level range|how do i get to silverpine from undercity|what is the worgen zone for horde|where are the dalaran mages in silverpine|where to level 10 to 20 as forsaken|who lives at the sepulcher');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_ghostlands', 'Ghostlands', 'Ghostlands is a level 10 to 20 blood elf zone south of Eversong Woods, scarred by the Scourge''s march on Quel''Thalas. Tranquillien is the quest hub, and the Dead Scar cuts through the middle of the zone. It leads on to Zul''Aman and connects Silvermoon''s territory to the rest of the Eastern Kingdoms.', 'ghostlands,tranquillien,dead scar,quelthalas,zulaman entrance', 'zone,horde,eastern_kingdoms,leveling', '', '', 'what level is ghostlands|where is ghostlands|where is tranquillien|where do blood elves go after eversong|what is the dead scar|how do i get to zul''aman|what zone comes after eversong woods|ghostlands level range|how do i get from silvermoon to ghostlands|where do belfs quest after eversong|ghostlands quest hub|where is zul aman entrance|what level is the ghostlands for belf');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_redridge_mountains', 'Redridge Mountains', 'Redridge Mountains is a level 15 to 25 Alliance zone east of Elwynn Forest, centered on Lakeshire and its broken bridge. Blackrock orcs push down from Render''s Camp in the north and gnolls hold the southern hills. It borders Duskwood to the south and the Burning Steppes far to the north.', 'redridge mountains,redridge,lakeshire,blackrock orcs,renders camp,lake everstill,stonewatch', 'zone,alliance,eastern_kingdoms,leveling', '', '', 'what level is redridge|where is redridge mountains|where is lakeshire|where is the broken bridge|where is render''s camp|how do i get to redridge from elwynn|what zone is south of redridge|what zone is north of redridge|redridge level range|where do i go after redridge|what are the blackrock orcs doing in redridge|where is redridge relative to burning steppes|where do alliance quest at level 15 to 25');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_duskwood', 'Duskwood', 'Duskwood is a level 18 to 30 zone of permanent night south of Elwynn Forest, with Darkshire as its quest hub. Worgen, undead, and spiders roam the roads, and the Night Watch patrols nervously. It holds the Stalvan Mistmantle and Mor''Ladim questlines, Raven Hill Cemetery, and the entrance to Deadwind Pass in the east.', 'duskwood,darkshire,night watch,raven hill,raven hill cemetery,morladim,stalvan mistmantle,twilight grove', 'zone,alliance,eastern_kingdoms,leveling', '', '', 'what level is duskwood|where is duskwood|where is darkshire|why is duskwood always night|where is raven hill cemetery|stalvan mistmantle quest|how do i get to duskwood from elwynn|what is mor''ladim|duskwood level range|where is deadwind pass entrance|what zone is south of elwynn|who is the night watch|what mobs are in duskwood|where do i quest at level 18 to 30');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_hillsbrad_foothills', 'Hillsbrad Foothills', 'Hillsbrad Foothills is a level 20 to 30 contested zone below Alterac, famous for open world PvP between Tarren Mill and Southshore. The Forsaken hold Tarren Hill in the north and the Alliance hold Southshore on the coast. Durnholde Keep and the Syndicate occupy the eastern hills.', 'hillsbrad foothills,hillsbrad,tarren mill,southshore,durnholde keep,azurelode mine', 'zone,contested,eastern_kingdoms,leveling,pvp', '', '', 'what level is hillsbrad|where is hillsbrad foothills|where is tarren mill|where is southshore|how do i get to southshore|how do i get to tarren mill|where is durnholde keep|is hillsbrad pvp|tarren mill vs southshore pvp|hillsbrad level range|where is hillsbrad relative to alterac|who are the syndicate|where do i level 20 to 30');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_wetlands', 'Wetlands', 'Wetlands is a level 20 to 30 Alliance-leaning zone of marsh and rain north of Dun Morogh, with Menethil Harbor as its port and quest hub. Raptors, murlocs, and crocolisks make the roads dangerous for the level range. Boats from Menethil run to Theramore in Kalimdor and to Howling Fjord in Northrend.', 'wetlands,menethil harbor,dun modr,grim batol,boat to theramore', 'zone,alliance,eastern_kingdoms,leveling', '', '', 'what level is wetlands|where is wetlands|where is menethil harbor|how do i get to theramore|how do i get to howling fjord from wetlands|where is the boat to theramore|where is the boat to northrend as alliance|wetlands level range|what zone is north of dun morogh|how do i get to kalimdor from menethil|what mobs are in the wetlands|where do i level 20 to 30 as alliance|where is the menethil boat');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_arathi_highlands', 'Arathi Highlands', 'Arathi Highlands is a level 30 to 40 contested zone of open grassland, with Refuge Pointe for the Alliance and Hammerfall for the Horde. Stromgarde Keep lies ruined in the southwest, contested by the Syndicate and Boulderfist ogres. The Arathi Basin battleground takes its name and setting from this zone.', 'arathi highlands,arathi,refuge pointe,hammerfall,stromgarde keep,boulderfist ogres', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is arathi highlands|where is arathi highlands|where is refuge pointe|where is hammerfall|where is stromgarde keep|what zone is arathi basin named after|arathi highlands level range|where is arathi relative to hillsbrad|who are the boulderfist ogres|where do i quest at 30 to 40|is arathi highlands pvp|who holds stromgarde|where is the horde base in arathi');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_alterac_mountains', 'Alterac Mountains', 'Alterac Mountains is a level 30 to 40 contested snow zone between Hillsbrad and the Hinterlands. The ruins of Alterac city are held by the Syndicate, and yetis and ogres fill the valleys. It is thinly quested compared to its neighbours, and its main draw is the entrance to Alterac Valley in the north.', 'alterac mountains,alterac,ruins of alterac,alterac valley entrance,dalaran crater', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is alterac mountains|where is alterac valley entrance|how do i get to alterac valley|where is the av entrance|where is alterac mountains|is alterac worth questing|what zone is between hillsbrad and the hinterlands|who holds alterac city|where are the yetis near alterac|alterac mountains level range|where do i enter av|why dont people quest in alterac');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_stranglethorn_vale', 'Stranglethorn Vale', 'Stranglethorn Vale is a level 30 to 45 contested jungle at the south end of the Eastern Kingdoms, notorious for world PvP along its single road. Booty Bay in the far south is a neutral goblin port with an auction house. Grom''gol Base Camp serves the Horde, Rebel Camp the Alliance, and Zul''Gurub sits in the eastern jungle. Alliance walk south from Duskwood; Horde take the zeppelin from Orgrimmar or Undercity.', 'stranglethorn vale,stranglethorn,booty bay,gromgol base camp,rebel camp,nesingwary,zulgurub entrance,bloodsail buccaneers,stv', 'zone,contested,eastern_kingdoms,leveling,pvp', '', '', 'what level is stranglethorn vale|where is stv|where is booty bay|how do i get to stv as horde|how do i get to stv as alliance|where is grom''gol base camp|where is rebel camp|where is zul''gurub entrance|is stv pvp|where is the zeppelin to stv|stv level range|does booty bay have an auction house|where is zg');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_badlands', 'Badlands', 'Badlands is a level 35 to 45 contested canyon zone south of Loch Modan, all red rock and dust. Kargath serves the Horde and the Dwarven District of Thelsamar supplies the Alliance side from the north. Its main feature is the entrance to Uldaman, and black dragonkin and Dark Iron dwarves contest the excavation sites.', 'badlands,kargath,uldaman entrance,angor fortress,lethlor ravine', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is badlands|where is badlands|where is uldaman entrance|where is kargath|how do i get to badlands as alliance|how do i get to badlands as horde|where is the dwarven district of thelsamar|badlands level range|what zone is south of loch modan|who fights over the badlands excavation sites|where do i level 35 to 45|where is uldaman');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_swamp_of_sorrows', 'Swamp of Sorrows', 'Swamp of Sorrows is a level 35 to 45 contested marsh east of Duskwood, sunk in permanent fog and rain. Stonard is the Horde outpost, and the Alliance has no real foothold. The Sunken Temple lies beneath the Temple of Atal''Hakkar in the north of the zone, and the Dark Portal sits just east in the Blasted Lands.', 'swamp of sorrows,stonard,sunken temple,temple of atalhakkar,misty valley,pool of tears', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is swamp of sorrows|where is swamp of sorrows|where is stonard|where is the sunken temple entrance|where is the temple of atal''hakkar|how do i get to the swamp as horde|does alliance have a base in swamp of sorrows|where is the dark portal from swamp of sorrows|swamp of sorrows level range|what zone is east of duskwood|why is swamp of sorrows foggy|where do i level 35 to 45 as horde');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_hinterlands', 'The Hinterlands', 'The Hinterlands is a level 40 to 50 contested forest north of the Plaguelands, home to the Wildhammer dwarves at Aerie Peak and the Revantusk trolls on the eastern coast. Vilebranch and Witherbark forest trolls hold most of the zone. Aerie Peak is also the entrance to Seradane and a common Alliance flight point.', 'the hinterlands,hinterlands,aerie peak,wildhammer dwarves,revantusk village,vilebranch trolls,witherbark,jintha alor', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is the hinterlands|where is the hinterlands|where is aerie peak|where are the wildhammer dwarves|where is revantusk village|where are the trolls in the hinterlands|where is the flight path at aerie peak|hinterlands level range|where is seradane|who are the vilebranch|what zone is north of the plaguelands|where do i level 40 to 50 alliance');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_searing_gorge', 'Searing Gorge', 'Searing Gorge is a level 43 to 50 contested zone of ash and open flame between the Badlands and the Burning Steppes. The Thorium Brotherhood works out of Thorium Point, and the Dark Iron dwarves hold the Slag Pit and Blackrock. It is the surface approach to Blackrock Depths and a prime mining zone for thorium.', 'searing gorge,thorium point,thorium brotherhood,the slag pit,blackrock depths approach', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is searing gorge|where is searing gorge|where is thorium point|how do i get to blackrock depths|where is the brd entrance|where is the slag pit|where do i mine thorium|where is the thorium brotherhood|searing gorge level range|what zone is between badlands and burning steppes|where do i farm thorium ore|who is the thorium brotherhood');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_blasted_lands', 'Blasted Lands', 'Blasted Lands is a level 45 to 55 contested wasteland at the southern tip of the Eastern Kingdoms, and it holds the Dark Portal to Outland. Nethergarde Keep serves the Alliance and Dreadmaul Hold the Horde. Players crossing to Outland at level 58 pass through here, so the zone stays busy well past its own level range.', 'blasted lands,dark portal,nethergarde keep,dreadmaul hold,outland entrance,portal to outland,rise of the defiler', 'zone,contested,eastern_kingdoms,leveling,outland_gateway', '', '', 'what level is blasted lands|where is blasted lands|where is the dark portal|how do i get to outland|how do i get to the dark portal|where is nethergarde keep|where is dreadmaul hold|what level do i need for outland|where do i go at level 58|blasted lands level range|what zone is at the southern tip of the eastern kingdoms|where is the portal to hellfire peninsula');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_burning_steppes', 'Burning Steppes', 'Burning Steppes is a level 50 to 58 contested zone of lava and black rock, north of Redridge and below Blackrock Mountain. Morgan''s Vigil holds the Alliance camp and Flame Crest the Horde. The zone is the front door to Blackrock Spire and Molten Core, and Dark Iron dwarves and black dragonkin patrol the roads.', 'burning steppes,morgans vigil,flame crest,blackrock mountain,blackrock spire entrance,molten core entrance', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is burning steppes|where is burning steppes|where is morgan''s vigil|where is flame crest|how do i get to blackrock spire|how do i get to molten core|where is the entrance to brs|where is the mc entrance|burning steppes level range|what zone is north of redridge|who are the dark iron dwarves at burning steppes|where do i level 50 to 58');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_western_plaguelands', 'Western Plaguelands', 'Western Plaguelands is a level 51 to 58 contested zone of Scourge-blighted farmland, with Chillwind Camp for the Alliance and the Bulwark on the Horde approach. Andorhal lies ruined at its center and Hearthglen in the north is held by the Scarlet Crusade. Scholomance sits on Caer Darrow in the southeast.', 'western plaguelands,chillwind camp,andorhal,hearthglen,caer darrow,scholomance entrance,the bulwark,wpl', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is western plaguelands|where is wpl|where is chillwind camp|where is andorhal|where is the bulwark|where is hearthglen|how do i get to scholomance|where is scholo entrance|where is caer darrow|wpl level range|who are the scarlet crusade in wpl|where do i level 51 to 58');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_eastern_plaguelands', 'Eastern Plaguelands', 'Eastern Plaguelands is a level 53 to 60 contested zone and the darkest ground in the Eastern Kingdoms, with the Argent Dawn holding Light''s Hope Chapel against the Scourge. Stratholme lies in the northwest behind its gates, and Naxxramas floated above the zone before it moved to Northrend. The plaguewood and Blackwood are thick with undead.', 'eastern plaguelands,lights hope chapel,stratholme entrance,plaguewood,corins crossing,epl', 'zone,contested,eastern_kingdoms,leveling', '', '', 'what level is eastern plaguelands|where is epl|where is light''s hope chapel|where is stratholme|how do i get to stratholme|where is strat entrance|where was naxxramas before northrend|what is the argent dawn|epl level range|where is the plaguewood|what is the blackwood|where do i level 53 to 60');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_deadwind_pass', 'Deadwind Pass', 'Deadwind Pass is a level 55 to 60 contested corridor between Duskwood and the Swamp of Sorrows, and it has almost no quests of its own. Its reason to exist is Karazhan, Medivh''s tower, which looms over the southern end of the pass and is the entry raid of the Burning Crusade.', 'deadwind pass,karazhan,medivh,medivhs tower,deadwind', 'zone,contested,eastern_kingdoms', '', '', 'what level is deadwind pass|where is deadwind pass|where is karazhan|how do i get to karazhan|where is kara entrance|where is medivh''s tower|does deadwind pass have quests|where is deadwind relative to swamp of sorrows|deadwind pass level range|what zone is between duskwood and swamp of sorrows|where is the entrance to the first burning crusade raid|how do i get to deadwind');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_isle_of_queldanas', 'Isle of Quel''Danas', 'Isle of Quel''Danas is a level 70 daily quest island north of Quel''Thalas, added at the end of the Burning Crusade. Both factions share the Shattered Sun Offensive base there, and the zone unlocks progressively through server-wide phases. It holds Magisters'' Terrace and the Sunwell Plateau raid.', 'isle of queldanas,queldanas,shattered sun offensive,sunwell plateau,magisters terrace,sunwell,quel danas', 'zone,neutral,eastern_kingdoms,endgame', '', '', 'what level is isle of quel''danas|where is quel''danas|how do i get to the sunwell|where is the sunwell plateau|where is magisters terrace|where is the shattered sun offensive base|what are the quel''danas dailies|how do i get to quel danas|where is the isle north of quel''thalas|is quel''danas for both factions|sunwell entrance where|where do i do shattered sun dailies');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_bloodmyst_isle', 'Bloodmyst Isle', 'Bloodmyst Isle is a level 10 to 20 draenei zone north of Azuremyst Isle, stained red by the crash of the Exodar. Blood Watch is the quest hub. It follows straight on from the draenei starting experience and ends around the level where players leave for Darkshore or Darnassus.', 'bloodmyst isle,bloodmyst,blood watch,exodar crash,vector coil,wrathscale naga', 'zone,alliance,kalimdor,leveling', '', '', 'what level is bloodmyst isle|where is bloodmyst|where is blood watch|where do draenei go after azuremyst|what zone is after azuremyst isle|where do i go after bloodmyst|bloodmyst level range|why is bloodmyst red|where is bloodmyst relative to the exodar|draenei quest zone 10 to 20|where do i go at level 20 as a draenei|where does the draenei questing continue');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_darkshore', 'Darkshore', 'Darkshore is a level 10 to 20 night elf zone along the western coast of Kalimdor, below Teldrassil. Auberdine is the port and quest hub, with boats to Stormwind Harbor, Rut''theran Village on Teldrassil, and Azuremyst Isle. Ruins, murlocs, and the Twilight''s Hammer occupy the coast, and Blackfathom Deeps lies at the southern end.', 'darkshore,auberdine,blackfathom deeps entrance', 'zone,alliance,kalimdor,leveling', '', '', 'what level is darkshore|where is darkshore|where is auberdine|how do i get to darkshore|where is the boat to stormwind from darkshore|where is the boat to teldrassil|where is the boat to azuremyst|where is blackfathom deeps|darkshore level range|where is bfd entrance|where do i level 10 to 20 as a nelf|where is the twilight''s hammer in darkshore');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_the_barrens', 'The Barrens', 'The Barrens is the great level 10 to 25 Horde zone across central Kalimdor, split by the Gold Road and remembered for its chat channel. Crossroads is the main quest hub, with Camp Taurajo south and Ratchet on the eastern coast as a neutral goblin port. Wailing Caverns sits in the Wailing Caverns oasis in the north.', 'the barrens,barrens,crossroads,camp taurajo,ratchet,wailing caverns entrance,gold road,barrens chat,razorfen', 'zone,horde,kalimdor,leveling', '', '', 'what level is the barrens|where is barrens|where is crossroads|where is camp taurajo|where is ratchet|where is wailing caverns|what is barrens chat|how do i get to ratchet|the barrens level range|where is the gold road|where is wc entrance|is ratchet neutral');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_stonetalon_mountains', 'Stonetalon Mountains', 'Stonetalon Mountains is a level 15 to 27 contested zone of pine ridges northwest of the Barrens. Sun Rock Retreat serves the Horde and Stonetalon Peak the Alliance. Venture Company goblins are logging the forest, which drives most of the zone''s quests, and the Charred Vale lies burnt in the south.', 'stonetalon mountains,stonetalon,sun rock retreat,stonetalon peak,charred vale,windshear crag', 'zone,contested,kalimdor,leveling', '', '', 'what level is stonetalon mountains|where is stonetalon|where is sun rock retreat|where is stonetalon peak|where is the charred vale|stonetalon level range|what are the venture company doing in stonetalon|where is stonetalon relative to the barrens|how do i get to stonetalon mountains|where do alliance quest in stonetalon|where do i go at level 15 to 27|what zone is northwest of the barrens');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_ashenvale', 'Ashenvale', 'Ashenvale is a level 18 to 30 contested night elf forest north of the Barrens, heavily fought over by Warsong loggers and the Sentinels. Astranaar is the Alliance hub and Splintertree Post the Horde''s. Blackfathom Deeps lies on its western coast and the Warsong Lumber Camp drives the faction conflict here.', 'ashenvale,astranaar,splintertree post,warsong lumber camp,silverwing', 'zone,contested,kalimdor,leveling,pvp', '', '', 'what level is ashenvale|where is ashenvale|where is astranaar|where is splintertree post|where is the warsong lumber camp|where is blackfathom deeps|is ashenvale pvp|how do i get to ashenvale|ashenvale level range|what zone is north of the barrens|who are the warsong loggers|where do i level 18 to 30 in kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_thousand_needles', 'Thousand Needles', 'Thousand Needles is a level 25 to 35 contested zone of towering mesas and dry canyons south of the Barrens. Freewind Post sits atop a mesa as the Horde hub. The Shimmering Flats in the southeast host the goblin racetrack, and centaur and Grimtotem tauren hold the canyon floor.', 'thousand needles,freewind post,shimmering flats,mirage raceway,goblin racetrack,razorfen downs', 'zone,contested,kalimdor,leveling', '', '', 'what level is thousand needles|where is thousand needles|where is freewind post|where is the shimmering flats|where is the goblin racetrack|thousand needles level range|who are the grimtotem|where is 1k needles|how do i get to thousand needles|what zone is south of the barrens|where do i go at level 25 to 35|where are the centaurs in thousand needles');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_desolace', 'Desolace', 'Desolace is a level 30 to 40 contested wasteland on Kalimdor''s western coast, grey and thinly populated. Nijel''s Point serves the Alliance and Shadowprey Village the Horde. Centaur clans war across the middle of the zone and Maraudon''s entrance lies in the Valley of Spears in the south.', 'desolace,nijels point,shadowprey village,maraudon entrance,valley of spears,kodo graveyard', 'zone,contested,kalimdor,leveling', '', '', 'what level is desolace|where is desolace|where is nijel''s point|where is shadowprey village|where is maraudon entrance|where is the valley of spears|desolace level range|how do i get to desolace|who are the centaur clans|where is desolace on the west coast|where do i go at level 30 to 40|where is mara entrance');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_dustwallow_marsh', 'Dustwallow Marsh', 'Dustwallow Marsh is a level 35 to 45 contested swamp on Kalimdor''s eastern coast, holding the Alliance city of Theramore Isle under Jaina Proudmoore and the Horde camp at Brackenwall Village. Onyxia''s Lair sits in the wyrmbog to the south, and Mudsprocket in the southwest was added as a later goblin hub.', 'dustwallow marsh,theramore isle,theramore,jaina proudmoore,brackenwall village,onyxias lair entrance,the wyrmbog,mudsprocket', 'zone,contested,kalimdor,leveling', '', '', 'what level is dustwallow marsh|where is dustwallow|where is theramore|where is brackenwall village|where is onyxia''s lair|where is mudsprocket|how do i get to onyxia''s lair|where is ony entrance|dustwallow level range|who is jaina proudmoore|how do i get to theramore|where is the horde camp in dustwallow');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_feralas', 'Feralas', 'Feralas is a level 40 to 50 contested jungle in southwestern Kalimdor, thick with yeti, ogres, and gorillas. Feathermoon Stronghold serves the Alliance from an island in the west and Camp Mojache the Horde. Dire Maul lies in the ruins of Eldre''Thalas at the center of the zone.', 'feralas,feathermoon stronghold,camp mojache,dire maul entrance,eldrethalas,gordunni ogres', 'zone,contested,kalimdor,leveling', '', '', 'what level is feralas|where is feralas|where is feathermoon stronghold|where is camp mojache|where is dire maul|how do i get to dire maul|where is dm entrance|feralas level range|how do i get to feathermoon|where is eldre''thalas|where do i level 40 to 50 in kalimdor|what mobs are in feralas');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_tanaris', 'Tanaris', 'Tanaris is a level 40 to 50 contested desert in southern Kalimdor, with the neutral goblin port of Gadgetzan as its hub and an auction house. The Caverns of Time open in the Tanaris cliffs, and Zul''Farrak lies in the northwest. Once you know its flight path, Gadgetzan connects to Orgrimmar and Thunder Bluff for the Horde and to Theramore and Thalanaar for the Alliance; on foot from Orgrimmar it is south through the Barrens and Thousand Needles. Dalaran has a portal to the Caverns of Time.', 'tanaris,gadgetzan,caverns of time,zulfarrak entrance,lost rigger cove,steamwheedle port,noggenfogger', 'zone,contested,kalimdor,leveling', '', '', 'what level is tanaris|where is tanaris|where is gadgetzan|where is zul''farrak|how do i get to zul''farrak|where are the caverns of time|how do i get to the caverns of time|where is lost rigger cove|does gadgetzan have an ah|tanaris level range|where is zf entrance|is gadgetzan neutral|how do i get to tanaris from orgrimmar|how do i get from orgrimmar to gadgetzan|how do i get to gadgetzan as horde|how do i get to gadgetzan as alliance|how do i get to tanaris from theramore|is there a flight path from orgrimmar to gadgetzan|how do i walk from orgrimmar to tanaris|how do i get to tanaris from thunder bluff|how do i get to the caverns of time from dalaran|how do i get to tanaris as alliance|how do i get to tanaris as horde|which way is tanaris from the barrens');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_azshara', 'Azshara', 'Azshara is a level 45 to 55 contested zone in northeastern Kalimdor, overgrown and lightly quested before Cataclysm reworked it. Valormok is the Horde camp and Talrendis Point the Alliance''s. Naga hold the ruins along the coast and the Timbermaw and blue dragonflight both have interests in the north.', 'azshara,valormok,talrendis point,ruins of eldarath,bay of storms,legash encampment', 'zone,contested,kalimdor,leveling', '', '', 'what level is azshara|where is azshara|where is valormok|where is talrendis point|is azshara worth questing|who are the naga in azshara|azshara level range|what zone is northeast kalimdor|is azshara a good leveling zone|where do i level 45 to 55|how do i get to azshara|who is in northern azshara');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_felwood', 'Felwood', 'Felwood is a level 48 to 55 contested zone north of Ashenvale, corrupted by demonic taint into sickly green forest. Emerald Sanctuary and Whisperwind Grove hold the Cenarion Circle''s efforts to cleanse it. Timbermaw Hold in the north is a neutral furbolg faction worth grinding for the shortcut it opens to Winterspring and Moonglade.', 'felwood,emerald sanctuary,whisperwind grove,timbermaw hold,irontree woods', 'zone,contested,kalimdor,leveling', '', '', 'what level is felwood|where is felwood|where is emerald sanctuary|where is whisperwind grove|where is timbermaw hold|how do i get to winterspring|timbermaw furbolg rep worth it|what is the timbermaw shortcut|how do i get to moonglade from felwood|felwood level range|why is felwood green|what zone is north of ashenvale|how do i get to winterspring from felwood');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_ungoro_crater', 'Un''Goro Crater', 'Un''Goro Crater is a level 48 to 55 contested prehistoric basin south of Silithus, full of devilsaurs, raptors, and elementals. Marshal''s Refuge in the middle is the neutral hub, and the crater is one of the best places in the old world for herbs, ore, and power crystals. A devilsaur will kill an unprepared player of its level range.', 'ungoro crater,ungoro,marshals refuge,devilsaur,power crystals,fire plume ridge,golakka hot springs,un goro', 'zone,contested,kalimdor,leveling', '', '', 'what level is un''goro crater|where is ungoro|where is marshal''s refuge|where do i farm devilsaurs|where do i get power crystals|good place to farm herbs ungoro|un''goro level range|how do i get to un''goro crater|where do i mine ore in ungoro|what zone is south of silithus|are devilsaurs dangerous|where do i go at level 48 to 55');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_silithus', 'Silithus', 'Silithus is a level 55 to 60 contested desert in southwestern Kalimdor, crawling with silithid and the Twilight''s Hammer cult. Cenarion Hold is the quest hub and the Cenarion Circle reputation grind runs from there. The gates of Ahn''Qiraj stand at the zone''s southern edge, opening onto the two Ahn''Qiraj raids.', 'silithus,cenarion hold,ahnqiraj gates,scarab lord', 'zone,contested,kalimdor,leveling,endgame', '', '', 'what level is silithus|where is silithus|where is cenarion hold|where is ahn''qiraj|how do i get to aq|where are the aq gates|where is the aq40 entrance|where is aq20|silithus level range|how do i do cenarion circle rep|who is the twilight''s hammer in silithus|where do i go at level 55 to 60');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_winterspring', 'Winterspring', 'Winterspring is a level 55 to 60 contested snow zone in northeastern Kalimdor, with the neutral goblin town of Everlook as its hub. Frostsabers, yeti, and chimaera roam the drifts. It holds the Frostsaber mount grind for night elves and heavy thorium and arcane crystal mining in the Mazthoril caves.', 'winterspring,everlook,frostsaber,mazthoril,starfall village', 'zone,contested,kalimdor,leveling', '', '', 'what level is winterspring|where is winterspring|where is everlook|how do i get frostsaber mount|where do i mine thorium in winterspring|where do i get arcane crystal|where is mazthoril|winterspring level range|how do i get to everlook|is everlook neutral|what mobs are in winterspring|where do i go at level 55 to 60 kalimdor');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_moonglade', 'Moonglade', 'Moonglade is a small neutral sanctuary valley in northern Kalimdor, sacred to druids and reachable by the Teleport: Moonglade spell any druid learns at level 14. Nighthaven is its only settlement, home to the Cenarion Circle and Remulos. It has no hostile mobs and no level range: druids come here for class quests and everyone else for the Lunar Festival.', 'moonglade,nighthaven,druid sanctuary,teleport moonglade,keeper remulos,timbermaw tunnel', 'zone,neutral,kalimdor,sanctuary,druid', '', '', 'where is moonglade|how do i get to moonglade|how do i teleport to moonglade|what level do druids learn teleport moonglade|where is nighthaven|where is remulos|does moonglade have mobs|can non druids go to moonglade|where is the lunar festival|what level is moonglade|where do druids do class quests|what is the moonglade teleport|is moonglade safe');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_hellfire_peninsula', 'Hellfire Peninsula', 'Hellfire Peninsula is the level 58 to 63 entry zone of Outland, the red broken land on the far side of the Dark Portal. Honor Hold serves the Alliance and Thrallmar the Horde. Hellfire Citadel sits at the center with Ramparts, Blood Furnace, Shattered Halls, and Magtheridon''s Lair, and the zone has a heavy world PvP presence around its towers.', 'hellfire peninsula,hellfire,honor hold,thrallmar,dark portal,hellfire citadel,ramparts,blood furnace,magtheridon', 'zone,contested,outland,leveling', '', '', 'what level is hellfire peninsula|where is hellfire|how do i start outland|where is honor hold|where is thrallmar|where is hellfire citadel|where are ramparts and blood furnace|where is magtheridon''s lair|what is the first zone in outland|is hellfire peninsula pvp|hellfire level range|where do i go after the dark portal|hellfire pen quests|where is shattered halls');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_zangarmarsh', 'Zangarmarsh', 'Zangarmarsh is a level 60 to 64 Outland zone of giant mushrooms and standing water, home to the Cenarion Expedition at Cenarion Refuge and the sporeggar mushroom folk. Telredor serves the Alliance and Zabra''jin the Horde. The Coilfang Reservoir instances, including Slave Pens, Underbog, Steamvault, and Serpentshrine Cavern, all open here.', 'zangarmarsh,cenarion expedition,sporeggar,telredor,zabrajin,coilfang reservoir,slave pens,underbog,steamvault,serpentshrine cavern', 'zone,contested,outland,leveling', '', '', 'what level is zangarmarsh|where is zangarmarsh|where is cenarion refuge|where is telredor|where is zabra''jin|where is coilfang reservoir|where are slave pens and underbog|where is steamvault|where is serpentshrine cavern|what is sporeggar|where do i get cenarion expedition rep|zangar level range|zangarmarsh quest hubs|what are the giant mushroom zone');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_terokkar_forest', 'Terokkar Forest', 'Terokkar Forest is a level 62 to 65 Outland zone of tall bone-white trees, and it surrounds Shattrath City. Allerian Stronghold serves the Alliance and Stonebreaker Hold the Horde. Auchindoun sits in the Bone Wastes at its center with four wings, and the Skettis arakkoa hold the southeast.', 'terokkar forest,terokkar,shattrath,allerian stronghold,stonebreaker hold,auchindoun,bone wastes,skettis,lower city', 'zone,contested,outland,leveling', '', '', 'what level is terokkar forest|where is terokkar|where is shattrath in terokkar|where is allerian stronghold|where is stonebreaker hold|where is auchindoun|where is the bone wastes|who are the skettis|terokkar level range|where do arakkoa live in terokkar|terokkar quest hubs|where is skettis|what zone surrounds shattrath|how many wings does auchindoun have');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_nagrand', 'Nagrand', 'Nagrand is a level 64 to 67 Outland zone of green plains and floating islands, widely considered the best-looking zone of the Burning Crusade. Telaar serves the Alliance and Garadar the Horde, and the Mag''har orcs quest chain runs from Garadar. Halaa in the center is a world PvP objective, and the Ring of Blood is a well-known group quest gauntlet.', 'nagrand,telaar,garadar,maghar orcs,halaa,ring of blood,throne of the elements', 'zone,contested,outland,leveling,pvp', '', '', 'what level is nagrand|where is nagrand|where is telaar|where is garadar|what is the best zone in outland|what is the ring of blood|where is halaa|is halaa pvp|nagrand level range|where do mag''har orcs quest|best looking zone in tbc|what are the floating islands in nagrand|nagrand quest hubs|where do i go at level 64 to 67');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_blades_edge_mountains', 'Blade''s Edge Mountains', 'Blade''s Edge Mountains is a level 65 to 68 Outland zone of jagged spires, ogre holds, and dragon bones driven into the rock. Sylvanaar serves the Alliance and Thunderlord Stronghold the Horde. Gruul''s Lair opens in the northwest and the Ogri''la plateau in the east unlocks daily quests at level 70.', 'blades edge mountains,blades edge,sylvanaar,thunderlord stronghold,gruuls lair,ogrila,bladespire,skyguard', 'zone,contested,outland,leveling', '', '', 'what level is blade''s edge mountains|where is blade''s edge|where is sylvanaar|where is thunderlord stronghold|where is gruul''s lair|where is ogri''la|what are the ogri''la dailies|bem level range|where are the ogre holds|where do i do dailies at 70 in blade''s edge|blades edge quest hubs|where is the plateau in the east of bem|where do i go at level 65 to 68');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_netherstorm', 'Netherstorm', 'Netherstorm is a level 67 to 70 Outland zone of shattered floating landmass and arcane storms in the northeast. Area 52 is the neutral goblin hub, and the Consortium and Kirin Tor both operate here. Tempest Keep, with the Arcatraz, Botanica, Mechanar, and Eye, sits at the zone''s western edge as Kael''thas Sunstrider''s stronghold.', 'netherstorm,area 52,tempest keep,arcatraz,botanica,mechanar,the eye,kaelthas sunstrider,manaforge', 'zone,contested,outland,leveling,endgame', '', '', 'what level is netherstorm|where is netherstorm|where is area 52|where is tempest keep|where is the arcatraz|where is botanica|where is the mechanar|where is the eye|where is kael''thas|netherstorm level range|what is the consortium in netherstorm|where is netherstorm in outland|where do i go at level 67 to 70|who are the kirin tor in netherstorm');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_shadowmoon_valley', 'Shadowmoon Valley', 'Shadowmoon Valley is a level 67 to 70 Outland zone of black rock and lava in the southeast, and the last leveling zone of the Burning Crusade. Wildhammer Stronghold serves the Alliance and Shadowmoon Village the Horde. The Black Temple, Illidan Stormrage''s fortress, dominates the middle of the zone, and the Netherwing ledge offers drake mount dailies at level 70.', 'shadowmoon valley,black temple,illidan stormrage,wildhammer stronghold,shadowmoon village,netherwing ledge,netherwing drake,altar of sha,coilskar', 'zone,contested,outland,leveling,endgame', '', '', 'what level is shadowmoon valley|where is shadowmoon valley|where is wildhammer stronghold|where is shadowmoon village|where is the black temple|where is illidan|what is the last leveling zone in tbc|where do i get the netherwing drake mount|what are netherwing dailies|smv level range|where is the netherwing ledge|where do i go at level 67 to 70 in outland|shadowmoon quest hubs');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_dragonblight', 'Dragonblight', 'Dragonblight is a level 71 to 74 Northrend zone at the center of the continent, where dragons come to die. Wintergarde Keep serves the Alliance and Agmar''s Hammer the Horde, with the neutral Wyrmrest Temple rising at the middle. Azjol-Nerub and the Old Kingdom open in the north, Naxxramas floats in the northeast, and the Wrathgate questline plays out here.', 'dragonblight,wyrmrest temple,wintergarde keep,agmars hammer,azjolnerub,old kingdom,naxxramas entrance,wrathgate,dragon graveyard', 'zone,contested,northrend,leveling', '', '', 'what level is dragonblight|where is dragonblight|where is wintergarde keep|where is agmar''s hammer|where is wyrmrest temple|where is azjol-nerub|where is naxxramas in northrend|where is the wrathgate|dragonblight level range|where do i go after borean tundra|where is the old kingdom entrance|what zone has the wrathgate quest|dragonblight quest hubs|where do i go at level 71 to 74');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_grizzly_hills', 'Grizzly Hills', 'Grizzly Hills is a level 73 to 75 Northrend zone of dense pine forest and logging camps, known for its music. Amberpine Lodge serves the Alliance and Conquest Hold the Horde. The Drakkari trolls, the Venture Company, and the worgen of Grizzlemaw drive most of the questing, and Drak''Tharon Keep sits on the border with Zul''Drak.', 'grizzly hills,amberpine lodge,conquest hold,grizzlemaw,draktharon keep', 'zone,contested,northrend,leveling', '', '', 'what level is grizzly hills|where is grizzly hills|where is amberpine lodge|where is conquest hold|where is drak''tharon keep|what zone has the best music in northrend|who are the drakkari in grizzly hills|grizzly hills level range|what are the worgen at grizzlemaw|what zone borders zul''drak|where do i go at level 73 to 75|grizzly hills quest hubs|where is datk entrance');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_zuldrak', 'Zul''Drak', 'Zul''Drak is a level 74 to 76 Northrend zone, the ice troll homeland, where the Drakkari are killing their own gods for power. The Argent Crusade holds Light''s Breach and the Ebon Blade operates at Ebon Watch. Gundrak sits at the northern end of the zone, and the Amphitheater of Anguish runs a well-known gauntlet of group quests.', 'zuldrak,drakkari,gundrak,lights breach,ebon watch,amphitheater of anguish,zul drak', 'zone,contested,northrend,leveling', '', '', 'what level is zul''drak|where is zul''drak|where is light''s breach|where is ebon watch|where is gundrak|what is the amphitheater of anguish|where do i go at level 74 to 76|zul''drak level range|who are the drakkari|what are the ice trolls doing in zul''drak|zuldrak quest hubs|where is the troll zone in northrend|where do i do group quests in zul''drak');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_sholazar_basin', 'Sholazar Basin', 'Sholazar Basin is a level 76 to 78 Northrend zone, a tropical valley sealed inside the ice and untouched by the Lich King. Nesingwary''s camp runs the hunting quests, and the Oracles and the Frenzyheart Tribe are opposed reputations: siding with one locks out the other, and each offers its own dailies and pets.', 'sholazar basin,sholazar,the oracles,frenzyheart tribe,nesingwary', 'zone,neutral,northrend,leveling', '', '', 'what level is sholazar basin|where is sholazar|who are the oracles and frenzyheart|oracles or frenzyheart which one|can i do both frenzyheart and oracles|where is nesingwary''s camp|how do i get pets from sholazar|what are the sholazar dailies|sholazar level range|where do i go at level 76 to 78|where is the tropical zone in northrend|what is the sealed valley in northrend|sholazar rep choice');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_storm_peaks', 'The Storm Peaks', 'The Storm Peaks is a level 76 to 80 Northrend zone of high mountains and titan architecture, home to the Sons of Hodir. Flight masters at K3, Dun Niffelem, Bouldercrag''s Refuge and Ulduar serve both factions; Frosthold is Alliance only, and Camp Tunka''lo and Grom''arsh Crash-Site are Horde only. Dalaran flies straight to K3, the goblin hub. Sons of Hodir reputation is the only source of shoulder enchants in Wrath, and Ulduar opens at the northern end of the zone.', 'the storm peaks,storm peaks,sons of hodir,dun niffelem,k3,ulduar entrance,brunnhildar,shoulder enchants,hyldnir', 'zone,contested,northrend,leveling,endgame', '', '', 'what level is the storm peaks|where is storm peaks|where is k3|where is dun niffelem|where is ulduar|how do i get to ulduar|how do i get shoulder enchants|where do i get sons of hodir rep|who are the sons of hodir|storm peaks level range|where are the titan ruins in northrend|where do i go at level 76 to 80|uld entrance where|does the storm peaks have flight paths|are there flight masters in the storm peaks|how do i get to the storm peaks|how do i get to k3|where are the flight paths in the storm peaks|how do i get to ulduar from dalaran|is there a flight path to ulduar|what flight paths do horde have in the storm peaks|what flight paths do alliance have in the storm peaks|how do i get to frosthold|how do i get to dun niffelem|where is the flight master in k3');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_icecrown', 'Icecrown', 'Icecrown is the level 77 to 80 Northrend zone below the Lich King''s fortress, and the last leveling zone of Wrath. The Argent Crusade, the Knights of the Ebon Blade, and the Alliance and Horde all hold camps here, and the Argent Tournament grounds run mounted dailies and host the Trial of the Crusader. Icecrown Citadel is a separate level 80 raid with the Lich King at its top. No flight path lands at its door; Dalaran flies to Crusaders'' Pinnacle, the Argent Tournament Grounds and the Argent Vanguard, and you ride or fly on from there.', 'icecrown,icecrown citadel,lich king,knights of the ebon blade,trial of the crusader,shadow vault', 'zone,contested,northrend,leveling,endgame', '', '', 'what level is icecrown|where is icecrown|where is icecrown citadel|where is icc|where is the argent tournament|where is trial of the crusader|where is toc|where are the argent tournament dailies|what is the last leveling zone in wrath|icecrown level range|where is the lich king''s fortress|where do i go at level 77 to 80|icecrown quest hubs|where is the argent crusade camp|how do i get to icecrown|how do i get to icecrown citadel|how do i get to the top of icc|how do i get to the lich king|how do i get to icc from dalaran|is there a flight path to icecrown citadel|what level do i need for icecrown citadel|where is the entrance to icc|how do i get to the argent tournament|where do i fly for icc|can i walk to icecrown citadel');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_crystalsong_forest', 'Crystalsong Forest', 'Crystalsong Forest is a level 77 to 80 Northrend zone of crystalline trees at the center of the continent, directly beneath the floating city of Dalaran. It has very few quests of its own and exists mostly as the approach to Dalaran and a passage between Dragonblight, Zul''Drak, and the Storm Peaks.', 'crystalsong forest,crystalsong,crystalline trees,windrunners overlook,sunreavers command', 'zone,contested,northrend', '', '', 'what level is crystalsong forest|where is crystalsong|where is dalaran|how do i get to dalaran|what is under dalaran|does crystalsong have quests|crystalsong level range|how do i get from dragonblight to the storm peaks|how do i get to zul''drak|where is the crystal forest|what zone is dalaran floating over|how do i get to dalaran on foot|where do i go at level 77 to 80');
INSERT INTO `hside_rag` (`id`, `title`, `content`, `keywords`, `tags`, `expert_domain`, `expert_content`, `questions`) VALUES ('zone_wintergrasp', 'Wintergrasp', 'Wintergrasp is a level 77 to 80 Northrend zone that is an open world PvP battleground rather than a leveling zone. The factions fight over the fortress with siege vehicles and destructible walls; the holder gets the Vault of Archavon and a damage buff, and the loser is locked out of both until the next battle. Dalaran flies to Valiance Landing Camp (Alliance) or Warsong Camp (Horde) and has a Wintergrasp portal in each faction''s enclave. On this realm a battle lasts 30 minutes with 150 minutes between battles, and joining needs level 75.', 'wintergrasp,wintergrasp fortress,vault of archavon,tenacity,pvp zone', 'zone,contested,northrend,pvp,endgame', '', '', 'what level is wintergrasp|where is wintergrasp|what is wg|how does wintergrasp work|how do i get into the vault of archavon|where is vault of archavon|what does winning wintergrasp give|is wintergrasp a battleground|wg timer how often|who owns wintergrasp|what happens if i lose wintergrasp|what are siege vehicles in wg|wintergrasp fortress where|is wg open world pvp|how do i get to wintergrasp from dalaran|is there a flight path to wintergrasp|is there a portal to wintergrasp|how do i get to wg|where is the wg portal in dalaran|how often is wintergrasp|how long does a wintergrasp battle last|what level do i need for wintergrasp|what level do i need for wg|how do i join wintergrasp|when is the next wintergrasp battle|wg level req|wg level|wg timer|when is wg|wg time|wintergrasp lvl|how long is wg|wg portal|wg battle length|wg vault of archavon|what is wintergrasp for|can i join wg at 75|wintergrasp how often|wg when does it start');
